window.__ARXIV_DATA__ = {"papers":[{"id":"2610.18874v1","title":"ChunkAct: Action Chunking for Agentic Robotics","abstract":"Agentic robotics places a large language model (LLM) agent in the robot control loop, where it composes perception, motion, and vision-language-action (VLA) tools under the guidance of a memory and thereby generalizes to new tasks without retraining. This generality comes at a steep price in efficiency. Every primitive requires a round of LLM reasoning over the full interaction history, so the cost of an episode grows with the number of primitives. We find this reasoning largely redundant: once a sub-goal is chosen, its primitives follow a routine already prescribed by memory. We present ChunkAct, which introduces action chunking to agentic robotics. Online, a single call launches a chunk of chained primitives, which executes autonomously and returns control only upon failure. Offline, ChunkAct compiles the memory into these chunks, so execution is memory-free at test time and the planner is reserved for decisions that require reasoning. LLM computation therefore scales with the number of decisions rather than the number of primitives. On LIBERO-Pro, ChunkAct improves task success by 5.0 points over the state of the art in agentic robotics while requiring 2.9x fewer LLM calls, 4.4x fewer input tokens, and 2.3x fewer output tokens.","authors":["Bingxin Xu","Wenrui Bao","Xinxin Liu","Jiawei Zhou","Yuzhang Shang","Emilio Ferrara"],"published":"2026-10-13T17:59:57Z","updated":"2026-10-13T17:59:57Z","abstract_url":"https://arxiv.org/abs/2610.18874v1","html_url":"https://arxiv.org/html/2610.18874v1","pdf_url":"https://arxiv.org/pdf/2610.18874v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":55001,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Agentic robotics places a large language model (LLM) agent in the robot control loop, where it composes perception, motion, and vision-language-action (VLA) tools under the guidance of a memory and thereby generalizes to new tasks without retraining. This gen...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18873v1","title":"LoopWAM: Closed-Loop Generalist Policy Improvement from Deployment Rollouts","abstract":"Scaling expert demonstrations alone does not enable generalist robot policies to improve from deployment. Real-world rollouts contain successes, suboptimal behavior, and failures: imitating every recorded action can reinforce poor behavior, while filtering out failures discards evidence of physical interactions and their consequences. We introduce \\textbf{LoopWAM}, a closed-loop world-action model that learns directly from this full quality spectrum, using rollouts from both itself and other deployed policies. Source-dependent noise sampling unifies behavior learning and action-conditioned world modeling, while quality steering and quality-weighted supervision retain full video supervision across qualities and regulate action imitation. Video and action tokens interact throughout parallel denoising, allowing learned consequences to inform action generation directly. On RoboChallenge Table30-V2, three deployment-and-training rounds raise success from 23.67\\% to 43.33\\%, a 19.7-percentage-point gain, with a final score of 56.80. LoopWAM also achieves 94.5\\% average success on RoboTwin~2.0 and 49.5\\% overall success on RoboCasa365 without additional embodied pretraining, obtaining the best overall results among the compared methods across all three benchmarks. On challenging shirt folding task, two rounds of deployment-driven improvement after single-task post-training raise success from 13.20\\% to 55.56\\%. These results demonstrate closed-loop improvement from mixed-quality experience under both multi-task learning and single-task post-training. \\href{https://loop-wam.github.io/}{\\textcolor{orange}{Project Page}}","authors":["Wenxuan Guo","Yingping Liang","Zhaoguo Wang","Ziyuan Li","Angyuan Ma","Zhenyu Wu","Chengkun Wang","Bingyao Yu","Ze Chen","Borui Zhang","Xiuwei Xu","Meng Zhang","Erjin Zhou","Jiwen Lu"],"published":"2026-10-13T17:59:56Z","updated":"2026-10-13T17:59:56Z","abstract_url":"https://arxiv.org/abs/2610.18873v1","html_url":"https://arxiv.org/html/2610.18873v1","pdf_url":"https://arxiv.org/pdf/2610.18873v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":59748,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Scaling expert demonstrations alone does not enable generalist robot policies to improve from deployment. Real-world rollouts contain successes, suboptimal behavior, and failures: imitating every recorded action can reinforce poor behavior, while filtering ou...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18872v1","title":"EgoExplorer: A Vision-Motion-Touch Observatory for Human Loco-Manipulation In Situ","abstract":"Learning humanoid loco-manipulation from human demonstrations rests on observing how locomotion, posture, and object interaction evolve together as tasks unfold. Scaling collection across diverse environments, in turn, favors lightweight, portable capture systems. Yet, existing datasets provide only partial views of this coordination. Thus, we introduce EgoExplorer, a 100-hour vision-motion-touch observatory of human loco-manipulation built with a wearable system. With an emphasis on professional activities, its continuous recordings align egocentric video with reconstructed whole-body motion, fine-grained finger articulation, and tactile observations, accompanied by step-level descriptions. To achieve this coverage with sparse body sensing, we develop the Calibrate-Complete-Constrain pipeline. Concretely, reusable calibration fixes participant geometry and sensor attachments before motion inference to disentangle mounting offsets from articulation. A temporal prior then completes unobserved joint motion, while layered constraints promote measurement agreement, temporal continuity, and geometric consistency, properties that motion plausibility alone does not guarantee. Against tracker-fitted references, the method reduces body-point error by 71.9% relative to the strongest baseline; matched evaluations also show gains in hand stability and contact estimation. Preliminary studies explore multimodal generation and conditioning alongside humanoid retargeting with whole-body control in simulation.","authors":["Yunsong Zhou","Xuekun Jiang","Haiqi Shen","Hangxu Liu","Chaojian Shi","Yujie Liu","Jingyuan Li","Haoran Yang","Jiafei Cao","Dongzhan Zhou","Dong Wang","Yao Mu","Chunhua Shen","Weinan Zhang"],"published":"2026-10-13T17:59:55Z","updated":"2026-10-13T17:59:55Z","abstract_url":"https://arxiv.org/abs/2610.18872v1","html_url":"https://arxiv.org/html/2610.18872v1","pdf_url":"https://arxiv.org/pdf/2610.18872v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":138789,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Learning humanoid loco-manipulation from human demonstrations rests on observing how locomotion, posture, and object interaction evolve together as tasks unfold. Scaling collection across diverse environments, in turn, favors lightweight, portable capture sys...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18870v1","title":"Dog-Breed Text-to-image Flow Matching from Pretraining to Fine-Tuning on 4 Consumer GPUs","abstract":"We generally perceive that training text-to-image diffusion models requires heavy compute: it is true if we aim at a comprehensive frontier model. This understanding prevents people from training their own models when getting started in the field. We develop MiniDog, a framework that enables pretraining diffusion transformers in 55 minutes and fine-tuning in another 15 minutes on four 3090 GPUs. For data, we use 26k dog images from ImageNet and caption them for pretraining and use 2k images generated by FLUX.1-schnell for fine-tuning. We precompute the image and text features and cache them for efficiency. For architecture, we use E2E-INVAE for its semantic latent space, a small transformer with 22M parameters, a small Qwen model for text encoding, and in-context conditioning. For training, we use iREPA and an EUPE perception encoder for acceleration. For evaluation, our repository supports FID, HPSv2 score, PickScore, and various VAE reconstruction metrics.","authors":["Reyhaneh Esmailizadeh","Xingjian Leng","Zhanhao Liang","Liang Zheng"],"published":"2026-10-13T17:59:53Z","updated":"2026-10-13T17:59:53Z","abstract_url":"https://arxiv.org/abs/2610.18870v1","html_url":"https://arxiv.org/html/2610.18870v1","pdf_url":"https://arxiv.org/pdf/2610.18870v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":30920,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：We generally perceive that training text-to-image diffusion models requires heavy compute: it is true if we aim at a comprehensive frontier model. This understanding prevents people from training their own models when getting started in the field. We develop...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18871v1","title":"Cepheid: Decoupling Scale from Structure for Cross-Family Motion Completion","abstract":"Sparse-to-dense motion completion recovers dense mesh motion from sparse vertex displacements. Residual priors trained on one geometry family frequently fail to beat parameter-free harmonic extension off-family. Moreover, cross-family training meets a scaling barrier: residual amplitude varies by more than an order of magnitude across geometry families and collapses as observations become denser. Since this scale depends on unknown target motion, it cannot be measured directly at test time. We decouple residual structure from physical scale by learning a dimensionless prior, estimating amplitude from observables and a lightweight correction fitted only on training sources. Our unified model surpasses harmonic extension across all evaluated families, including unseen cloth and legged bodies, without skeletons, registration, or cross-mesh correspondence. The same prior applies without retraining to point-tracked animal video and a robot grasping a soft body. Project page: https://su-terry.github.io/cepheid-website/","authors":["Chih-Hai Su","Tsung-Wei Ke","Yu-Lun Liu"],"published":"2026-10-13T17:59:53Z","updated":"2026-10-13T17:59:53Z","abstract_url":"https://arxiv.org/abs/2610.18871v1","html_url":"https://arxiv.org/html/2610.18871v1","pdf_url":"https://arxiv.org/pdf/2610.18871v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":120475,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Sparse-to-dense motion completion recovers dense mesh motion from sparse vertex displacements. Residual priors trained on one geometry family frequently fail to beat parameter-free harmonic extension off-family. Moreover, cross-family training meets a scaling...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18868v1","title":"Tev: Scaling Long-Horizon Agentic Environments with Dense Progress Rewards","abstract":"Long-horizon agents have drawn growing attention for their ability to work autonomously -- from hours to days -- on economically valuable tasks, a capability essential to automated discovery and recursive self-improvement (RSI). Yet open-source models still struggle on long-horizon tasks, largely for lack of both training data and a working recipe, and scaling both is hard: long, complex tasks are difficult to curate and verify, and their rewards are sparse. We address both. First, we introduce Tev-Gym, the first long-horizon agent training dataset with verifiable, dense, progressive rewards -- 1,170 verified task environments across 7 domains. It is built on a latent-world-first approach that first constructs a latent world: a complete and correct hidden specification of the task domain, workflow, and expected state after each step. Each task is then progressively rendered from this specification into an agent-facing environment, enabling controllable complexity and a natural progress metric. Second, we turn this metric into a training recipe: via progress-potential reward shaping (PPRS), we convert progress into a dense per-step reward that improves training efficiency and makes otherwise-intractable tasks trainable. Training with this recipe yields Tev-27B, which achieves substantial gains on the Agents' Last Exam computing and math sciences domains (ALE-CM), matching GPT-6 Astra and Claude Opus 5 at Pass@5. Despite training only on ALE-related data, it generalizes to the Terminal-Bench (TB) 3.0 and 4.0 subsets, surpassing GLM 5.2 and Gemini 3.7 Flash, and reaches Claude Opus 4.8-level performance on middle-horizon tasks such as TB 2.1.","authors":["Wenbo Hu","Shraman Pramanick","Krishna Kumar Singh","Nanyun Peng","Kai-Wei Chang","Yong Jae Lee"],"published":"2026-10-13T17:59:51Z","updated":"2026-10-13T17:59:51Z","abstract_url":"https://arxiv.org/abs/2610.18868v1","html_url":"https://arxiv.org/html/2610.18868v1","pdf_url":"https://arxiv.org/pdf/2610.18868v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":173556,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Long-horizon agents have drawn growing attention for their ability to work autonomously -- from hours to days -- on economically valuable tasks, a capability essential to automated discovery and recursive self-improvement (RSI). Yet open-source models still s...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18858v1","title":"Visual Tokens on Demand: Visual Budgeting for Scalable and Efficient Multi-Image Reasoning in Multimodal LLMs","abstract":"Multimodal large language models have advanced rapidly, but most remain optimized for single-image inputs. Multi-image reasoning is costly because each image adds many visual tokens, increasing encoding and attention demands. Existing techniques that address the above issue, including visual token pruning, token merging, visual token compression, learned resampling, hierarchical compression, retrieval-augmented visual reasoning, and memory-based architectures, have largely been designed for single-image scenarios, where redundancy is primarily spatial and local. Multi-image reasoning introduces additional challenges: redundancy may occur across images, task-relevant evidence may be sparse or distributed, and aggressive per-image compression can remove details needed for comparison, counting, temporal reasoning, retrieval, or evidence grounding. Moreover, existing token-reduction methods are often either (i) training-free but inference-inefficient, typically relying on accessing attention matrices to get token-importance that may be impractical to access with memory-efficient attention implementations such as FlashAttention, or (ii) training-dependent, requiring the base MLLM to be retrained or adapted to a new compressed-token paradigm. In this work, we study scalable multi-image reasoning and understanding without retraining the base model and without accessing attention matrices at inference time. To this end, we propose mmVB, a lightweight plug-and-play module that assigns query-conditioned per-image token budgets via cross-image context, adding only 1.6M trainable parameters while reducing visual input tokens by 9x. This reduction yields 5x faster time-to-first-token and 7x fewer prefill FLOPs, while maintaining 94.4% of full-resolution accuracy across eight multi-image reasoning benchmarks.","authors":["Aimon Rahman","Joymallya Chakraborty","Vidit Bansal","Abhishek Dan"],"published":"2026-10-13T17:59:24Z","updated":"2026-10-13T17:59:24Z","abstract_url":"https://arxiv.org/abs/2610.18858v1","html_url":"https://arxiv.org/html/2610.18858v1","pdf_url":"https://arxiv.org/pdf/2610.18858v1.pdf","matched_keywords":["retrieval","multimodal"],"source_used":"html","source_text_chars":59105,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models have advanced rapidly, but most remain optimized for single-image inputs. Multi-image reasoning is costly because each image adds many visual tokens, increasing encoding and attention demands. Existing techniques that address...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18857v1","title":"PixelMoE: Scaling Pixel-Space Diffusion with LLM-Style Mixture-of-Experts","abstract":"Pixel-space diffusion models provide an appealing alternative to latent-space diffusion models by directly modeling raw images without relying on a learned tokenizer. However, scaling pixel-space models has predominantly followed dense strategies, tightly coupling model capacity with active computation. In this work, we show that standard LLM-style Mixture-of-Experts (MoE) architectures can be effectively transferred to pixel-space diffusion. Building on this finding, we introduce PixelMoE, a pixel-space generative framework that sparsely scales model capacity with standard LLM-style MoE, without diffusion-specific routing mechanisms or auxiliary routing objectives. Specifically, PixelMoE combines standard Token-Choice (TC) routing with fine-grained routed experts for input-adaptive sparse computation, a shared expert for capturing common representations, and a bias-based load-balancing strategy. To complement sparse capacity scaling, PixelMoE further introduces Pixel-Space Hierarchical Flow Matching, which varies spatial resolution along the denoising trajectory from global structure formation to fine-grained detail refinement. At comparable active parameter counts, PixelMoE consistently outperforms its dense counterparts across model scales, demonstrating effective sparse capacity scaling in pixel space. On class-conditional ImageNet-1K, PixelMoE achieves FID scores of 1.47 at 256x256 and 1.53 at 512x512 without representation alignment or perceptual losses, comparing favorably with leading pixel-space and latent-space generative models. Code and models will be released soon.","authors":["Ruixiao Dong","Jianmin Bao","Bozhi Luan","Zijie Meng","Xin Tao","Pengfei Wan","Kun Gai","Li Li","Houqiang Li"],"published":"2026-10-13T17:59:21Z","updated":"2026-10-13T17:59:21Z","abstract_url":"https://arxiv.org/abs/2610.18857v1","html_url":"https://arxiv.org/html/2610.18857v1","pdf_url":"https://arxiv.org/pdf/2610.18857v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":92678,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Pixel-space diffusion models provide an appealing alternative to latent-space diffusion models by directly modeling raw images without relying on a learned tokenizer. However, scaling pixel-space models has predominantly followed dense strategies, tightly cou...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18846v1","title":"WorldRecon: Generative Multi-View Mesh Reconstruction for Large-Scale 3D World","abstract":"Reconstructing complete, high-quality meshes of large-scale scenes from unposed multi-view images requires faithful geometric grounding while plausibly completing surfaces that are unobserved or only sparsely captured. We present WorldRecon, a generative multi-view reconstruction framework for recovering complete, large-scale 3D scene meshes from unposed RGB images. WorldRecon uses a coarse, noisy global point cloud and camera poses estimated from the input images by a reconstruction model as a global scaffold for whole-scene generation and partitions it into overlapping spatial blocks. To robustly leverage these imperfect geometric priors, we equip the native 3D generative model TRELLIS.2 with a dedicated reconstruction-based conditioning architecture that generates each block from its local point-cloud crop and block-relevant image observations, producing sparse structure, detailed geometry, and PBR materials. To maintain scene-level coherence, we introduce neighbour-aware latent inpainting and a causal world-generation procedure that propagates structural, geometric, and material context across overlapping blocks. Together, these designs scale multi-view generative reconstruction to large-scale scenes, yielding coherent, unified meshes. Extensive experiments demonstrate that WorldRecon achieves state-of-the-art reconstruction performance, reducing Chamfer distance by 14.9% and 43.1% while improving F-score by 17.3% and 12.0% over the strongest baselines on synthetic and real-world indoor scenes, respectively, thereby demonstrating faithful and complete generative reconstruction as well as strong sim-to-real generalization. Project page: https://kszpxxzmc.github.io/WorldRecon-website/.","authors":["Mengchen Zhang","Yang Li","Chunshi Wang","Tong Wu","Chunchao Guo"],"published":"2026-10-13T17:57:58Z","updated":"2026-10-13T17:57:58Z","abstract_url":"https://arxiv.org/abs/2610.18846v1","html_url":"https://arxiv.org/html/2610.18846v1","pdf_url":"https://arxiv.org/pdf/2610.18846v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":85783,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Reconstructing complete, high-quality meshes of large-scale scenes from unposed multi-view images requires faithful geometric grounding while plausibly completing surfaces that are unobserved or only sparsely captured. We present WorldRecon, a generative mult...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18845v1","title":"The Last Remote Sensing Model Built by Humans? Casting Any Earth Observation Task as Recursive Self-Improvement","abstract":"Earth observation (EO) models are still built by hand. For each new task, experts design a training recipe and tune it against a benchmark. We show that this loop can be handed to an agent. Any verifiable task can be cast as a harness and a verifier, where the harness defines what the agent may use and the verifier defines what counts as success. Every EO task can be made verifiable, through labeled benchmarks, independent sensors, physical models or the repeated observation of the same place. Given only these two components, a general-purpose coding agent builds the EO model and improves it recursively on its own outputs. Settings long treated as separate research problems, from learning with a handful of labels to adapting across domains, become choices of harness and verifier. On four EO benchmarks spanning optical, SAR and multispectral time-series imagery, agent-built models surpass the state of the art and keep most of that accuracy from about 1% of the training labels. This establishes a new paradigm for EO, in which people design harnesses and verifiers and agents build the models, so EO models improve as agents do.","authors":["Sijie Zhao","Zeqi Zhou","Heli Qi","Xuanchao Fu","Zhuo Zheng","Junshi Xia","Junjue Wang","Weihao Xuan","Naoto Yokoya"],"published":"2026-10-13T17:57:51Z","updated":"2026-10-13T17:57:51Z","abstract_url":"https://arxiv.org/abs/2610.18845v1","html_url":"https://arxiv.org/html/2610.18845v1","pdf_url":"https://arxiv.org/pdf/2610.18845v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":81117,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Earth observation (EO) models are still built by hand. For each new task, experts design a training recipe and tune it against a benchmark. We show that this loop can be handed to an agent. Any verifiable task can be cast as a harness and a verifier, where th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18844v1","title":"RepProbe: Can Video Language Models Count Repeated Actions? A Diagnostic Benchmark","abstract":"Repetition counting requires identifying and enumerating action cycles over time. While state-of-the-art video language models describe actions fluently, they fail to reliably count how many times an action repeats. To investigate this limitation, we introduce RepProbe, a benchmark of 42K real and synthetic video clips containing exactly k in [1, 20] complete repetitions, with controls for clip position, temporal coverage, and duration. These controls allow us to study the counting failure directly and locate where in the model it arises. Counting accuracy collapses at high counts across the video language models we evaluate, and controlled experiments show this collapse is not explained by frame sampling alone. We compare model outputs with linear probes trained on the final-layer representations used to generate those outputs. We find a consistent representation-to-output dissociation: substantial count information remains linearly decodable even when models fail to report the correct count. Further analysis shows this failure arises primarily at the output stage, where answers concentrate on a small set of preferred numbers rather than the available count information. The dissociation holds on both real and synthetic videos and is not explained by clip duration, position, or scene content. These results indicate that models encode repetition structure but do not reliably report it in their outputs. Project page: https://arenaa.github.io/RepProbe-webpage/","authors":["Mahsa Khoshnoodi","Sarah Adel Bargal"],"published":"2026-10-13T17:57:43Z","updated":"2026-10-13T17:57:43Z","abstract_url":"https://arxiv.org/abs/2610.18844v1","html_url":"https://arxiv.org/html/2610.18844v1","pdf_url":"https://arxiv.org/pdf/2610.18844v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":57719,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Repetition counting requires identifying and enumerating action cycles over time. While state-of-the-art video language models describe actions fluently, they fail to reliably count how many times an action repeats. To investigate this limitation, we introduc...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18829v1","title":"OmniCompass: A Holistic Benchmark for Omni-Modal Video Grounding and Understanding","abstract":"With the rapid development of multimodal large language models (MLLMs), evaluating their video understanding capabilities has become increasingly important. Existing video understanding benchmarks cover only part of the evaluation dimensions, limiting systematic diagnosis of omni-modal video understanding. We introduce OmniCompass, a holistic benchmark for omni-modal video grounding and understanding. OmniCompass defines two evaluation tracks: OmniCompass-VL assesses vision-language models on tasks requiring visual evidence, while OmniCompass-AV assesses omni-modal models on tasks requiring joint audio-visual evidence. Each track includes three complementary tasks: temporal grounding (TG), spatial grounding (SG), and question answering (QA), assessing when a referenced target appears, where it is, and what happens. QA covers five perception and three reasoning categories in OmniCompass-VL, and three perception and two reasoning categories in OmniCompass-AV. OmniCompass-VL contains 820 videos and 2,460 instances across domains and three duration types: short, medium, and long. A narrative- and audio-rich subset forms OmniCompass-AV with 240 videos and 720 instances. Each instance is evaluated under two paired settings: text-only and text+image, specifying the same target through text and visual-language guidance. All instances are manually annotated with multi-round quality verification. Evaluations of 50 MLLMs show that open-source models still lag behind proprietary counterparts, particularly in audio-visual understanding. Precise temporal and spatial grounding remains challenging even for leading models, and their predictions still exhibit inconsistencies across the paired target specifications.","authors":["Xuyang Liu","Shihao Wang","Xinyu Wei","Minghan Li","Zeqing Wang","Zuhao Yang","Zichen Wen","Lei Zhang"],"published":"2026-10-13T17:54:22Z","updated":"2026-10-13T17:54:22Z","abstract_url":"https://arxiv.org/abs/2610.18829v1","html_url":"https://arxiv.org/html/2610.18829v1","pdf_url":"https://arxiv.org/pdf/2610.18829v1.pdf","matched_keywords":["video","instance","multimodal"],"source_used":"html","source_text_chars":107566,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, instance, multimodal 相关；摘要显示其主要贡献为：With the rapid development of multimodal large language models (MLLMs), evaluating their video understanding capabilities has become increasingly important. Existing video understanding benchmarks cover only part of the evaluation dimensions, limiting systema...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18804v1","title":"Registration is a Representation Problem: Solving Whole-Body PET/CT Registration","abstract":"Raw image intensities are a poor surrogate for similarity across images in correspondence problems. Further, while auxiliary segmentation labels can provide semantic identification and improve matching, they can assign only coarse identities to fine-grained anatomy and often cover only a subset of structures, particularly in whole-body settings. We present an approach that instead establishes correspondence using complementary representations of anatomy and demonstrate its utility for longitudinal whole-body PET/CT registration in the Learn2Reg 2026 PSMAReg Challenge. Our 3D foundation model, anatomix, is used to derive fine-grained, per-voxel semantic representations that are consistent across volumes, and we further employ off-the-shelf segmentation models to obtain coarse anatomical identities. Together, these representations drive a GPU-accelerated iterative registration solver (FireANTs) in a hybrid multistage framework: the first stage estimates alignment from dense multi-channel features, after which a second refines the deformation using both anatomix- and segmentation-based losses. Lastly, because registration should not introduce non-biological tumor volume changes across time, we develop lesion-specific component-wise volume preservation schemes. Without any task-specific training, our system won first place in the PSMAReg Challenge leaderboard. Code and interactive visualizations are available at http://www.neeldey.com/reps-for-reg.","authors":["Neel Dey","Adrian V. Dalca"],"published":"2026-10-13T17:45:34Z","updated":"2026-10-13T17:45:34Z","abstract_url":"https://arxiv.org/abs/2610.18804v1","html_url":"https://arxiv.org/html/2610.18804v1","pdf_url":"https://arxiv.org/pdf/2610.18804v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":33315,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Raw image intensities are a poor surrogate for similarity across images in correspondence problems. Further, while auxiliary segmentation labels can provide semantic identification and improve matching, they can assign only coarse identities to fine-grained a...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18789v1","title":"Trust Before Autonomy: Rethinking Agentic Remote Sensing for Crisis Response","abstract":"Agentic remote sensing is evaluated on how many questions it can answer, whereas crisis response depends on whether its answers can be relied on and how much of the decision can safely be handed to the agent. This paper argues that \\emph{autonomy should be earned, not assumed}: An Earth-Observation (EO) agent should be granted autonomy in proportion to demonstrated reliability, epistemic honesty and verifiability. The position is supported by an evidential meta-analysis of twelve agentic RS/EO/GIS benchmark studies from peer-reviewed venues. Only one repeats runs, three contain unanswerable tasks and none measures calibration. Their own tables show that completed workflows are often not correct (task success exceeds tool-call correctness by up to 54pp on identical queries), that the gap to an expert trajectory widens overall with trajectory length (from 7 to 56pp), and that capability does not predict abstention (Spearman r from -0.25 to 0.50, all n.s.). The paper then contributes three EO-specific trust properties, an autonomy ladder for crisis EO tasks, and a readiness protocol that replays archived emergency activations before any live use. In this context, current evidence justifies assistive roles only.","authors":["Georgios Angelidis","Aggelos Psiris","Spyridon Evangelatos","Thomas Lagkas","Panagiotis Sarigiannidis","Iraklis Varlamis","Georgios Th. Papadopoulos"],"published":"2026-10-13T17:39:23Z","updated":"2026-10-13T17:39:23Z","abstract_url":"https://arxiv.org/abs/2610.18789v1","html_url":"https://arxiv.org/html/2610.18789v1","pdf_url":"https://arxiv.org/pdf/2610.18789v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":55562,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Agentic remote sensing is evaluated on how many questions it can answer, whereas crisis response depends on whether its answers can be relied on and how much of the decision can safely be handed to the agent. This paper argues that \\emph{autonomy should be ea...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18779v1","title":"GAD: Geometry Attention Distillation for Consistent Video Generation","abstract":"Video diffusion models generate visually compelling short-term sequences but often struggle to preserve scene geometry and object structure over time. In this paper, we first demonstrate that current video attention cannot identify reliable correspondences across frames, with responses dispersed across multiple regions even after recognizable scene structure has emerged. We argue that reliable cross-frame associations are essential for information exchange as scene structure forms in video generation. Thus, we introduce Geometry Attention Distillation (GAD), which transfers correspondences from a frozen geometry model's attention to video attention. Extracted from clean videos, these correspondences link the same static surface or moving object across frames. Since structure formation begins in deeper layers at higher noise and shallower layers at lower noise, we apply attention distillation at a student layer selected according to the noise timestep. After training, video attention focuses more consistently on corresponding locations. Experiments across all three video backbones demonstrate improved long-range scene consistency and dynamic temporal consistency, with geometric gains across generation lengths. On Wan2.2 5B, GAD improves cross-frame matching accuracy by at least 30% over the Wan baseline on both long-range benchmarks. Notably, GAD achieves these gains without additional inference modules, offering a promising approach to efficient and consistent video-based world simulation. Project page: https://fantasy-amap.github.io/GAD/.","authors":["Junfeng Ni","Ziyu Zhu","Fan Jiang","Yu Liu","Chiyu Wang","Jiawei Zhang","Zhaoxu Sun","Mu Xu","Siyuan Huang","Yixin Chen"],"published":"2026-10-13T17:33:16Z","updated":"2026-10-13T17:33:16Z","abstract_url":"https://arxiv.org/abs/2610.18779v1","html_url":"https://arxiv.org/html/2610.18779v1","pdf_url":"https://arxiv.org/pdf/2610.18779v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":102854,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：Video diffusion models generate visually compelling short-term sequences but often struggle to preserve scene geometry and object structure over time. In this paper, we first demonstrate that current video attention cannot identify reliable correspondences ac...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18763v1","title":"LayerCanvas: Infographic Generation in AI Learning Assistants via Hybrid Layer-Set Diffusion","abstract":"Online learning platforms are increasingly deploying AI assistants to provide personalized, on-demand tutoring. These can leverage infographics to communicate complex information and improve the learning experience. However, automating effective infographic generation remains a challenging task, requiring a combination of visual richness with precise typography, structured layouts, and continued editability. Existing representation methods satisfy these goals only in part: Scalable Vector Graphics (SVG) representations preserve geometry, hierarchy, and text but provide limited aesthetic flexibility, while raster diffusion models produce richer appearances by flattening content and layout into a single image. Conditioning a diffusion model on a rasterized SVG does not resolve this conflict because the raster preserves approximate placement but discards element ownership, occlusion relationships, and the structure needed to modify and recompose the result. We introduce LayerCanvas, a hybrid approach that retains SVG as the semantic, structural, and typographic program while using diffusion to aestheticize non-text content. Rather than generating one flattened raster, LayerCanvas partitions SVG elements into z-ordered sets of mutually non-overlapping elements and processes them through communicating parallel RGB generation streams. The resulting layers are independently editable and deterministically recomposed, while text is rendered from preserved vector metadata. Our approach combines rich visual synthesis with accurate typography and localized editing. LayerCanvas substantially improves text fidelity over state-of-the-art raster image generators while achieving the highest overall aesthetic quality. We further demonstrate non-destructive content editing, localization, asset reuse, and animation.","authors":["Keshav Gupta","Jeremy Owen","Christopher Lloyd","Shaunak Mishra","Manav Sharma"],"published":"2026-10-13T17:25:04Z","updated":"2026-10-13T17:25:04Z","abstract_url":"https://arxiv.org/abs/2610.18763v1","html_url":"https://arxiv.org/html/2610.18763v1","pdf_url":"https://arxiv.org/pdf/2610.18763v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":89825,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Online learning platforms are increasingly deploying AI assistants to provide personalized, on-demand tutoring. These can leverage infographics to communicate complex information and improve the learning experience. However, automating effective infographic g...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18741v1","title":"Context-aware Bayesian Fusion for Multimodal Object Detection","abstract":"Reliable detection of pedestrians and road users is essential for the safe operation of autonomous vehicles. However, this task becomes increasingly challenging under adverse environmental conditions, such as poor weather and low lighting, where the performance of state-of-the-art pre-trained object detectors and on-board sensors tends to degrade, which limits their effectiveness and reliability. Moreover, retraining models for each operating context imposes significant constraints due to high data requirements, computational resources, and time. Considering this, we propose a novel context-aware multimodal late fusion approach that integrates a lightweight gating network within our probabilistic calibration framework. The gating network extracts environmental context and dynamically modulates the detection outputs of pre-trained object detectors based on the inferred context, without retraining of the detectors. Our methodology is evaluated on a modified KITTI dataset, in which the camera images and lidar pointclouds are augmented for varying fog levels. Experimental results show that our approach yields an approximately 14% relative improvement over non-adaptive late fusion baselines, achieving a consistent average precision of 56% across different fog levels.","authors":["Arunachalam Venkatachalam","Mhafuzul Islam","Marwan Yusuf","David Van Hamme","Ben Stoffelen","James Foresi"],"published":"2026-10-13T17:10:27Z","updated":"2026-10-13T17:10:27Z","abstract_url":"https://arxiv.org/abs/2610.18741v1","html_url":"https://arxiv.org/html/2610.18741v1","pdf_url":"https://arxiv.org/pdf/2610.18741v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":36395,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Reliable detection of pedestrians and road users is essential for the safe operation of autonomous vehicles. However, this task becomes increasingly challenging under adverse environmental conditions, such as poor weather and low lighting, where the performan...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18697v1","title":"UniW(A)M: A Unified Mixture-of-Experts Framework for World and World-Action Models","abstract":"World models (WMs) and world-action models (WAMs) focus on future world prediction and executable action generation, respectively. Although these models learn shared physical dynamics and interaction semantics from embodied trajectories, they are typically trained in isolation, which restricts knowledge reuse between prediction and control. The central challenge is therefore to develop a unified learning framework that shares these dynamics while preserving the distinct modeling capabilities required by each paradigm. We propose UniW(A)M, a mixture-of-experts world-(action) model built upon diffusion Transformers that unifies action-conditioned world modeling and diverse WAM variants. Shared experts capture common dynamics, while atomic capability experts are reused across interfaces so that each interface keeps its own conditional pathway. At deployment, a plug-in adaptive interface router (PAIR) learns from a small subset of target-task chunk scenarios to select a suitable WAM interface for each execution chunk, balancing task success and execution efficiency while keeping the backbone frozen. We evaluate UniW(A)M on LIBERO, RoboTwin 2.0, and three real-world manipulation tasks, where it achieves 88.3% average real-world success versus 76.7% for the strongest baseline. On WorldArena, it leads action-conditioned world modeling on all three tasks. AC-WM co-training contributes to action generation on every action interface and PAIR raises OOD success from 63.3% to 76.7%.","authors":["Jingbo Xu","Jianjie Fang","Zhuohang Li","Zihao Song","Zhaolu Wang","Xvyuan Liu","Xin Zhang","Haisheng Su","Yinzhou Tang","Chen Gao","Wei Wu","Yong Li"],"published":"2026-10-13T16:47:16Z","updated":"2026-10-13T16:47:16Z","abstract_url":"https://arxiv.org/abs/2610.18697v1","html_url":"https://arxiv.org/html/2610.18697v1","pdf_url":"https://arxiv.org/pdf/2610.18697v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":105445,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：World models (WMs) and world-action models (WAMs) focus on future world prediction and executable action generation, respectively. Although these models learn shared physical dynamics and interaction semantics from embodied trajectories, they are typically tr...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18696v1","title":"CryoTracer: A Synthetic-to-Real System for Filament Instance Tracing in Cryo-EM","abstract":"Particle picking in cryo-electron microscopy is commonly formulated as an object-detection problem in which individual particles are represented by bounding boxes, a natural representation for globular particles but a poor match for filaments that can extend across an entire micrograph. Existing methods reconstruct filament trajectories by linking local predictions in a separate post-processing stage, decoupling detection from instance formation and creating potential ambiguities at gaps and crossings. Directly preserving filament identity is particularly useful for polymorphic specimens, where segments originating from the same filament should remain associated. However, learning such instance-level representations is challenging because expert centerline annotations are scarce and costly to obtain. We introduce CryoTracer, a synthetic-to-real framework that addresses this limitation through procedural micrograph generation, transformer-based polyline prediction, and specimen-specific fine-tuning. Procedural pretraining exposes the model to diverse filament geometries, intersections, and imaging conditions before adaptation using a limited number of fully annotated experimental micrographs. CryoTracer represents filaments as ordered centerline polylines and optimizes their geometry using an orientation-invariant discrete Fréchet objective, enabling consistent learning regardless of tracing direction. Evaluation on established and newly expert-annotated datasets shows that CryoTracer improves instance-level filament recovery over existing particle-detection approaches. These results establish end-to-end polyline prediction as a practical alternative to detection-and-linking pipelines for recovering complete filament instances with limited micrograph annotation budgets. Code and data are available at https://github.com/cryotracer/cryotracer","authors":["Radosław Kuczbański","Wojciech Kozłowski","Mateusz Grzesiuk","Konrad Karanowski","Lukas Frey","Andrzej Rzepiela","Maciej Zięba"],"published":"2026-10-13T16:46:43Z","updated":"2026-10-13T16:46:43Z","abstract_url":"https://arxiv.org/abs/2610.18696v1","html_url":"https://arxiv.org/html/2610.18696v1","pdf_url":"https://arxiv.org/pdf/2610.18696v1.pdf","matched_keywords":["representation","instance"],"source_used":"html","source_text_chars":68602,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, instance 相关；摘要显示其主要贡献为：Particle picking in cryo-electron microscopy is commonly formulated as an object-detection problem in which individual particles are represented by bounding boxes, a natural representation for globular particles but a poor match for filaments that can extend...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18694v1","title":"GeoReader: Learning Latent Geometry for Spatial Reasoning in Vision-Language Models","abstract":"Vision-language models (VLMs) struggle with metric and multi-view relationships that remain implicit in RGB observations. Geometry foundation models recover this structure from RGB, but existing methods either fuse the estimated features with visual tokens and learn to use them from question answering alone, or align VLM latents with geometry features. Capturing geometry, however, does not ensure its use: zeroing the aligned latents of a released feature-alignment model leaves its accuracy unchanged. We introduce GeoReader, a framework that learns geometric representations for the VLM that reads them. First, we train lightweight Geometric Readers to produce continuous input tokens, supervising them with geometry descriptions decoded by a frozen VLM, so that the Readers express geometry in a form the target model can already read. We then freeze the Readers to preserve this interface while fine-tuning the VLM on spatial QA, with geometry injection conditioned on the question. Geometry descriptions serve only as training targets: at inference, the VLM answers directly from the continuous geometric tokens without generating a geometry chain of thought. With geometry predicted from RGB images, our approach reaches 94.3 on MindCube-Tiny with Qwen3-VL-4B and, with a multi-source QA mixture, an average of 72.5 across six additional spatial benchmarks with Qwen3.5-9B. These results suggest that a useful geometric representation is one the receiving model can use, not merely one from which geometry can be reconstructed.","authors":["Rong Li","Shijie Li","Jiangyong Huang","Lingdong Kong","Jiaming Zhou","Dongyue Lu","Zeying Gong","Baoxiong Jia","Junwei Liang","Siyuan Huang"],"published":"2026-10-13T16:45:37Z","updated":"2026-10-13T16:45:37Z","abstract_url":"https://arxiv.org/abs/2610.18694v1","html_url":"https://arxiv.org/html/2610.18694v1","pdf_url":"https://arxiv.org/pdf/2610.18694v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":110094,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Vision-language models (VLMs) struggle with metric and multi-view relationships that remain implicit in RGB observations. Geometry foundation models recover this structure from RGB, but existing methods either fuse the estimated features with visual tokens an...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18688v1","title":"RSIgen: Reciprocal Self-Improvement for Agentic Visual Generation","abstract":"Agentic visual generation produces experience that can improve the native understanding (agent) and generation roles of a unified multimodal backbone, but task success alone does not determine which role should learn. Generator updates can also make the agent's action supervision stale. We introduce RSIgen, a task-centric reciprocal self-improvement framework linking learning allocation, supervision refresh, and recursive curriculum construction. Dynamic Responsibility Routing (DRR) uses matched interventions on evidence, inputs, and supported actions to select learning recipients and construct compatible training targets. After generator learning, RSIgen re-evaluates the relative utility of tested actions with branch inputs held fixed to refresh agent supervision; the retained roles then construct the next curriculum. Across BAGEL, Qwen-Image, and Wan-Image-7B, RSIgen improves AgentGen-Bench Full Overall9 by 3.2--3.3 points over a three-cycle SearchGen adaptation with action costs. Wan controls support allocation gains at matched role-level training exposure, refresh gains at a matched adaptation budget, and benefits from updated curriculum sources while recipients continue learning. In blind evaluation on 200 real-user requests, pooled tie-adjusted preference scores against the same baseline reach 70.0% for task completion and 64.9% for visual quality.","authors":["Yidi Liu","Haozhe Wang","Jie Xiao","Kai Zhu","Xueyang Fu","Zheng-Jun Zha"],"published":"2026-10-13T16:41:24Z","updated":"2026-10-13T16:41:24Z","abstract_url":"https://arxiv.org/abs/2610.18688v1","html_url":"https://arxiv.org/html/2610.18688v1","pdf_url":"https://arxiv.org/pdf/2610.18688v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18686v1","title":"RadarGSOcc: Doppler-Aware 3D Semantic Occupancy Prediction Using 4D Radar Tensor with Geometric-Semantic Feature Extraction","abstract":"3D semantic occupancy prediction is crucial for autonomous driving, but camera-based methods degrade in low-light conditions and LiDAR-based methods are sensitive to adverse weather. 4D radar is more robust, yet its sparsity and the high cost of radar tensor processing limit its use. We propose Radar Geometric-Semantic Occupancy Prediction (RadarGSOcc), an efficient framework that directly processes 4D radar tensors by separately extracting geometric and semantic features, including Doppler information, with a deformable attention-based geometric refinement module as its key component. We also introduce the K-Radar 3DSemOcc benchmark, the first large-scale benchmark for 3D semantic occupancy prediction using 4D radar tensors, built on the K-Radar dataset with refined LiDAR-based annotations. RadarGSOcc predicts 15 classes within a 51.2m range and achieves 38.2% IoU, 7.6% mIoU, and 25.5% weighted mIoU, outperforming RadarOcc by 17% relative (25.5 vs. 21.9) in weighted mIoU while using fewer parameters and lower computation. It substantially improves truck prediction while trading off car accuracy, outperforms camera-based approaches, and narrows the gap with LiDAR-based methods. To assess robustness without per-frame ground truth in adverse weather, we further propose a novel proxy metric, Environment-Based KL Divergence (EBKL), under which 4D radar proves a reliable and efficient modality for 3D semantic occupancy prediction. The dataset and code will be publicly available.","authors":["Christofel Rio Goenawan","Dong-Hee Paek","Seung-Hyun Kong"],"published":"2026-10-13T16:40:59Z","updated":"2026-10-13T16:40:59Z","abstract_url":"https://arxiv.org/abs/2610.18686v1","html_url":"https://arxiv.org/html/2610.18686v1","pdf_url":"https://arxiv.org/pdf/2610.18686v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18670v1","title":"Perception Beyond the Visible: Incompleteness-Aware Scene Understanding for Robot Autonomy","abstract":"Reliable robot autonomy requires reasoning about the world from partial and noisy observations. However, many perception systems model only visible scene regions, rely on fixed semantic categories, and assume reliable sensor measurements. These assumptions break under occlusion, novel object encounters, and sensor degradation. In this paper, I present a research vision for incompleteness-aware scene understanding. I organize this vision around three fundamental challenges: incomplete evidence, incomplete knowledge, and incomplete sensor reliability. I discuss my research contributions toward addressing these challenges through amodal perception, semantic occupancy forecasting, open-world scene understanding, label-efficient learning, and uncertainty-guided multi-modal fusion. Building on these contributions, I outline future research directions toward belief-centric 4D scene representations. These representations aim to jointly model geometry, semantics, motion, and uncertainty. I also discuss active sensing and safe adaptation strategies that allow robots to reduce uncertainty through interaction. The goal is to develop calibrated and actionable scene representations that support reliable autonomy in dynamic, open-world environments.","authors":["Rohit Mohan"],"published":"2026-10-13T16:29:25Z","updated":"2026-10-13T16:29:25Z","abstract_url":"https://arxiv.org/abs/2610.18670v1","html_url":"https://arxiv.org/html/2610.18670v1","pdf_url":"https://arxiv.org/pdf/2610.18670v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18664v1","title":"PlanPath: Exploration-Guided Orchestration for Patient-Level Pathology Reasoning","abstract":"A patient's pathology case spans tens of slides from distinct specimens and anatomical sites, each carrying non-redundant, site-specific evidence. Forming a patient-level conclusion therefore requires locating the slides relevant to a given question and integrating complementary findings across them. However, existing pathology agents analyze one slide at a time and describe morphology rather than measure it, leaving evidence acquisition across a patient's specimens and patient-level quantification underexplored. To address this gap, we propose PlanPath, an agentic framework for patient-level pathology visual question answering (VQA). PlanPath turns the question into an exploration plan that specifies the evidence required, routes to the slides likely to carry it, and drives coarse-to-fine acquisition from tissue architecture down to individual cells. Tissue- and cell-level tools supply the counts, proportions, and extents, which PlanPath aggregates across slides into a traceable answer. To enable evaluation, we build two patient-level VQA datasets for renal and gastric cancer, averaging 15 WSIs per patient, with pathologist-verified question-answer pairs derived from diagnostic reports. Experimental results show that PlanPath outperforms the strongest baseline by 9.4% and 12.1% in overall accuracy on the two datasets and further improves existing slide-level agents when plugged into our framework. The dataset and code are available at: https://github.com/JSGe-AI/PlanPath_1.","authors":["Jiusong Ge","Mingzhao He","Qidong Liu","Chunbao Wang","Chunze Yang","Di Zhang","Jiashuai Liu","Mireia Crispin-Ortuzar","Huazhu Fu","Chen Li","Zeyu Gao"],"published":"2026-10-13T16:25:58Z","updated":"2026-10-13T16:25:58Z","abstract_url":"https://arxiv.org/abs/2610.18664v1","html_url":"https://arxiv.org/html/2610.18664v1","pdf_url":"https://arxiv.org/pdf/2610.18664v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18655v1","title":"Texture Interpolation as Texton Matching","abstract":"Texture interpolation asks what should lie between two textures. Standard methods typically blend pixels or features at corresponding spatial locations, implicitly assuming that co-located elements should be mixed. For unrelated textures, however, this correspondence is arbitrary: a crack at one location has no particular relationship to a fiber at the same location in another image. We study whether this hidden pairing choice is itself a major determinant of interpolation quality. We represent textures as collections of local appearance vectors, or textons, and replace positional pairing with appearance-aware matching while keeping the encoder, representation, and decoder fixed. This isolates the effect of correspondence from changes in model capacity or training. Across texture pairs, appearance-aware matching consistently improves the distributional quality of interpolated midpoints over positional feature blending. Soft matching produces the strongest midpoint statistics, whereas one-to-one assignments yield more balanced transitions and closer agreement with the target endpoint. The same intervention also improves a second pretrained texture interpolator without retraining. These results identify correspondence as a first-class design choice in texture interpolation: meaningful transitions depend not only on how strongly two textures are mixed, but also on which local appearances are mixed with one another.","authors":["Ido Madar","Gal Oren","Shai Avidan"],"published":"2026-10-13T16:19:42Z","updated":"2026-10-13T16:19:42Z","abstract_url":"https://arxiv.org/abs/2610.18655v1","html_url":"https://arxiv.org/html/2610.18655v1","pdf_url":"https://arxiv.org/pdf/2610.18655v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18645v1","title":"ST-GRU PredRNN-V2: A GRU-Based Reformulation of PredRNN-V2 for Video Prediction","abstract":"Video prediction requires models to capture complex spatiotemporal dependencies and to retain relevant information over long sequences. PredRNN and its successor PredRNN-V2 address this challenge with spatiotemporal Long Short-Term Memory (ST-LSTM) units that maintain two separate memory states, at the cost of a relatively complex recurrent building block. In this work, we investigate whether the simpler gating of Gated Recurrent Units (GRUs) can be transferred to spatiotemporal predictive learning. To this end, we develop a spatiotemporal GRU (ST-GRU) unit as a GRU-based alternative to the ST-LSTM. The ST-GRU replaces the ST-LSTM's three gates per memory state with two GRU-style gates (update and reset), and merges the temporal memory state into the hidden state, which reduces the number of parameters by about 5%. We incorporate the ST-GRU into PredRNN-V2 and evaluate the resulting model on the Moving MNIST video prediction benchmark, following the original experimental protocol. Averaged over ten predicted frames, the ST-GRU-based PredRNN-V2 achieves an MSE of 55.1, an SSIM of 0.883, an LPIPS of 0.065 and a PSNR of 19.53dB. It does not surpass the original ST-LSTM-based PredRNN-V2 on MSE, SSIM or PSNR, but it achieves a lower LPIPS and performs on par with the earlier ST-LSTM-based PredRNN, while using a simpler recurrent cell. These results suggest that ST-GRUs are a promising building block for spatiotemporal predictive learning and motivate further work on their design and integration.","authors":["Augusta van Haren","Hanna Hoogen","Luca Pattavina","Quincy Rommen"],"published":"2026-10-13T16:11:56Z","updated":"2026-10-13T16:11:56Z","abstract_url":"https://arxiv.org/abs/2610.18645v1","html_url":"https://arxiv.org/html/2610.18645v1","pdf_url":"https://arxiv.org/pdf/2610.18645v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18615v1","title":"VideoJev: System One Model for Video Understanding and Interaction","abstract":"Visual agents must turn video observations into timely decisions to track progress and choose what to do next. Building on the emerging System One paradigm, we introduce VideoJev, a family of models that cast video understanding and interaction as structured decision tasks. We adapt pretrained multimodal large language models (MLLMs) by replacing autoregressive answer decoding with a shared head that scores temporal intervals and textual options against video evidence. These scores yield event spans or answer choices, unifying temporal grounding and multiple-choice video question answering. This combines the semantic flexibility of MLLMs with efficient decisions that agents can use directly. As an interaction unfolds, new goals and intermediate results prompt further queries about the same visual history. VideoJev therefore reuses visual computation through Cached inference for queries as they arrive and Joint inference for multiple queries in a single forward pass. Across three temporal grounding benchmarks, VideoJev-4B and VideoJev-35B-A3B improve mean mIoU over their backbones by 6.7 and 10.8 points, respectively, with measured inference speedups of $2.8$-$3.1\\times$. On four video QA benchmarks, both achieve performance comparable to their backbones in Thinking mode, with measured inference speedups exceeding $100\\times$. These results offer a unified, reusable decision interface for composing structured visual judgments into complex, open-ended workflows.","authors":["Yuhan Zhu","Xiangyu Zeng","Qingyi Si","Chenxu Yang","Yifei Li","Luozheng Qin","Junhao Zhou","Dingyu Yao","Jun Zhang","Chuanyu Qin","Zhiqiu Zhang","Yuandong Yang","Yuqi Xu","Tianyu Zhang","Hongcheng Guo","Jiaqi Wang","Nan Duan","Limin Wang"],"published":"2026-10-13T16:00:41Z","updated":"2026-10-13T16:00:41Z","abstract_url":"https://arxiv.org/abs/2610.18615v1","html_url":"https://arxiv.org/html/2610.18615v1","pdf_url":"https://arxiv.org/pdf/2610.18615v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18609v1","title":"DPOison-VL: Clean Preference Poisoning in Vision-Language Direct Preference Optimization","abstract":"Direct Preference Optimization (DPO) has become a widely adopted approach for aligning vision-language models (VLMs), yet the security of multimodal preference data remains largely unexplored. Existing preference poisoning attacks either corrupt explicit supervision signals or require visible triggers, making them detectable under human inspection. We introduce DPOison-VL, the first clean preference poisoning attack against VLM-DPO, which manipulates model alignment solely through imperceptible perturbations on a small fraction of training images, while leaving all prompts, responses, and preference annotations semantically intact. We formulate poison construction as a bilevel optimization and derive a gradient alignment surrogate that efficiently steers image perturbations toward the attacker-specified preference. We further introduce a preference displacement score for principled poison selection with provable first-order optimality under a fixed poison budget, and derive a sufficient condition for preference inversion. Extensive experiments across diverse attack tasks, different VLM architectures and scales, and baseline comparisons demonstrate that DPOison-VL achieves up to 98\\% ASR with only 2\\% poisoned data and exhibits cross-model transferability, while largely preserving clean accuracy and general utility. Our findings reveal a critical vulnerability in VLM-DPO, where imperceptible image perturbations in preference training data can silently redirect alignment.","authors":["Chengtao Jian","Kai Yang"],"published":"2026-10-13T15:58:58Z","updated":"2026-10-13T15:58:58Z","abstract_url":"https://arxiv.org/abs/2610.18609v1","html_url":"https://arxiv.org/html/2610.18609v1","pdf_url":"https://arxiv.org/pdf/2610.18609v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18607v1","title":"Recasting DiT for Extreme Image Compression with Hierarchical Visual Priors","abstract":"Pretrained diffusion models provide powerful generative priors for extreme image compression, but their stochastic, iterative generation processes are not designed to decode compressed representations directly. We present PrismCodec, which recasts a pretrained Diffusion Transformer (DiT) as a bitstream-grounded one-step generative decoder. PrismCodec uses the decoded representation in two complementary roles: a projected codec state defines the starting state for generation, while hierarchical visual priors derived from the same decoded latent provide semantic and structural guidance. To bridge the gap between stochastic, iterative generation and deterministic one-step decoding, we develop a progressive adaptation strategy. We first learn codec-conditioned transport from a noisy neighborhood centered on the codec state, distill it into a one-step mapping, and finally anneal the source perturbation to zero during end-to-end optimization. The resulting decoder reconstructs deterministically from the received representation without additional conditioning bits. Across Kodak, CLIC, and DIV2K, PrismCodec consistently improves rate-perception performance over prior generative codecs, achieving BD-rate reductions of 70-75% in LPIPS and 75-81% in DISTS over StableCodec. Code will be released upon acceptance.","authors":["Yunuo Chen","Jingnan Gao","Bing He","Jinjing Zhao","Chuqin Zhou","Xiaoyue Ling","Li Song","Guo Lu","Wenjun Zhang"],"published":"2026-10-13T15:58:40Z","updated":"2026-10-13T15:58:40Z","abstract_url":"https://arxiv.org/abs/2610.18607v1","html_url":"https://arxiv.org/html/2610.18607v1","pdf_url":"https://arxiv.org/pdf/2610.18607v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18604v1","title":"LLM2R: From Large Language Models to 3D Reassemblers","abstract":"3D part assembly aims to reconstruct a complete shape from a set of unassembled parts by predicting a rigid SE(3) transformation for each part. Because the placement of a part is rarely determined by its own geometry, the task demands reasoning over the entire part set, and existing methods, which rely on pairwise relations or iterative generation and verification, scale poorly to objects with many parts. We present LLM2R, which casts part assembly as sequence modeling with a pretrained decoder-only large language model (LLM): a Point-BERT encoder and a Q-Former compress each part into a block of geometric tokens, the blocks of all parts are concatenated, and a causal LLM adapted with Low-Rank Adaptation (LoRA) processes the sequence in one forward pass. Causal attention, however, lets the hidden states of a part observe only the parts that precede it. LLM2R therefore appends a block of learnable summary tokens after the last part: these tokens follow every part, so their states aggregate the whole assembly at a constant token cost, and a part-aware pose head fuses each part's states with them before predicting its rotation and translation. One architecture thus handles semantic and geometric assembly and predicts all poses in a single non-autoregressive pass. LLM2R achieves the highest part accuracy and success rate on all three PartNet categories, the best rotation error, translation error, and part accuracy on PartNeXt, and the lowest translation error and fastest inference on Breaking Bad, where only a fracture-specialized method is more accurate. Its advantage grows with the number of parts: at 100 parts it exceeds GARF by 33.5 points in part accuracy on Breaking Bad and Assembler by 29.1 points on PartNet, and it transfers zero-shot to unseen categories with more than 16 points higher part accuracy than the strongest of three baselines.","authors":["Zhouhan Zhong","Qiuhong Shen","Xingyi Yang","Jinyi Xu","Xinchao Wang"],"published":"2026-10-13T15:57:41Z","updated":"2026-10-13T15:57:41Z","abstract_url":"https://arxiv.org/abs/2610.18604v1","html_url":"https://arxiv.org/html/2610.18604v1","pdf_url":"https://arxiv.org/pdf/2610.18604v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18598v1","title":"Rethinking Projector Training in Multimodal LLMs","abstract":"Multimodal LLMs are typically trained by first aligning a vision encoder with a language model via projector training on large image-caption datasets, followed by joint training of the full multimodal model. Despite its widespread use, the role of the projector training stage remains poorly understood. We find that (i) using only $10$ to $20\\%$ of the data for training the projector already recovers most downstream performance gains, and (ii) projectors trained on different datasets can be linearly interpolated while largely preserving performance. These results suggest that projector training mainly performs a coarse alignment, which many different projectors achieve equally well. Motivated by these findings, we propose PORTAL, a training-free projector initialization that requires neither paired image-caption data nor gradient-based optimization, but only per-modality summary statistics. PORTAL computes an optimal-transport-based map between Gaussian approximations of the vision and language feature distributions on a shared principal subspace, so that the projector training stage can be skipped entirely. Without any paired data, PORTAL matches the standard pipeline trained on 558k image-caption pairs across six LLM backbones, two vision encoders, and 16 benchmarks. It outperforms that pipeline in $3$ of $7$ (vision encoder, LLM) settings and reaches an average $98\\%$ of its score across the other four.","authors":["Fabian Gröger","Naël Ouerghemi","Shuo Wen","Maria Brbić"],"published":"2026-10-13T15:53:53Z","updated":"2026-10-13T15:53:53Z","abstract_url":"https://arxiv.org/abs/2610.18598v1","html_url":"https://arxiv.org/html/2610.18598v1","pdf_url":"https://arxiv.org/pdf/2610.18598v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18571v1","title":"Parameter-Efficient Multimodal Brain Tumor Segmentation With Stage-Wise Shared Adapters","abstract":"Different MRI modalities reveal different parts of a brain tumor. Segmentation models combine information from these modalities to outline tumor regions. Many models use a separate encoder for each modality. However, exchanging features among these encoders at several stages can increase model complexity. We introduce the Block-Wise Shared Adapter (BWSA), which combines compressed features from the modality encoders in a shared path and returns adapted features to each stream. In its fixed-blending form, BWSA adds the adapted features to the original features. Its trainable-gated variant (TG-BWSA) instead learns separate weights for the original and adapted features at each modality and encoder stage. We evaluate both variants on BraTS 2020 and BraTS 2023 with four segmentation backbones. On the official BraTS 2023 online validation set, BWSA increases average region-wise Dice by 1.3--7.6 percentage points relative to the corresponding unmodified backbones. TG-BWSA increases it by 2.8--7.7 points. Both variants add approximately 0.85--3.73% parameters and reduce average HD95 relative to the unmodified backbones.","authors":["Milad Rostamian","Mohammadreza Mohammadi","Ender Konukoglu","Mohsen Soryani"],"published":"2026-10-13T15:39:20Z","updated":"2026-10-13T15:39:20Z","abstract_url":"https://arxiv.org/abs/2610.18571v1","html_url":"https://arxiv.org/html/2610.18571v1","pdf_url":"https://arxiv.org/pdf/2610.18571v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18543v1","title":"Beyond the Encoder: Object-Centric Representations Emerging from Segmentation Foundation Models","abstract":"Foundation models are increasingly used as feature extractors for downstream tasks with limited data, typically through representations obtained from their encoders. However, foundation models trained for structured tasks such as segmentation also form object-specific representations during task execution, whose transferability remains largely unexplored. We investigate Segment Anything Model 2 (SAM2) object pointers, compact object-level representations produced through the segmentation pathway, as transferable representations for downstream tumour prediction. Through experiments on two PET/CT tumour prediction tasks, we find that object pointers learned using segmentation supervision alone already encode tumour-discriminative information, despite never being optimised for the downstream labels. We further introduce task-guided object pointers, where an auxiliary objective jointly shapes the object pointer space for the downstream prediction together with segmentation. Task-guided pointers improve cancer-type classification, outperforming conventional encoder-based transfer and radiomics, while segmentation-only pointers perform best on the more challenging recurrence prediction task. Representation analyses reveal associations between object pointers and interpretable radiomics features, class-dependent organisation of the learned representation space, and explicit spatial grounding around the segmented tumour. Together, these findings suggest that useful transferable representations can emerge through the execution of a foundation model's primary task, providing an alternative to conventional encoder-based transfer.","authors":["Michalis Pistos","Bartłomiej W. Papież"],"published":"2026-10-13T15:22:00Z","updated":"2026-10-13T15:22:00Z","abstract_url":"https://arxiv.org/abs/2610.18543v1","html_url":"https://arxiv.org/html/2610.18543v1","pdf_url":"https://arxiv.org/pdf/2610.18543v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18535v1","title":"Meta-Video: Efficient Standardized Evaluation for Video Understanding","abstract":"Video understanding benchmarks are the primary yardstick for measuring progress in video-language modeling, and a growing body of work relies on them to claim improvements. The reported benchmark scores in these works, however, are almost always produced by frameworks (e.g., lmms eval) used as black boxes: certain evaluation choices like frame sampling, preprocessing, and input formatting are inherited from preset defaults and seldom inspected carefully. We show these unexamined choices are a major source of variance. Even for the same model checkpoint, evaluation configuration alone can shift accuracy by up to 19.5pp. Hence, it is unclear whether reported gains reflect genuine improvements in capability or differences in evaluation setup. Moreover, many benchmark samples offer little evidence of visual capability, since they can be answered without the video, and the full suites are expensive to evaluate. We address these issues in two parts. First, we curate existing suites for discriminability and efficiency, producing Meta-Video, a balanced 1,000-question benchmark over 791 videos spanning diverse tasks and durations, which largely preserves model rankings, at 5 times inference speedup for a full-frame count sweep experiment (4-128 frames). Second, we establish a standardized evaluation protocol by sweeping the configuration space to isolate choices that measurably affect results, distill them into best practices and reporting standards, and release reproducible reference scores across five models and seven benchmarks. We hope that the proposed evaluation framework and the Meta-Video benchmark will support video understanding research by providing a reproducible and efficient foundation to measure progress in a reliable way.","authors":["Soumya Shamarao Jahagirdar","Anna Kukleva","Vishaal Udandarao","Samuel Thomas","Brian Kingsbury","Rogerio Feris","James R. Glass. Ameya Prabhu","Hilde Kuehne"],"published":"2026-10-13T15:18:12Z","updated":"2026-10-13T15:18:12Z","abstract_url":"https://arxiv.org/abs/2610.18535v1","html_url":"https://arxiv.org/html/2610.18535v1","pdf_url":"https://arxiv.org/pdf/2610.18535v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18499v1","title":"EgoOmniWorld: Unifying Egocentric Understanding via Ego-Action-World Interactions","abstract":"Egocentric video understanding spans diverse capabilities, modalities, and evaluation formats, yet these are often studied in isolation despite their tight coupling in real-world interaction. We propose the Ego-Action-World interaction loop as a unifying principle: the wearer perceives the world, forms goals, acts, changes the world, and uses feedback to guide subsequent behavior. Based on this view, we introduce EgoOmniWorld, a benchmark organized around four complementary interaction structures: Node captures ego, action, and world states; Edge captures directed relations among them; Chain captures linked dependencies; and Loop captures feedback-closed interactions. We develop an interaction-first, evidence-grounded data pipeline that extracts structured interactions from egocentric videos, grounds them in visual and auditory evidence, and generates questions according to their interaction structure. Required modalities and single- or multi-turn formats follow naturally from the supporting evidence and dependencies. EgoOmniWorld contains 24,166 QA groups, including 20,284 training and 3,882 test samples. Experiments on representative open- and closed-source multimodal large language models reveal substantial and uneven limitations across interaction structures. Models trained on EgoOmniWorld improve in-domain interaction understanding and generalize to existing egocentric benchmarks. EgoOmniWorld provides a unified foundation for evaluating and advancing egocentric video understanding. Data, code, and models will be released.","authors":["Songruo Chen","Yuqian Fu","Yu Li","Mingkang Dong","Sifan Zhou","Bin Ren","Xu Zheng","Tianwen Qian","Mohamed Elhoseiny","Yanwei Fu"],"published":"2026-10-13T14:53:16Z","updated":"2026-10-13T14:53:16Z","abstract_url":"https://arxiv.org/abs/2610.18499v1","html_url":"https://arxiv.org/html/2610.18499v1","pdf_url":"https://arxiv.org/pdf/2610.18499v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18485v1","title":"Physics-Aware Deepfake Detection via Distance-Speech Consistency","abstract":"Recent progress in generative models has made talking-head deepfakes highly realistic and easy to create, jeopardizing public trust. However, most audio-visual deepfake detectors rely on lip-speech synchronization and are designed for static, frontal videos, limiting their reliability in dynamic, in-the-wild recordings where the speaker moves and lip cues are degraded or missing. As an alternative, we propose a physics-aware detector for dynamic speaking videos that leverages an acoustic constraint: in real recordings, speech energy varies predictably with speaker-to-camera distance, whereas deepfake generation can break this coupling. Our method combines distance estimates from video with distance-dependent acoustic measures from speech to detect deepfakes. Experiments on in-the-wild benchmarks show that the proposed physical cue is effective in dynamic scenarios, and that it complements lip-sync-based detectors, with a simple ensemble achieving consistent gains across datasets. Codes are available at https://byulharang.github.io/PADD/.","authors":["Kyeongrae Kim","Kim Sung-Bin","Oh Hyun-Bin","Tae-Hyun Oh"],"published":"2026-10-13T14:44:28Z","updated":"2026-10-13T14:44:28Z","abstract_url":"https://arxiv.org/abs/2610.18485v1","html_url":"https://arxiv.org/html/2610.18485v1","pdf_url":"https://arxiv.org/pdf/2610.18485v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18472v1","title":"Simplifying and Improving On-Policy Distillation for Few-Step Diffusion","abstract":"Few-step distillation reduces the sampling cost of diffusion and flow models, but existing approaches often require auxiliary score models or specialized architectures. We show that simple on-policy velocity regression already provides a strong foundation for 4-NFE generation. To represent teacher velocity variation within each coarse transition, we introduce Pivot, a training-only residual proxy that separates local corrections from the student's interval-mean prediction. We further repel the student from weaker teacher predictions, providing a lightweight mechanism for avoiding undesirable modes. The resulting framework, Simplified Matching Distillation (SMD), remains entirely regression-based, requires neither online score estimation nor adversarial training, and leaves the deployed generator unchanged. We evaluate SMD on image generation and editing, 3D generation, video synthesis, and joint audio--video generation, scaling to 33 billion parameters. At 4-NFE, SMD outperforms strong few-step baselines and surpasses multi-step teachers on several benchmarks. It also supports cross-model, multi-teacher, and causal-video distillation.","authors":["Jiawei Zhang","Ziyu Wan","Nanye Ma","Long Zhao","Dong Chen","Hongyu Liu","Qifeng Chen","Dongdong Chen"],"published":"2026-10-13T14:35:46Z","updated":"2026-10-13T14:35:46Z","abstract_url":"https://arxiv.org/abs/2610.18472v1","html_url":"https://arxiv.org/html/2610.18472v1","pdf_url":"https://arxiv.org/pdf/2610.18472v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18461v1","title":"MFVSR: A Multi-Style and Fine-Grained Benchmark for Video Subtitle Removal","abstract":"Video subtitle removal (VSR) is an important video restoration task, yet existing evaluation remains limited by low-resolution datasets, fragmented test sets, and generic video-inpainting protocols that fail to adequately capture localized restoration errors, unintended modifications, temporal instability, and incomplete outputs. In this paper, we introduce MFVSR, a large-scale multi-style benchmark for fine-grained and reliability-aware video subtitle removal evaluation. MFVSR distinguishes itself through three key features: (1) Large-scale and diverse data, comprising 3,000 paired videos from Real-HQ, Real-LQ, and AI-Generated sources, with an auxiliary set of 953 in-the-wild real videos for real-world coverage analysis; (2) Controlled subtitle diversity, spanning 16 languages and four factors covering spatial layout, temporal behavior, visual style, and language mode; (3) Fine-grained evaluation, introducing an information-conditioned, spatially decoupled protocol that separates blind from mask-guided removal and measures Restoration Fidelity, Preservation Fidelity, Temporal Fidelity, coverage, and failures. Experiments on six representative methods reveal substantial discrepancies between local restoration, outside-region preservation, temporal consistency, and full-set reliability that are obscured by conventional full-frame metrics. MFVSR therefore provides a more comprehensive and diagnostic foundation for evaluating and advancing video subtitle removal methods.","authors":["Xiyan Huang","Qingdong He","Peng Tang","Bo Yin","Chaoyi Wang","Xiaobin Hu"],"published":"2026-10-13T14:27:22Z","updated":"2026-10-13T14:27:22Z","abstract_url":"https://arxiv.org/abs/2610.18461v1","html_url":"https://arxiv.org/html/2610.18461v1","pdf_url":"https://arxiv.org/pdf/2610.18461v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18458v1","title":"$\\mathrm{S}^3$-PnP: Plug-and-Play Denoising for Scientific Imaging with Self-Supervised Score Priors","abstract":"Modern image restoration methods increasingly rely on large-scale supervised training, yet clean targets are often prohibitively difficult to obtain in scientific imaging modalities such as hyperspectral imaging (HSI) and magnetic resonance imaging (MRI). Plug-and-play ADMM (PnP-ADMM) with pretrained diffusion priors offers a promising alternative, but the learned prior distribution can mismatch both the target scientific image distribution and the distribution of ADMM denoiser inputs induced by dual feedback. To mitigate these mismatches, we propose $\\mathrm{S}^3$-PnP, a self-supervised plug-and-play restoration framework that learns a score prior directly from observation-derived ADMM intermediate states, without clean training targets or externally pretrained weights. Specifically, the learned score corrects the input to the analytical prior update, combining observation-driven corrections with analytical regularization. We further analyze the convergence and reconstruction error of the corrected ADMM algorithm assuming an ideal score and quadratic data fidelity. Experiments on reference-guided HSI restoration, single-image HSI denoising, and MRI denoising demonstrate consistent improvements over competing methods.","authors":["Yukun Cui","Jiangshe Zhang","Shuang Xu","Lilun Deng","Haowen Bai","Tao Feng","Haotong Qin","Konrad Schindler","Zixiang Zhao"],"published":"2026-10-13T14:26:37Z","updated":"2026-10-13T14:26:37Z","abstract_url":"https://arxiv.org/abs/2610.18458v1","html_url":"https://arxiv.org/html/2610.18458v1","pdf_url":"https://arxiv.org/pdf/2610.18458v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18455v1","title":"EmoGenie: Benchmarking and Evaluating Expressed and Evoked Emotion in T2I Generation with MLLMs","abstract":"Rapid advances in artificial intelligence-generated content (AIGC) have significantly promoted using text-to-image (T2I) models to generate images with specific affective intentions. However, the emotional effects conveyed by generated images frequently deviate from target expectations, and it remains unclear whether multimodal large language models (MLLMs) can reliably interpret the emotion of AI-generated visual content. Existing affective benchmarks are predominantly built on natural images, while affective studies of generated images have largely focused on emotions expressed in portraits, lacking a unified benchmark for studying the emotions expressed and evoked by generated images. We therefore introduce EmoGenie, a benchmark of emotion for AI-generated images that evaluates capabilities in T2I generation and MLLM understanding across expressed and evoked emotions. It comprises 6,400 images generated by eight T2I models using 800 emotion-targeted prompts, annotated with question-answer (QA) pairs, termed EmoGenie-QA, and continuous human ratings, termed EmoGenie-Assess. EmoGenie-QA contains 90,000 closed-set questions in single-image and image-pair settings, as well as 1,057 open-ended questions for emotion description. EmoGenie-Assess benchmarks continuous affective and aesthetic prediction using 13,175 mean opinion scores (MOSs) aggregated from human ratings in terms of valence, arousal, dominance, and aesthetic quality. We further develop EmoProbe, which combines emotion question answering with response-aligned, dimension-specific regression heads for continuous score prediction. Experimental results show that EmoProbe achieves superior results on emotion-related QA tasks, while its affective and aesthetic predictions correlate better with human ratings, demonstrating its state-of-the-art capabilities of unified coarse-to-fine affective understanding for AI-generated images.","authors":["Zixuan Xing","Lancheng Gao","Shengyan Li","Huiyu Duan","Zhaolin Cai","Guangtao Zhai","Xiongkuo Min"],"published":"2026-10-13T14:23:07Z","updated":"2026-10-13T14:23:07Z","abstract_url":"https://arxiv.org/abs/2610.18455v1","html_url":"https://arxiv.org/html/2610.18455v1","pdf_url":"https://arxiv.org/pdf/2610.18455v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18447v1","title":"Thinker-WM: A Unified World Model with Shared Multimodal Representations for Embodied Intelligence","abstract":"World models have emerged as a promising paradigm for embodied AI, yet existing systems often remain fragmented in the modalities they model and the functions they support. In particular, visual dynamics, geometric structure, and executable action are commonly coupled through separate interfaces or downstream modules rather than being jointly represented and evolved within a shared dynamics model. In this work, we present Thinker-WM, a unified multimodal world model that jointly models and generates RGB, metric depth, and robot action through a shared intermediate Unified Dynamics Transformer with modality-specific encoders and decoders. The model performs multimodal unification at the representation level: appearance, geometry, and action are transformed into a common dynamic representation and jointly evolved by shared parameters, while their distinct output structures are preserved. The same parameterization supports multiple functions, including joint video-action generation, world prediction, policy inference, action-conditioned generation, video-to-action generation, and inverse dynamics. To examine whether the shared representation captures action-related information, we introduce a lightweight motion probe that shows the frozen visual representation contains recoverable motion information. Thinker-WM is trained on a heterogeneous corpus comprising approximately 20K hours of egocentric video, 10K hours of real-robot data, and 1K hours of simulation data, including approximately 4K hours of real-robot data with aligned depth supervision. Extensive experiments demonstrate strong performance across embodied world-model evaluations. Thinker-WM ranks first on EWMBench, WorldOlympiad and WorldArena, while controlled studies further demonstrate the benefits of action conditioning, geometric interaction, and multi-function training within the shared representation.","authors":["Thinker Team","Peng Gao","Jichao Jiao","Chen Liao","Daqin Luo","Yiming Ma","Baiyu Pan","Hailin Shi","Jiyuan Wang","Xiangming Xu","Xiongwei Zhao"],"published":"2026-10-13T14:18:47Z","updated":"2026-10-13T14:18:47Z","abstract_url":"https://arxiv.org/abs/2610.18447v1","html_url":"https://arxiv.org/html/2610.18447v1","pdf_url":"https://arxiv.org/pdf/2610.18447v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18446v1","title":"CoTL: Compact Token Learning for 3D Scene Representation","abstract":"We present CoTL, a framework that learns a compact set of tokens that preserves scene geometry and appearance from unposed multi-view images. Our encoder compresses the input images into small per-view sets of latent tokens that aggregate information across views to form a view-consistent scene representation. Each additional view expands the representation with only a small, resolution-independent set of tokens, allowing its capacity to grow with the available observations. To force this compact bottleneck to retain sufficient scene information, a query-based Gaussian decoder uses scene-independent queries to attend to the learned tokens and recover an explicit, renderable set of 3D Gaussian primitives. Novel-view rendering supervision trains the compact representation end to end through the reconstructed Gaussian scene. Experiments on \\retenk{} and ACID show that the resulting compact, unstructured token set supports competitive novel-view synthesis and can serve as the latent space of a generative model for 3D Gaussian scene generation. Together, these results show that 3D Gaussian reconstruction is an effective objective for compact scene representation learning and the learned token space provides a basis for broader downstream tasks in 3D vision.","authors":["Han Liang","Sibo Wu","Anpei Chen","Rüdiger Westermann"],"published":"2026-10-13T14:17:30Z","updated":"2026-10-13T14:17:30Z","abstract_url":"https://arxiv.org/abs/2610.18446v1","html_url":"https://arxiv.org/html/2610.18446v1","pdf_url":"https://arxiv.org/pdf/2610.18446v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18417v1","title":"Resource-Efficient 3D Shape and Orientation Estimation of Road Users using Roadside RGB Camera and 3D Radar","abstract":"End-to-end deep learning pipelines for camera-radar 3D object detection are well established in driver assistance systems and autonomous vehicles; however, adapting them to roadside-mounted infrastructure presents significant challenges. On vehicles, sensor heights, pitch angles, and relative geometries remain largely uniform, allowing end-to-end models to generalize effectively. On the contrary, roadside sensor installations vary drastically in height, tilt, and field of view across locations, rendering end-to-end models prone to failure and difficult to adapt without massive location-specific datasets. Hence, instead of designing a complex end-to-end pipeline for direct 3D bounding box estimation, a low-cost, resource-efficient two-stage approach is proposed for real-time 3D shape and orientation estimation. The first stage utilizes any off-the-shelf, state-of-the-art method to extract 2D camera bounding boxes and associated 3D radar points for each road user. The proposed second stage then processes these inputs to construct 3D oriented bounding boxes where radar data determines 3D position, predefined templates define size for each road user, and a tiny neural network predicts a site-specific and optimized yaw angle. The algorithm is successfully validated at a curved road with a junction for pedestrians, bicycles, and cars, where it achieves 25 frames per second on an NVIDIA Jetson ORIN for real-time applications.","authors":["Shiva Agrawal","Savankumar Bhanderi","Gordon Elger"],"published":"2026-10-13T13:58:01Z","updated":"2026-10-13T13:58:01Z","abstract_url":"https://arxiv.org/abs/2610.18417v1","html_url":"https://arxiv.org/html/2610.18417v1","pdf_url":"https://arxiv.org/pdf/2610.18417v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18399v1","title":"Bifocal: Training-Free Mixed Granularity Visual Token Pruning for Multimodal LLMs","abstract":"Visual token pruning for multimodal large language models (MLLMs) appears highly effective, with existing methods retaining over 95% of unpruned performance on common VQA benchmarks using a quarter of the visual tokens or fewer. However, our extensive evaluation of ten methods across three MLLM families and five ability groups reveals a critical gap: strong general performance often comes at the cost of severe degradation on fine-grained tasks such as OCR and visual grounding. We trace these failures to two limitations of the prevailing paradigm of retaining the highest-ranked native patches. A single importance ranking overlooks the complementary evidence required by different tasks, while sparse patch selection disrupts both image content and spatial integrity. To address these limitations, we propose Bifocal, a training-free, two-stage pruning method built on a mixed-granularity framework. It allocates separate budgets to query-focused and image-intrinsic evidence, complemented by a pooled coarse representation of the entire image. Before the LLM, Bifocal matches question words to visual regions through a soft conjunction balanced against norm-debiased image saliency, while selecting image-intrinsic evidence to maximize representational coverage. Inside the LLM, it further prunes tokens using density-adjusted text-to-image attention. With roughly a quarter of the original visual tokens, Bifocal is the only evaluated method to retain over 90% of unpruned performance in every ability group across all three models, and ranks first on average in all nine model-budget settings. The code is available at: https://github.com/EIT-NLP/Bifocal","authors":["Peiran Yin","Hao Wu","Zihao Yang","Fengyu Zhou","Yijuan Liang","Haozhe Hu","Xudong Wang","Wei Zhang","Xiaoyu Shen"],"published":"2026-10-13T13:46:32Z","updated":"2026-10-13T13:46:32Z","abstract_url":"https://arxiv.org/abs/2610.18399v1","html_url":"https://arxiv.org/html/2610.18399v1","pdf_url":"https://arxiv.org/pdf/2610.18399v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18388v1","title":"ReDiS: Reasoning-Diagnosis Self-Evolution for Multimodal Reasoning in Remote Sensing","abstract":"Multimodal large language models (MLLMs) have shown strong potential for remote sensing understanding, yet reliable reasoning remains challenging when tasks require fine-grained visual grounding and multi-step inference. Existing approaches typically rely on either costly pre-constructed reasoning trajectories or self-generated signals such as response consistency, which can reinforce shared errors and provide unreliable supervision. We introduce \\textbf{Reasoning--Diagnosis Self-Evolution (ReDiS)}, a framework that separates reasoning exploration from candidate evaluation while allowing the two processes to evolve jointly. ReDiS instantiates two role-specific experts from a shared multimodal backbone: a \\textbf{Reasoner} that explores diverse visual evidence--answer candidates and a \\textbf{Diagnoser} that jointly evaluates the complete candidate set and provides credibility-aware feedback. As the Reasoner evolves, it exposes new candidate distributions and failure modes; the Diagnoser adapts to these changes and, in turn, reshapes the learning signal for subsequent exploration. To handle groups in which all sampled answers are incorrect and group-relative advantages vanish, we further introduce \\textbf{Failure-Triggered Recovery (FTR)}, which provides minimal outcome-level correction without prescribing intermediate reasoning trajectories. Experiments on LHRS-Bench, MME-RS, and CHOICE show consistent improvements over Qwen3.5 backbones at 0.8B, 2B, and 4B scales. ReDiS improves category-averaged accuracy by 6.47 percentage points at 0.8B, while ReDiS-4B achieves the highest average performance among the compared remote sensing MLLMs.","authors":["Yi Liu","Wentao Jiang","Shuo Ni","Zhiming Luo","Di Wang","Zengmao Wang","Jing Zhang","Bo Du"],"published":"2026-10-13T13:38:02Z","updated":"2026-10-13T13:38:02Z","abstract_url":"https://arxiv.org/abs/2610.18388v1","html_url":"https://arxiv.org/html/2610.18388v1","pdf_url":"https://arxiv.org/pdf/2610.18388v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18374v1","title":"SchemaPose: RGB-Based Category-Level Pose Estimation with Parametric Category Schema","abstract":"RGB-based category-level 9D pose estimation remains highly challenging because a monocular system must generalize across unseen object instances while jointly inferring 3D translation, 3D rotation, and 3D size. Unlike instance-level pose estimation, the category-level setting requires the network to learn both what is shared across objects within a category and how individual instances vary in structure. This challenge is amplified in the RGB-only setting, where pose cues, category-level commonality, and instance-specific variation are entangled in appearance without direct geometric constraints, making it difficult for existing frameworks to learn a representation that is truly aligned with the category-level estimation objective. To address this problem, we propose SchemaPose, a schema-guided framework for RGB-based category-level pose estimation. SchemaPose equips the estimation pipeline with an explicit parametric schema for modeling category-level regularities together with structured instance variation, and uses the inferred schema variables to guide pose-related prediction in an end-to-end query-based framework. The same formulation also supports template instantiation, synthetic annotation, and pose learning within a unified framework. Experiments on synthetic and real data show that SchemaPose achieves state-of-the-art performance among RGB-based methods for category-level 9D pose estimation.","authors":["Shuang Wu","Jiude Wei","Cewu Lu","Jianhua Sun"],"published":"2026-10-13T13:29:04Z","updated":"2026-10-13T13:29:04Z","abstract_url":"https://arxiv.org/abs/2610.18374v1","html_url":"https://arxiv.org/html/2610.18374v1","pdf_url":"https://arxiv.org/pdf/2610.18374v1.pdf","matched_keywords":["3d","representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18369v1","title":"Hallucination-aware Faithful Reasoning in Remote Sensing","abstract":"Multimodal large language models (MLLMs) have demonstrated promising capabilities for remote sensing reasoning, yet they frequently generate visually unsupported reasoning that contradicts the visual evidence. Existing post-training methods optimize primarily for final-answer correctness, providing limited supervision for identifying and correcting hallucinations that arise during the reasoning process. To address this limitation, we propose \\textbf{FaithRS}, a hallucination-aware self-reflection framework for faithful reasoning in remote sensing. We first construct \\textbf{SFHD-43K}, a dataset of 43K structured, fine-grained hallucination annotations, and train a detector to identify hallucination types, underlying causes, and supporting visual evidence. FaithRS then incorporates this diagnostic feedback into a Safe Detector-Guided Corrective Rollout framework, where a safety-aware gate selectively determines whether and how to revise the response. Training is driven by a composite reward that jointly optimizes answer accuracy, reasoning faithfulness, hallucination reduction, format compliance, and revision safety. Experiments with Qwen3.5 backbones (0.8B, 4B, and 9B) show consistent improvements across four remote sensing benchmarks, with gains of up to 11.64 points.","authors":["Yi Liu","Jing Zhang","Xiang Feng","Xiaoyu Tian","Haonan Guo","Di Wang","Zengmao Wang","Bo Du"],"published":"2026-10-13T13:28:00Z","updated":"2026-10-13T13:28:00Z","abstract_url":"https://arxiv.org/abs/2610.18369v1","html_url":"https://arxiv.org/html/2610.18369v1","pdf_url":"https://arxiv.org/pdf/2610.18369v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18363v1","title":"Visual Sevoing from Lines","abstract":"In this work, we present a fundamentally new approach to visual servoing using lines. It is based on a theoretical and geometrical study of the main line representations which allowed us to define a new representation, the so-called binormalized Plucker coordinates. They are particularly well suited to visual servoing. Indeed, they allow the definition of a proper image line alignment concept. The control law which realizes such an alignment has moreover several properties: partial decoupling between rotation and translation, analytical inversion of the motion equations and global asymptotic stability conditions. This control law was validated both in simulation and experimentally in the specific case of an orthogonal trihedron.","authors":["Nicolas Andreff","Bernard Espiau","Radu Horaud"],"published":"2026-10-13T13:25:30Z","updated":"2026-10-13T13:25:30Z","abstract_url":"https://arxiv.org/abs/2610.18363v1","html_url":"https://arxiv.org/html/2610.18363v1","pdf_url":"https://arxiv.org/pdf/2610.18363v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18356v1","title":"Urbex: Agentic Spatial Grounding for City-Scale 3D Scenes","abstract":"City-scale 3D grounding is commonly formulated as candidate ranking, which requires precomputed instance proposals and becomes inefficient in large outdoor scenes. We propose Urbex, an agentic vision-language framework that instead casts grounding as active spatial search. Urbex represents a city-scale 3D scene as an interactive multi-view environment, allowing a VLM agent to query landmarks, zoom into local regions, render oblique views, and commit a grounded bounding box. We optimize this tool-use policy with reinforcement learning on CityRefer, using smooth localization rewards and lightweight shaping rewards for efficient exploration. Experiments show that Urbex achieves the best Hit@1 and IoU on CityRefer, supports candidate-free grounding without ground-truth boxes, and is substantially faster than the strongest city-scale ranking baseline. Zero-shot results on STPLS3D-Refer further indicate improved cross-scene robustness.","authors":["Yu Wang","Rui Dai","Wei Chen","Yi Wang","Bo Dang","Kaikui Liu","Xiangxiang Chu","Yansheng Li"],"published":"2026-10-13T13:23:24Z","updated":"2026-10-13T13:23:24Z","abstract_url":"https://arxiv.org/abs/2610.18356v1","html_url":"https://arxiv.org/html/2610.18356v1","pdf_url":"https://arxiv.org/pdf/2610.18356v1.pdf","matched_keywords":["3d","agent","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18342v1","title":"CityCode: Building Agent-Operable 3D Cities from Sparse Aerial Observations","abstract":"Urban spatial intelligence calls for 3D cities that agents can measure, interpret, and modify across successive tasks. Maintaining such cities as persistent, code-based states requires lightweight acquisition and support for consistent state updates without repeated dense reconstruction. We therefore formulate a new setting for grounded urban world construction: generating large-scale, instance-level parameterized 3D cities from one low-altitude aerial RGB image per region and known camera parameters, while recovering metrically scaled buildings and explicit road geometry and connectivity. We introduce CityCode, an agent-operable representation that unifies metric geometry, urban topology, visual semantics, and 3D assets through persistent entity identities, with dependency-aware versioned execution for validated updates and historical restoration. We further develop Air2Code to construct this representation by combining visual structure extraction with adapted metric depth estimation. To address occlusion and incomplete coverage, recovered structure and observed appearance guide generative completion and subsequent structure-aware 3D generation for buildings and backgrounds. Experiments on CitySample-Aerial and UrbanScene3D demonstrate substantially more accurate metric structure recovery and superior visual fidelity to the target cities compared with the evaluated baselines. Across 50 task chains of 50 steps each, CityCode supports continued querying, editing, planning, and historical restoration over evolving city states. Together, CityCode and Air2Code turn sparse aerial observations into persistent, agent-operable urban worlds for long-horizon urban spatial intelligence.","authors":["Jiahui Sun","Ran Bi","Yifei Liu","Xiaolong Zhou","Yishuo Xu","Yuanqi Li","Congcong Zhu","Lei Yang","Yanwen Guo","Zhihang Zhong","Hongjie Zhang"],"published":"2026-10-13T13:14:17Z","updated":"2026-10-13T13:14:17Z","abstract_url":"https://arxiv.org/abs/2610.18342v1","html_url":"https://arxiv.org/html/2610.18342v1","pdf_url":"https://arxiv.org/pdf/2610.18342v1.pdf","matched_keywords":["3d","agent","representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18325v1","title":"ShoeFit: A New Dataset and Dual-image-stream DiT Framework for Virtual Footwear Try-On","abstract":"Virtual footwear try-on (VFTON), a critical yet underexplored area in virtual try-on (VTON), aims to synthesize faithful try-on results given diverse footwear and model images while maintaining 3D consistency and texture authenticity. Unlike conventional garment-focused VTON methods, VFTON presents unique challenges due to (1) Data Scarcity, which arises from the difficulty of perfectly matching product shoes with models wearing the identical ones, (2) Viewpoint Misalignment, where the target foot pose and source shoe views are always misaligned, leading to incomplete texture information and detail distortion, and (3) Background-induced Color Distortion, where complex material of footwear interacts with environmental lighting, causing unintended color contamination. To address these challenges, we introduce MVShoes, a multi-view shoe try-on dataset consisting of 7305 well-annotated image triplets, covering diverse footwear categories and challenging try-on scenarios. Furthermore, we propose a dual-stream DiT architecture, ShoeFit, designed to mitigate viewpoint misalignment through Multi-View Conditioning with 3D Rotary Position Embedding, and alleviate background-induced distortion using the LayeredRefAttention which leverages background features to modulate footwear latents. The proposed framework effectively decouples shoe appearance from environmental interferences while preserving high-quality texture detail through decoupled denoising and conditioning branches. Extensive quantitative and qualitative experiments demonstrate that our method substantially improves rendering fidelity and robustness under challenging real-world product shoes, establishing a new benchmark in high-fidelity footwear try-on synthesis.","authors":["Yuhan Li","Zhiyu Jin","Yifan Tong","Wenxiang Shang","Benlei Cui","Xuanhong Chen","Hangcheng Zhu","Bingbing Ni"],"published":"2026-10-13T13:03:29Z","updated":"2026-10-13T13:03:29Z","abstract_url":"https://arxiv.org/abs/2610.18325v1","html_url":"https://arxiv.org/html/2610.18325v1","pdf_url":"https://arxiv.org/pdf/2610.18325v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18323v1","title":"Omni-RS: Unifying Multi-Task Understanding and Generation in Remote Sensing","abstract":"Practical remote sensing applications often require both understanding and generation capabilities for the same geographic scene. However, most existing methods address either understanding or generation in isolation, while existing unified remote sensing models' generative ability is limited to text-to-image. To bridge this gap, we propose Omni-RS, a unified framework supporting four remote sensing understanding tasks and five generation tasks. Specifically, we introduce the \"Scene-Guided Two-Stage Training\" strategy, which first adapts a multimodal large language model to remote sensing understanding and then uses its hidden states to guide a diffusion transformer for image generation. To enable joint learning across diverse generation tasks, we construct UniGen, a unified multi-task generation dataset, by organizing heterogeneous remote sensing data into a unified format. Furthermore, we introduce \"Detailed Visual Conditioning\", which uses visual conditions encoded by a VAE to guide the generation process, thereby supporting additional generation tasks that require reference images. Extensive experiments demonstrate that Omni-RS performs exceptionally well in understanding tasks and has achieved outstanding results in a variety of generative tasks.","authors":["Pan Yin. Shuai Yang","Yuanhao Liu","Datao Tang","Jialin Li","Hao Wang","Pei Liu","Kaiyu Li","Cong Zhao","Xiangyong Cao"],"published":"2026-10-13T13:02:27Z","updated":"2026-10-13T13:02:27Z","abstract_url":"https://arxiv.org/abs/2610.18323v1","html_url":"https://arxiv.org/html/2610.18323v1","pdf_url":"https://arxiv.org/pdf/2610.18323v1.pdf","matched_keywords":["multimodal","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18305v1","title":"AffectWorld: Benchmarking Emotion-Driven Future World Prediction","abstract":"The world encompasses both physical environments and human actors. Predicting its evolution requires understanding both physical laws and how emotions shape human actions. However, existing world model benchmarks primarily assess physical plausibility and perceptual quality, leaving emotion-driven world evolution largely untested.We introduce AffectWorld, a benchmark that evaluates the chain Emotion-Action-World State through three tasks: World-State Consistency, Emotion-Action Consistency, and Causal Consistency. It comprises 1,498 everyday video samples annotated with plausible emotions, action tendencies, and atomic world-state constraints. A counterfactual subset of 233 samples tests whether changing an agent's emotion under fixed scene and event conditions yields corresponding changes in actions and consequences. We define eight metrics across the three tasks and an additional counterfactual metric, combining automatic visual assessment with human-calibrated VLM/LLM judgments. Evaluations of five SoTA world models (e.g., Cosmos3) required world-state change scores of 0.100-0.280 and counterfactual emotion sensitivity scores of 0.027-0.070 on a [0, 1] scale. These results reveal substantial gaps in generating the consequences of emotion-driven actions and adapting future predictions to emotional interventions. AffectWorld provides a testbed for advancing world models that capture how emotions shape future physical and social states.","authors":["Changhao Song","Yacong Chen","Hui Gao","Yazhou Zhang","Peng Zhang"],"published":"2026-10-13T12:50:40Z","updated":"2026-10-13T12:50:40Z","abstract_url":"https://arxiv.org/abs/2610.18305v1","html_url":"https://arxiv.org/html/2610.18305v1","pdf_url":"https://arxiv.org/pdf/2610.18305v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18289v1","title":"LongForcing: Scaling Temporal Manifold Matching for Long-Horizon World Rollout","abstract":"Autoregressive video diffusion models have emerged as a foundation for long-horizon world rollout. However, when extended far beyond their training windows, these models suffer from progressive drift: visual quality deteriorates, motion becomes inconsistent, and object identity gradually collapses as generated frames are recursively reused as context. We study a supervision-horizon gap: short-horizon distillation leaves later rollout states without direct supervision. We show that matching short-window marginals need not determine long-horizon behavior, while longer on-policy trajectories expose delayed failures to training. This motivates temporal manifold matching at scale for long-horizon world models. Building on this insight, we introduce LongForcing, a distillation approach that scales teacher supervision to long student self-rollouts. LongForcing preserves the short-horizon teacher-forcing and causal ODE-distillation stages, while replacing the realscore teacher in the final distribution-matching stage with an extended-horizon bidirectional teacher. The long-horizon teacher supervises extended student self-rollouts using the standard distribution-matching formulation, without modifying the student architecture or increasing inference cost. We evaluate LongForcing on text-to-video generation and interactive action-conditioned world models, achieving a VBench Quality score of 85.52 and improving WorldRoamBench 60s action score by 23.9 points in first-person ablations. Qualitative stress tests further sample interactive rollouts up to 24 hours, far beyond the training horizon. These results suggest that scaling supervision along the temporal axis is a practical step toward long-horizon world models. The project website and code are at https://github.com/Fantasy-AMAP/LongForcing.","authors":["Ziyu Zhu","Zhaoxu Sun","Fan Jiang","Mengchao Wang","Junfeng Ni","Ting-Bing Xu","Zhicheng Liu","Mu Xu"],"published":"2026-10-13T12:39:00Z","updated":"2026-10-13T12:39:00Z","abstract_url":"https://arxiv.org/abs/2610.18289v1","html_url":"https://arxiv.org/html/2610.18289v1","pdf_url":"https://arxiv.org/pdf/2610.18289v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18243v1","title":"LiFUSE: Frequency-Spatial Unified Self-Supervised Pretraining for Liver Disease Analysis on Non-contrast CT","abstract":"Given the growing global burden of liver tumors and diffuse liver diseases, non-contrast computed tomography (NCCT) is increasingly used for opportunistic screening because of its low cost and favorable safety profile. However, downstream tasks such as tumor detection and fine-grained disease diagnosis remain challenging due to NCCT's inherently low tissue contrast, lack of hemodynamic enhancement, and complex anatomical background. These limitations make subtle, heterogeneous, and multifocal hepatic lesions difficult to identify. Although large-scale self-supervised pretraining can learn robust representations from unlabeled NCCT scans, conventional voxel-wise reconstruction does not fully exploit the complementary information available in NCCT. Under weak NCCT contrast, low-level intensity patterns become less informative for pathology recognition, limiting the capture of lesion-specific discriminative features. In this paper, we propose the Liver Frequency-Spatial Unified Self-Supervised Pretraining (LiFUSE). The frequency branch applies random band-stop masking and spectrum reconstruction to encourage the model to capture subtle differences between lesions and surrounding tissues, while the spatial branch performs hybrid-granularity masked volumetric reconstruction to accommodate lesions of diverse sizes and morphologies. Finally, a cross-domain consistency scheme couples the spatial and frequency branches, yielding more discriminative representations for hepatic structures and lesions. Extensive experiments on three clinically relevant tasks across internal cohorts and a public target-domain transfer setting show that LiFUSE consistently outperforms strong baselines. These results suggest that unified frequency-spatial learning can improve liver disease analysis on NCCT, highlighting its potential for large-scale screening.","authors":["Hao Zhang","Yi Huang","Wei Liu","Yuan Gao","Zeju Li","Xu Han","Yu Shi","Ling Zhang","Ke Yan"],"published":"2026-10-13T12:08:56Z","updated":"2026-10-13T12:08:56Z","abstract_url":"https://arxiv.org/abs/2610.18243v1","html_url":"https://arxiv.org/html/2610.18243v1","pdf_url":"https://arxiv.org/pdf/2610.18243v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18238v1","title":"Heading Hierarchy Reconstruction for Complex and Long Documents with Level-Wise Multimodal Memory","abstract":"Vision-language models (VLMs) have been widely adopted for document parsing and optical character recognition (OCR), as they can accurately extract page-level elements. However, downstream applications such as retrieval-augmented generation (RAG) also require coherent document-level structure. Although these models indicate heading levels using different numbers of preceding ``\\#'' symbols, page-by-page prediction often lacks document-level consistency. In practice, input-resolution and context-length constraints make it infeasible for a VLM to jointly process all page images in documents containing tens or hundreds of pages. To address this limitation, we propose a VLM-based framework that incrementally reconstructs heading hierarchies with a \\emph{level-wise multimodal memory}. The memory retains a compact subset of all previously processed pages, selected by anchors. Our framework supports flexible anchor selection, and in this work we select the most recent node at each level, allowing the VLM to observe the visual, textual, and layout patterns of headings at every level. For comprehensive evaluation, we also introduce the Complex and Long Document Heading Hierarchy Reconstruction Benchmark (CLDoc-HHRBench), comprising 250 documents and 11,212 pages with expert-verified annotations. Experiments on CLDoc-HHRBench and three existing benchmarks demonstrate the effectiveness of our method.","authors":["Qian Chen","Xianyin Zhang","Lifan Guo","Chi Zhang"],"published":"2026-10-13T12:06:28Z","updated":"2026-10-13T12:06:28Z","abstract_url":"https://arxiv.org/abs/2610.18238v1","html_url":"https://arxiv.org/html/2610.18238v1","pdf_url":"https://arxiv.org/pdf/2610.18238v1.pdf","matched_keywords":["retrieval","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18227v1","title":"A Controlled Evaluation of Curvature Inspired Scalar Feature Scaling for Domain Generalization","abstract":"Domain-specific curvature is an appealing idea for domain generalization (DG), but curvature learning can denote substantially different computations. This paper evaluates one deliberately narrow implementation: the code calls it HyperDG, but it rescales Euclidean encoder features during training by learned positive scalars and uses an ordinary linear classifier on unscaled Euclidean features at inference. It does not implement a Lorentz or Poincaré representation, geodesic prediction, or a Sharpness-Aware Minimization inner loop. We audit the executed objective and evaluate six conditions on PACS, VLCS, Office Home, and TerraIncognita. The completed design contains 384 runs: six conditions, four held-out targets, and four run seeds per dataset. Checkpoints are selected using only the three source-validation environments. Inference first averages paired seed differences within each held-out target; targets, rather than 16 seed-by-target observations, are the per-dataset clusters. The full implementation's equal-dataset macro point estimate is 1.61 percentage points below native DomainBed ERM (95% clustered CI [-3.17, -0.04]). All four dataset point estimates favor ERM, but an exact four-dataset sign-flip test gives p = .125 and Holm-adjusted p = .250; we therefore claim no adjusted evidence of a difference. The cleaner domain-specificity contrast, separate learned source scales without their variance penalty versus one shared learned source scale, is -0.13 pp (95% CI [-0.53, 0.27]). Its 90% CI lies within a revision-stage $\\pm 1$ pp smallest effect of practical interest (TOST p = .003), supporting equivalence only for the source-selected suite macro, not every dataset, target, or final-step endpoint. The study thus supplies a bounded negative result for this scalar training package; it does not test or refute genuine hyperbolic representation learning.","authors":["Sunny Gupta","Amit Sethi"],"published":"2026-10-13T11:56:18Z","updated":"2026-10-13T11:56:18Z","abstract_url":"https://arxiv.org/abs/2610.18227v1","html_url":"https://arxiv.org/html/2610.18227v1","pdf_url":"https://arxiv.org/pdf/2610.18227v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18209v1","title":"Closing the Estimation Gap: Training-Free Transductive Inference for Cross-Domain Few-Shot Action Recognition","abstract":"Cross-domain few-shot action recognition (CD-FSAR) aims to recognise unseen action classes in a target domain from a handful of labelled videos. Despite advances in representation learning, CD-FSAR inference still relies on prototypes estimated from extremely limited support examples. To assess this bottleneck, we perform an oracle analysis with the representation fixed. Constructing oracle prototypes and decision boundaries from ground-truth query labels improves 5-way 1-shot accuracy by 7--20 percentage points across five target datasets. This reveals a substantial estimation gap: the representation contains useful discriminative information, but prototypes and boundaries estimated from scarce supports fail to capture each episode's true class structure. Motivated by this, we propose TRACE, a training-free transductive inference framework that improves episode-level estimation without modifying the backbone. TRACE comprises two complementary stages. Confidence-Thresholded Transductive Prototype Refinement (CTPR) refines support-based prototypes using confidently predicted queries. The refined prototypes initialise a lightweight per-episode classifier, which Transductive Classifier Refinement (TCR) further adapts by encouraging confident, class-balanced predictions over all queries. Together, the two stages improve prototype and boundary estimation, enabling better use of information in the unlabelled queries. Across five target datasets (HMDB51, UCF101, SSv2, Diving48, and RareAct) in both 1-shot and 5-shot settings, TRACE consistently improves a strong CD-FSAR baseline, including gains of more than six percentage points on HMDB51 1-shot, while recovering much of the oracle-estimated gap. These results suggest that improving test-time estimation is a powerful, broadly applicable complement to representation learning for CD-FSAR under extreme support scarcity.","authors":["Changyi Li","Zeyu Yang","Yu Xiao"],"published":"2026-10-13T11:42:31Z","updated":"2026-10-13T11:42:31Z","abstract_url":"https://arxiv.org/abs/2610.18209v1","html_url":"https://arxiv.org/html/2610.18209v1","pdf_url":"https://arxiv.org/pdf/2610.18209v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18189v1","title":"VARI: Robust Text-to-Video Generation via Group-Structured Intent Alignment","abstract":"Modern text-to-video (T2V) models generate visually compelling videos, yet meaning-preserving changes in prompt wording can substantially alter semantic realization and overall quality. Existing prompt rewriting modifies the inference input, whereas conventional post-training constructs supervision from one prompt formulation at a time; neither explicitly optimizes reliability across equivalent forms. We introduce VARI (Verified Alignment over Representations of Intent), a group-structured framework that treats automatically verified formulations of the same visual intent as a shared supervision unit. VARI builds matched form-seed rollout pools, cross-scores each video against all forms, and applies a wording-independent structured intent audit to identify valid realizations and hard semantic failures. Group-Consistent Distillation (GCD) aligns every verified form with interchangeable valid realizations, while Form-Contrastive Flow-DPO (FC-DPO) learns group-level preferences from audited positive-negative pairs, prioritizing same-seed, different-form contrasts. On HunyuanVideo-1.5, VARI attains the highest T2V-CompBench, VBench, and StoryEval scores among the evaluated methods. On prompt-form extensions of T2V-CompBench and VBench, it improves weakest-form alignment over the strongest prompt-level baselines by 2.45 and 3.55 points and reduces cross-form drop by 30.5% and 32.2%, respectively, while preserving visual quality. Human evaluation, natural-caption controls, prompt-enhancement experiments, diversity analyses, and transfer to LTX-2.3 further support the robustness and transferability of these gains, while VARI requires no additional inference-time module.","authors":["Mingxuan Zhu","Hohei Chan","Shiyuan Liu","Yuanxing Zhang","Lu Chen"],"published":"2026-10-13T11:28:50Z","updated":"2026-10-13T11:28:50Z","abstract_url":"https://arxiv.org/abs/2610.18189v1","html_url":"https://arxiv.org/html/2610.18189v1","pdf_url":"https://arxiv.org/pdf/2610.18189v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18161v1","title":"Benchmarking Multimodal Large Language Models for Zero-Shot Human-Object Interaction","abstract":"Multimodal Large Language Models (MLLMs) have demonstrated strong zero-shot reasoning across diverse domains, but their potential for Human-Object Interaction (HOI) remains unexplored. Unlike traditional HOI approaches that rely on extensive labeled datasets and fixed interaction taxonomies, MLLMs offer flexible reasoning, making them well-suited for dynamic, real-world scenarios. In this work, we present the first systematic study of MLLMs for HOI recognition and detection within a pipeline that combines an external object detector for entity localization with zero-shot multimodal reasoning for interaction understanding. We introduce a benchmark framework for principled zero-shot evaluation, consisting of (i) a unified taxonomy of zero-shot prompting strategies, and (ii) a methodology that transforms token-level logits into interaction scores, enabling fair comparison with specialized HOI models under standard metrics. To support prompt-based evaluation, we additionally construct new question-answer annotations for standard HOI datasets, transforming them into a format suitable for MLLMs. Building on this, we propose two visual prompting strategies, namely Objects as Context and Black Other Objects, that guide MLLMs to target objects while preserving scene context. Experiments on HICO, HICO-DET, and V-COCO demonstrate state-of-the-art zero-shot performance, achieving 53.50 mAP on HICO and 23.69 mAP on HICO-DET. Overall, our work provides a principled benchmarking framework for MLLMs in HOI, opening the door to new models and datasets and enabling flexible open-world interaction understanding.","authors":["Oriol Rabasseda","Zenjie Li","Kamal Nasrollahi","Sergio Escalera"],"published":"2026-10-13T11:05:05Z","updated":"2026-10-13T11:05:05Z","abstract_url":"https://arxiv.org/abs/2610.18161v1","html_url":"https://arxiv.org/html/2610.18161v1","pdf_url":"https://arxiv.org/pdf/2610.18161v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18142v1","title":"FlowCred: Hierarchical Credit Assignment and Functional Coordination for Joint Text-to-Video Post-Training","abstract":"Prompt optimization and generator post-training are two complementary ways to improve text-to-video (T2V) generation, and recent systems increasingly train both modules jointly. However, optimizing a prompt policy and a video generator from the same terminal reward creates two ambiguities: prompt quality is confounded with stochastic generation, and the two modules may realize overlapping local improvements. We introduce FlowCred, a two-level framework for joint T2V post-training. First, hierarchical credit assignment uses matched prompt-seed rollout grids to separate prompt-level credit from prompt-conditioned generator residuals under shared randomness. Second, functional coordination probes alternative current-policy prompts at states from actual generation trajectories, providing generator-aware evidence for prompt optimization while selectively attenuating generator updates already supported by conditioning changes. Across multiple T2V benchmarks, FlowCred consistently improves matched joint-training baselines. On LTX-2.5, FlowCred improves a strictly matched joint-training control from 61.47 to 64.46 on T2V-CompBench and from 55.58 to 58.08 on StoryEval, without increasing decoded-video or reward-model-call budgets. Factorial and realized-update analyses show complementary contributions from prompt shaping and generator routing, while human evaluation and transfer across backbones and updater families provide further supporting evidence.","authors":["Mingxuan Zhu","Yanwei Huang","Shiyuan Liu","Xinzhi Zhang","Shujie Li","Yuanxing Zhang","Lu Chen"],"published":"2026-10-13T10:48:01Z","updated":"2026-10-13T10:48:01Z","abstract_url":"https://arxiv.org/abs/2610.18142v1","html_url":"https://arxiv.org/html/2610.18142v1","pdf_url":"https://arxiv.org/pdf/2610.18142v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18125v1","title":"H-DDCM: Hadamard Codebooks for Fast Generative Image and Video Compression","abstract":"Training-free diffusion-based compression methods repurpose the generative priors of a diffusion or a flow model to compress data without retraining them as task-specific codecs. Recent codebook-based approaches such as Turbo-DDCM achieve strong perceptual quality at ultra-low bitrates, but their reliance on dense Gaussian codebooks remains costly in both memory and computation, and scales poorly with the large latent dimensions of modern image and video generators. Their combinatorial bitstream encoding further becomes computationally heavy at this scale. We introduce H-DDCM, a scalable generative compression framework that replaces Gaussian codebooks with implicit randomized Hadamard dictionaries. The fast Walsh-Hadamard transform allows for implicitly synthesizing full-dimensional dictionaries with $O(d \\log d)$ compute for projection and reconstruction and $O(d)$ memory, without materializing the full-dimensional dictionary. We further introduce an efficient table-free lexicographic coding scheme that makes combinatorial encoding practical at larger dimensions. Beyond images, we adapt the framework to an autoregressive video flow model and develop a streaming compression scheme that periodically re-encodes recently reconstructed frames into a fresh KV-cache prefix, preserving temporal context across segments at no additional transmitted bits. This enables long-form, close to real-time generative video compression on a single GPU. Across image and video benchmarks, H-DDCM achieves competitive rate-distortion-perception performance while substantially reducing the memory and computational overhead of codebook-based training-free generative compression.","authors":["Or Ronai","Vladimir Kulikov","Tomer Michaeli"],"published":"2026-10-13T10:36:58Z","updated":"2026-10-13T10:36:58Z","abstract_url":"https://arxiv.org/abs/2610.18125v1","html_url":"https://arxiv.org/html/2610.18125v1","pdf_url":"https://arxiv.org/pdf/2610.18125v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18110v1","title":"SYNPRED: A Synergistic Approach to Multimodal Learning for Clinical Prediction","abstract":"Multimodal medical data captures complementary aspects of disease. It provides a comprehensive basis for diagnosis and the identification of biological associations linked to progression or treatment response. Established contrastive learning approaches exploit shared information across modalities, but fall short in exploiting complementary, modality-specific signals relevant for a task. Here, we propose a synergistic multimodal variational autoencoder (VAE) framework that separates task-relevant unimodal and multimodal information from instance-specific variation task-irrelevant, allowing complementary signals across modalities to be leveraged for prediction. The method yields benefits even if modalities are missing at test time. We evaluate the method on a treatment response prediction task using medical imaging and RNA data. Empirical comparison with alignment-based and multimodal VAE state-of-the-art approaches demonstrates improved multimodal prediction performance, and consistent benefits for prediction from a single modality after multimodal training. The full code can be found here: https://github.com/cirmuw/SYNPRED.","authors":["Ivana Janíčková","Yen Y. Tan","Thomas H. Helbich","Philipp Seeböck","Julieta Di Marco","Zsuzsanna Bago-Horvath","Ulrike Heber","Thomas Spiegel","Georg Langs"],"published":"2026-10-13T10:24:09Z","updated":"2026-10-13T10:24:09Z","abstract_url":"https://arxiv.org/abs/2610.18110v1","html_url":"https://arxiv.org/html/2610.18110v1","pdf_url":"https://arxiv.org/pdf/2610.18110v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18097v1","title":"APT: Feedback-Driven Agentic Post-Training for Text-to-Image Generation","abstract":"Post-training is crucial for improving text-to-image models, yet existing pipelines typically rely on manually curated training data and fixed training distributions. We introduce APT (Agentic Post-Training), a fully automated framework that adaptively post-trains a base model according to its evolving capability profile. APT coordinates three agents to construct evaluation sets from user requirements, diagnose model-specific strengths and failure modes, and generate reinforcement learning data with an adaptive prompt distribution that emphasizes underperforming capabilities. By repeatedly evaluating, diagnosing, and updating the generator, APT lets the current model's behavior shape its next training tasks, forming a feedback loop inspired by recursive self-improvement. For general-purpose settings without user-specified evaluation scenarios, we further develop an evaluation harness that enables broad and diverse evaluation set generation. Experiments across multiple base models, benchmarks, and generation architectures demonstrate that APT is model-agnostic, benchmark-agnostic, architecture-agnostic, and fully automated.","authors":["Sirui Zhang","Fangyun Wei","Dong Chen","Jinjing Zhao","Yitong Wang","Yunuo Chen","Baining Guo","Zheng-Jun Zha"],"published":"2026-10-13T10:14:23Z","updated":"2026-10-13T10:14:23Z","abstract_url":"https://arxiv.org/abs/2610.18097v1","html_url":"https://arxiv.org/html/2610.18097v1","pdf_url":"https://arxiv.org/pdf/2610.18097v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18072v1","title":"LensErase: A Foundation Model for Erase Anything","abstract":"We introduce LensErase, a general-purpose mask-based Erase Anything foundation model designed to cover a broad spectrum of real-world erase scenarios. LensErase supports diverse objects, visual text, watermarks, associated visual effects, multiple-object removal, and a wide range of object scales, aspect ratios, and image resolutions. First, to enable such broad coverage, we construct LensErase-100M, a large-scale dataset containing 101.07 million paired source-mask-target examples spanning diverse erase scenarios. Second, we pretrain LensErase from the text-to-image model Lens, adapting its strong generative prior to mask-based erasing. To efficiently incorporate the source image and erase mask, we propose Mask-Aware RoPE, a 3D rotary positional encoding that directly injects mask information into the source-image tokens without introducing a separate mask token sequence. Finally, we refine the model through supervised fine-tuning and reinforcement learning with contract-guided, region-aware rewards, and apply TraceFusion at inference to preserve high-fidelity content outside the effective edit region. Across six public benchmarks and the proposed LensErase-Bench, LensErase achieves substantial improvements under both reference-based objective metrics and reference-free VLM evaluation. We hope LensErase can serve as a foundational model for erase-related applications and systems.","authors":["Yunuo Chen","Xiuyu Wu","Qinhong Yang","Jinjing Zhao","Yanchen Dong","Sirui Zhang","Dong Chen","Fangyun Wei","Lei Shi","Ji Li","Dongdong Chen","Guo Lu","Yan Lu","Baining Guo"],"published":"2026-10-13T09:56:02Z","updated":"2026-10-13T09:56:02Z","abstract_url":"https://arxiv.org/abs/2610.18072v1","html_url":"https://arxiv.org/html/2610.18072v1","pdf_url":"https://arxiv.org/pdf/2610.18072v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18038v1","title":"Data-Free Continual Learning for World Action Model with Rectified Generative Replay","abstract":"World action models (WAMs) built on pretrained video generation models adapt quickly to new robotic tasks, but they forget previously learned tasks under sequential fine-tuning. Experience replay (ER) mitigates such forgetting by rehearsing data of previous tasks, yet this data is often unavailable in robotics, where a policy is deployed as weights only and its training data is not shared along with it. In this work, we ask whether a WAM can achieve data-free continual learning by regenerating its own past. Our key observation is that a WAM can indeed autoregressively regenerate complete rollouts of previously learned tasks and replay them to mitigate forgetting. However, replaying such raw rollouts still lags far behind replaying real data, which we attribute to two issues. First, the WAM is unable to recognize task completion and keeps generating purposeless motion after the task is done. Second, under open-loop generation, the generated actions gradually drift away from the generated observations. To address both issues, we present rectified generative replay (R$^2$-WAM), which truncates generated rollouts at task completion with an agentic evaluator and filters out rollouts whose actions are physically inconsistent with the observations. On the four LIBERO suites and five real-world tasks, R$^2$-WAM reduces forgetting by over 90% relative to sequential fine-tuning and nearly matches ER without accessing any data from previous tasks. Our analysis further reveals that forgetting in WAMs concentrates in inverse dynamics modeling: a forgotten WAM still produces visually plausible observations of previous tasks while its generated actions fail.","authors":["Kaipeng Fang","Hangxu Liu","Chaojian Shi","Yunsong Zhou","Hongzi Zhu","Minyi Guo","Jingkuan Song","Lianli Gao"],"published":"2026-10-13T09:27:32Z","updated":"2026-10-13T09:27:32Z","abstract_url":"https://arxiv.org/abs/2610.18038v1","html_url":"https://arxiv.org/html/2610.18038v1","pdf_url":"https://arxiv.org/pdf/2610.18038v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18034v1","title":"COMPASS: Contextual Moment Prior Alignment for Generalizable AIGI Detection","abstract":"Generalizable AI-generated image (AIGI) and deepfake detection remain challenging due to the asymmetry phenomenon, where adaptation to limited training distributions can degrade the transferable representations of Vision Foundation Models (VFMs). Recent subspace adaptation methods mitigate this issue by freezing high-magnitude principal components while adapting the residual subspace. However, such magnitude-based decomposition is data-agnostic and does not explicitly account for target-relevant semantics, potentially leading to semantic misalignment. We propose COMPASS (COntextual Moment Prior Alignment for Subspace Separation), a data-aware subspace adaptation framework that uses a small unlabeled Semantic Proxy Set to estimate target activation statistics. COMPASS incorporates activation covariance into the decomposition of pre-trained weights, preserving target-relevant representations as a stable semantic reference while the residual adapter learns forgery-related variations. The proxy calibration requires no gradient-based optimization. Extensive experiments demonstrate strong generalization across cross-dataset, cross-method, joint cross-dataset-method, and open-world cross-generator evaluations, achieving state-of-the-art performance on both Deepfake and AIGI detection benchmarks.","authors":["Zhan Yang","Tiancheng Shen","Weijie Lyu","Shuo Chen","Bernard Ghanem","Yibo Yang","Ming-Hsuan Yang"],"published":"2026-10-13T09:23:12Z","updated":"2026-10-13T09:23:12Z","abstract_url":"https://arxiv.org/abs/2610.18034v1","html_url":"https://arxiv.org/html/2610.18034v1","pdf_url":"https://arxiv.org/pdf/2610.18034v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18030v1","title":"FlowSim: Rendering-Free Closed-Loop Simulation for Evaluating End-to-End Driving Systems","abstract":"Closed-loop evaluation of end-to-end (E2E) driving systems typically relies on generating sensor observations and re-processing them through the perception encoder, introducing substantial computational cost and a sim2real gap between simulated and real sensor observations. In this paper, we ask a more fundamental question: is image-space simulation necessary for closed-loop evaluation of E2E driving systems? We propose FlowSim, a rendering-free simulation paradigm that predicts the internal latent representation directly from a previous latent and target-frame symbolic scene conditions. The predicted latent is then processed by the original frozen downstream modules, eliminating image rendering and perception re-encoding. Explicit cross-frame agent association improves latent transition prediction and rollout stability, while variable-horizon simulation enables long-horizon prediction from a common real anchor without accumulating intermediate rollout errors. Experiments on nuScenes and NavSim demonstrate that FlowSim preserves downstream behavior competitively with, and often exceeds image-space simulation in source-to-reference agreement across variable simulation horizons and both dense and sparse latent representations. By predicting the latent directly, both instantiations of FlowSim simulate each step in 0.04--0.06s, substantially faster than the image-space simulation methods they are compared against. These results establish FlowSim as an efficient and practical alternative to conventional image-space simulation methods.","authors":["Hanfeng Wu","Alvaro Marcos-Ramiro","Michael Schmidt","Christoph Stiller"],"published":"2026-10-13T09:21:40Z","updated":"2026-10-13T09:21:40Z","abstract_url":"https://arxiv.org/abs/2610.18030v1","html_url":"https://arxiv.org/html/2610.18030v1","pdf_url":"https://arxiv.org/pdf/2610.18030v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18018v1","title":"Dynamic Interpolation for Training-Time Prediction Reshaping in Low-Light Image Enhancement","abstract":"Low-light image enhancement (LLIE) is an important image/video processing problem for reliable visual systems under poor illumination, yet it remains challenging due to the strong coupling among insufficient illumination, noise amplification, and structural degradation. Existing methods typically rely on sophisticated network architectures or engineered objective functions. While effective, the former increases model complexity and deployment burden, whereas the latter relies on empirically tuned loss weights. We revisit supervised LLIE from a training-dynamics perspective and observe that brightness-related errors tend to converge early, while residual noise and structural artifacts often remain insufficiently optimized in later stages. To address this issue, we propose a Dynamic Interpolation Training-only Module (DITM), which introduces no additional learnable parameters and adaptively reshapes the model prediction for supervised feed-forward LLIE training. Specifically, DITM employs brightness-aware interpolation, in which the model prediction is combined with a mean brightness-aligned image constructed by rescaling the model prediction according to the mean brightness of the ground-truth image. By reducing the relative dominance of global brightness discrepancy, DITM makes residual local errors more influential during backpropagation after global luminance has largely stabilized, thereby facilitating artifact suppression and fine-detail restoration in later training stages. DITM is used only during training and is fully removed at inference, introducing no additional inference cost. Extensive experiments on multiple benchmark datasets and CNN-, Transformer-, and Mamba-based LLIE backbones show that DITM consistently improves fidelity and perceptual quality while preserving the inference-time architecture and introducing no additional inference-time computation.","authors":["Peirui Zhu","Shijie Hao","Jingxi Liao","Richang Hong","Meng Wang"],"published":"2026-10-13T09:14:49Z","updated":"2026-10-13T09:14:49Z","abstract_url":"https://arxiv.org/abs/2610.18018v1","html_url":"https://arxiv.org/html/2610.18018v1","pdf_url":"https://arxiv.org/pdf/2610.18018v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-10-14T05:43:07+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":69,"new_or_recent_papers":[{"id":"2610.18874v1","title":"ChunkAct: Action Chunking for Agentic Robotics","abstract":"Agentic robotics places a large language model (LLM) agent in the robot control loop, where it composes perception, motion, and vision-language-action (VLA) tools under the guidance of a memory and thereby generalizes to new tasks without retraining. This generality comes at a steep price in efficiency. Every primitive requires a round of LLM reasoning over the full interaction history, so the cost of an episode grows with the number of primitives. We find this reasoning largely redundant: once a sub-goal is chosen, its primitives follow a routine already prescribed by memory. We present ChunkAct, which introduces action chunking to agentic robotics. Online, a single call launches a chunk of chained primitives, which executes autonomously and returns control only upon failure. Offline, ChunkAct compiles the memory into these chunks, so execution is memory-free at test time and the planner is reserved for decisions that require reasoning. LLM computation therefore scales with the number of decisions rather than the number of primitives. On LIBERO-Pro, ChunkAct improves task success by 5.0 points over the state of the art in agentic robotics while requiring 2.9x fewer LLM calls, 4.4x fewer input tokens, and 2.3x fewer output tokens.","authors":["Bingxin Xu","Wenrui Bao","Xinxin Liu","Jiawei Zhou","Yuzhang Shang","Emilio Ferrara"],"published":"2026-10-13T17:59:57Z","updated":"2026-10-13T17:59:57Z","abstract_url":"https://arxiv.org/abs/2610.18874v1","html_url":"https://arxiv.org/html/2610.18874v1","pdf_url":"https://arxiv.org/pdf/2610.18874v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":55001,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Agentic robotics places a large language model (LLM) agent in the robot control loop, where it composes perception, motion, and vision-language-action (VLA) tools under the guidance of a memory and thereby generalizes to new tasks without retraining. This gen...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18873v1","title":"LoopWAM: Closed-Loop Generalist Policy Improvement from Deployment Rollouts","abstract":"Scaling expert demonstrations alone does not enable generalist robot policies to improve from deployment. Real-world rollouts contain successes, suboptimal behavior, and failures: imitating every recorded action can reinforce poor behavior, while filtering out failures discards evidence of physical interactions and their consequences. We introduce \\textbf{LoopWAM}, a closed-loop world-action model that learns directly from this full quality spectrum, using rollouts from both itself and other deployed policies. Source-dependent noise sampling unifies behavior learning and action-conditioned world modeling, while quality steering and quality-weighted supervision retain full video supervision across qualities and regulate action imitation. Video and action tokens interact throughout parallel denoising, allowing learned consequences to inform action generation directly. On RoboChallenge Table30-V2, three deployment-and-training rounds raise success from 23.67\\% to 43.33\\%, a 19.7-percentage-point gain, with a final score of 56.80. LoopWAM also achieves 94.5\\% average success on RoboTwin~2.0 and 49.5\\% overall success on RoboCasa365 without additional embodied pretraining, obtaining the best overall results among the compared methods across all three benchmarks. On challenging shirt folding task, two rounds of deployment-driven improvement after single-task post-training raise success from 13.20\\% to 55.56\\%. These results demonstrate closed-loop improvement from mixed-quality experience under both multi-task learning and single-task post-training. \\href{https://loop-wam.github.io/}{\\textcolor{orange}{Project Page}}","authors":["Wenxuan Guo","Yingping Liang","Zhaoguo Wang","Ziyuan Li","Angyuan Ma","Zhenyu Wu","Chengkun Wang","Bingyao Yu","Ze Chen","Borui Zhang","Xiuwei Xu","Meng Zhang","Erjin Zhou","Jiwen Lu"],"published":"2026-10-13T17:59:56Z","updated":"2026-10-13T17:59:56Z","abstract_url":"https://arxiv.org/abs/2610.18873v1","html_url":"https://arxiv.org/html/2610.18873v1","pdf_url":"https://arxiv.org/pdf/2610.18873v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":59748,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Scaling expert demonstrations alone does not enable generalist robot policies to improve from deployment. Real-world rollouts contain successes, suboptimal behavior, and failures: imitating every recorded action can reinforce poor behavior, while filtering ou...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18872v1","title":"EgoExplorer: A Vision-Motion-Touch Observatory for Human Loco-Manipulation In Situ","abstract":"Learning humanoid loco-manipulation from human demonstrations rests on observing how locomotion, posture, and object interaction evolve together as tasks unfold. Scaling collection across diverse environments, in turn, favors lightweight, portable capture systems. Yet, existing datasets provide only partial views of this coordination. Thus, we introduce EgoExplorer, a 100-hour vision-motion-touch observatory of human loco-manipulation built with a wearable system. With an emphasis on professional activities, its continuous recordings align egocentric video with reconstructed whole-body motion, fine-grained finger articulation, and tactile observations, accompanied by step-level descriptions. To achieve this coverage with sparse body sensing, we develop the Calibrate-Complete-Constrain pipeline. Concretely, reusable calibration fixes participant geometry and sensor attachments before motion inference to disentangle mounting offsets from articulation. A temporal prior then completes unobserved joint motion, while layered constraints promote measurement agreement, temporal continuity, and geometric consistency, properties that motion plausibility alone does not guarantee. Against tracker-fitted references, the method reduces body-point error by 71.9% relative to the strongest baseline; matched evaluations also show gains in hand stability and contact estimation. Preliminary studies explore multimodal generation and conditioning alongside humanoid retargeting with whole-body control in simulation.","authors":["Yunsong Zhou","Xuekun Jiang","Haiqi Shen","Hangxu Liu","Chaojian Shi","Yujie Liu","Jingyuan Li","Haoran Yang","Jiafei Cao","Dongzhan Zhou","Dong Wang","Yao Mu","Chunhua Shen","Weinan Zhang"],"published":"2026-10-13T17:59:55Z","updated":"2026-10-13T17:59:55Z","abstract_url":"https://arxiv.org/abs/2610.18872v1","html_url":"https://arxiv.org/html/2610.18872v1","pdf_url":"https://arxiv.org/pdf/2610.18872v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":138789,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Learning humanoid loco-manipulation from human demonstrations rests on observing how locomotion, posture, and object interaction evolve together as tasks unfold. Scaling collection across diverse environments, in turn, favors lightweight, portable capture sys...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18870v1","title":"Dog-Breed Text-to-image Flow Matching from Pretraining to Fine-Tuning on 4 Consumer GPUs","abstract":"We generally perceive that training text-to-image diffusion models requires heavy compute: it is true if we aim at a comprehensive frontier model. This understanding prevents people from training their own models when getting started in the field. We develop MiniDog, a framework that enables pretraining diffusion transformers in 55 minutes and fine-tuning in another 15 minutes on four 3090 GPUs. For data, we use 26k dog images from ImageNet and caption them for pretraining and use 2k images generated by FLUX.1-schnell for fine-tuning. We precompute the image and text features and cache them for efficiency. For architecture, we use E2E-INVAE for its semantic latent space, a small transformer with 22M parameters, a small Qwen model for text encoding, and in-context conditioning. For training, we use iREPA and an EUPE perception encoder for acceleration. For evaluation, our repository supports FID, HPSv2 score, PickScore, and various VAE reconstruction metrics.","authors":["Reyhaneh Esmailizadeh","Xingjian Leng","Zhanhao Liang","Liang Zheng"],"published":"2026-10-13T17:59:53Z","updated":"2026-10-13T17:59:53Z","abstract_url":"https://arxiv.org/abs/2610.18870v1","html_url":"https://arxiv.org/html/2610.18870v1","pdf_url":"https://arxiv.org/pdf/2610.18870v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":30920,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：We generally perceive that training text-to-image diffusion models requires heavy compute: it is true if we aim at a comprehensive frontier model. This understanding prevents people from training their own models when getting started in the field. We develop...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18871v1","title":"Cepheid: Decoupling Scale from Structure for Cross-Family Motion Completion","abstract":"Sparse-to-dense motion completion recovers dense mesh motion from sparse vertex displacements. Residual priors trained on one geometry family frequently fail to beat parameter-free harmonic extension off-family. Moreover, cross-family training meets a scaling barrier: residual amplitude varies by more than an order of magnitude across geometry families and collapses as observations become denser. Since this scale depends on unknown target motion, it cannot be measured directly at test time. We decouple residual structure from physical scale by learning a dimensionless prior, estimating amplitude from observables and a lightweight correction fitted only on training sources. Our unified model surpasses harmonic extension across all evaluated families, including unseen cloth and legged bodies, without skeletons, registration, or cross-mesh correspondence. The same prior applies without retraining to point-tracked animal video and a robot grasping a soft body. Project page: https://su-terry.github.io/cepheid-website/","authors":["Chih-Hai Su","Tsung-Wei Ke","Yu-Lun Liu"],"published":"2026-10-13T17:59:53Z","updated":"2026-10-13T17:59:53Z","abstract_url":"https://arxiv.org/abs/2610.18871v1","html_url":"https://arxiv.org/html/2610.18871v1","pdf_url":"https://arxiv.org/pdf/2610.18871v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":120475,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Sparse-to-dense motion completion recovers dense mesh motion from sparse vertex displacements. Residual priors trained on one geometry family frequently fail to beat parameter-free harmonic extension off-family. Moreover, cross-family training meets a scaling...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18868v1","title":"Tev: Scaling Long-Horizon Agentic Environments with Dense Progress Rewards","abstract":"Long-horizon agents have drawn growing attention for their ability to work autonomously -- from hours to days -- on economically valuable tasks, a capability essential to automated discovery and recursive self-improvement (RSI). Yet open-source models still struggle on long-horizon tasks, largely for lack of both training data and a working recipe, and scaling both is hard: long, complex tasks are difficult to curate and verify, and their rewards are sparse. We address both. First, we introduce Tev-Gym, the first long-horizon agent training dataset with verifiable, dense, progressive rewards -- 1,170 verified task environments across 7 domains. It is built on a latent-world-first approach that first constructs a latent world: a complete and correct hidden specification of the task domain, workflow, and expected state after each step. Each task is then progressively rendered from this specification into an agent-facing environment, enabling controllable complexity and a natural progress metric. Second, we turn this metric into a training recipe: via progress-potential reward shaping (PPRS), we convert progress into a dense per-step reward that improves training efficiency and makes otherwise-intractable tasks trainable. Training with this recipe yields Tev-27B, which achieves substantial gains on the Agents' Last Exam computing and math sciences domains (ALE-CM), matching GPT-6 Astra and Claude Opus 5 at Pass@5. Despite training only on ALE-related data, it generalizes to the Terminal-Bench (TB) 3.0 and 4.0 subsets, surpassing GLM 5.2 and Gemini 3.7 Flash, and reaches Claude Opus 4.8-level performance on middle-horizon tasks such as TB 2.1.","authors":["Wenbo Hu","Shraman Pramanick","Krishna Kumar Singh","Nanyun Peng","Kai-Wei Chang","Yong Jae Lee"],"published":"2026-10-13T17:59:51Z","updated":"2026-10-13T17:59:51Z","abstract_url":"https://arxiv.org/abs/2610.18868v1","html_url":"https://arxiv.org/html/2610.18868v1","pdf_url":"https://arxiv.org/pdf/2610.18868v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":173556,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Long-horizon agents have drawn growing attention for their ability to work autonomously -- from hours to days -- on economically valuable tasks, a capability essential to automated discovery and recursive self-improvement (RSI). Yet open-source models still s...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18858v1","title":"Visual Tokens on Demand: Visual Budgeting for Scalable and Efficient Multi-Image Reasoning in Multimodal LLMs","abstract":"Multimodal large language models have advanced rapidly, but most remain optimized for single-image inputs. Multi-image reasoning is costly because each image adds many visual tokens, increasing encoding and attention demands. Existing techniques that address the above issue, including visual token pruning, token merging, visual token compression, learned resampling, hierarchical compression, retrieval-augmented visual reasoning, and memory-based architectures, have largely been designed for single-image scenarios, where redundancy is primarily spatial and local. Multi-image reasoning introduces additional challenges: redundancy may occur across images, task-relevant evidence may be sparse or distributed, and aggressive per-image compression can remove details needed for comparison, counting, temporal reasoning, retrieval, or evidence grounding. Moreover, existing token-reduction methods are often either (i) training-free but inference-inefficient, typically relying on accessing attention matrices to get token-importance that may be impractical to access with memory-efficient attention implementations such as FlashAttention, or (ii) training-dependent, requiring the base MLLM to be retrained or adapted to a new compressed-token paradigm. In this work, we study scalable multi-image reasoning and understanding without retraining the base model and without accessing attention matrices at inference time. To this end, we propose mmVB, a lightweight plug-and-play module that assigns query-conditioned per-image token budgets via cross-image context, adding only 1.6M trainable parameters while reducing visual input tokens by 9x. This reduction yields 5x faster time-to-first-token and 7x fewer prefill FLOPs, while maintaining 94.4% of full-resolution accuracy across eight multi-image reasoning benchmarks.","authors":["Aimon Rahman","Joymallya Chakraborty","Vidit Bansal","Abhishek Dan"],"published":"2026-10-13T17:59:24Z","updated":"2026-10-13T17:59:24Z","abstract_url":"https://arxiv.org/abs/2610.18858v1","html_url":"https://arxiv.org/html/2610.18858v1","pdf_url":"https://arxiv.org/pdf/2610.18858v1.pdf","matched_keywords":["retrieval","multimodal"],"source_used":"html","source_text_chars":59105,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models have advanced rapidly, but most remain optimized for single-image inputs. Multi-image reasoning is costly because each image adds many visual tokens, increasing encoding and attention demands. Existing techniques that address...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:08+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18857v1","title":"PixelMoE: Scaling Pixel-Space Diffusion with LLM-Style Mixture-of-Experts","abstract":"Pixel-space diffusion models provide an appealing alternative to latent-space diffusion models by directly modeling raw images without relying on a learned tokenizer. However, scaling pixel-space models has predominantly followed dense strategies, tightly coupling model capacity with active computation. In this work, we show that standard LLM-style Mixture-of-Experts (MoE) architectures can be effectively transferred to pixel-space diffusion. Building on this finding, we introduce PixelMoE, a pixel-space generative framework that sparsely scales model capacity with standard LLM-style MoE, without diffusion-specific routing mechanisms or auxiliary routing objectives. Specifically, PixelMoE combines standard Token-Choice (TC) routing with fine-grained routed experts for input-adaptive sparse computation, a shared expert for capturing common representations, and a bias-based load-balancing strategy. To complement sparse capacity scaling, PixelMoE further introduces Pixel-Space Hierarchical Flow Matching, which varies spatial resolution along the denoising trajectory from global structure formation to fine-grained detail refinement. At comparable active parameter counts, PixelMoE consistently outperforms its dense counterparts across model scales, demonstrating effective sparse capacity scaling in pixel space. On class-conditional ImageNet-1K, PixelMoE achieves FID scores of 1.47 at 256x256 and 1.53 at 512x512 without representation alignment or perceptual losses, comparing favorably with leading pixel-space and latent-space generative models. Code and models will be released soon.","authors":["Ruixiao Dong","Jianmin Bao","Bozhi Luan","Zijie Meng","Xin Tao","Pengfei Wan","Kun Gai","Li Li","Houqiang Li"],"published":"2026-10-13T17:59:21Z","updated":"2026-10-13T17:59:21Z","abstract_url":"https://arxiv.org/abs/2610.18857v1","html_url":"https://arxiv.org/html/2610.18857v1","pdf_url":"https://arxiv.org/pdf/2610.18857v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":92678,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Pixel-space diffusion models provide an appealing alternative to latent-space diffusion models by directly modeling raw images without relying on a learned tokenizer. However, scaling pixel-space models has predominantly followed dense strategies, tightly cou...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18846v1","title":"WorldRecon: Generative Multi-View Mesh Reconstruction for Large-Scale 3D World","abstract":"Reconstructing complete, high-quality meshes of large-scale scenes from unposed multi-view images requires faithful geometric grounding while plausibly completing surfaces that are unobserved or only sparsely captured. We present WorldRecon, a generative multi-view reconstruction framework for recovering complete, large-scale 3D scene meshes from unposed RGB images. WorldRecon uses a coarse, noisy global point cloud and camera poses estimated from the input images by a reconstruction model as a global scaffold for whole-scene generation and partitions it into overlapping spatial blocks. To robustly leverage these imperfect geometric priors, we equip the native 3D generative model TRELLIS.2 with a dedicated reconstruction-based conditioning architecture that generates each block from its local point-cloud crop and block-relevant image observations, producing sparse structure, detailed geometry, and PBR materials. To maintain scene-level coherence, we introduce neighbour-aware latent inpainting and a causal world-generation procedure that propagates structural, geometric, and material context across overlapping blocks. Together, these designs scale multi-view generative reconstruction to large-scale scenes, yielding coherent, unified meshes. Extensive experiments demonstrate that WorldRecon achieves state-of-the-art reconstruction performance, reducing Chamfer distance by 14.9% and 43.1% while improving F-score by 17.3% and 12.0% over the strongest baselines on synthetic and real-world indoor scenes, respectively, thereby demonstrating faithful and complete generative reconstruction as well as strong sim-to-real generalization. Project page: https://kszpxxzmc.github.io/WorldRecon-website/.","authors":["Mengchen Zhang","Yang Li","Chunshi Wang","Tong Wu","Chunchao Guo"],"published":"2026-10-13T17:57:58Z","updated":"2026-10-13T17:57:58Z","abstract_url":"https://arxiv.org/abs/2610.18846v1","html_url":"https://arxiv.org/html/2610.18846v1","pdf_url":"https://arxiv.org/pdf/2610.18846v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":85783,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Reconstructing complete, high-quality meshes of large-scale scenes from unposed multi-view images requires faithful geometric grounding while plausibly completing surfaces that are unobserved or only sparsely captured. We present WorldRecon, a generative mult...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18845v1","title":"The Last Remote Sensing Model Built by Humans? Casting Any Earth Observation Task as Recursive Self-Improvement","abstract":"Earth observation (EO) models are still built by hand. For each new task, experts design a training recipe and tune it against a benchmark. We show that this loop can be handed to an agent. Any verifiable task can be cast as a harness and a verifier, where the harness defines what the agent may use and the verifier defines what counts as success. Every EO task can be made verifiable, through labeled benchmarks, independent sensors, physical models or the repeated observation of the same place. Given only these two components, a general-purpose coding agent builds the EO model and improves it recursively on its own outputs. Settings long treated as separate research problems, from learning with a handful of labels to adapting across domains, become choices of harness and verifier. On four EO benchmarks spanning optical, SAR and multispectral time-series imagery, agent-built models surpass the state of the art and keep most of that accuracy from about 1% of the training labels. This establishes a new paradigm for EO, in which people design harnesses and verifiers and agents build the models, so EO models improve as agents do.","authors":["Sijie Zhao","Zeqi Zhou","Heli Qi","Xuanchao Fu","Zhuo Zheng","Junshi Xia","Junjue Wang","Weihao Xuan","Naoto Yokoya"],"published":"2026-10-13T17:57:51Z","updated":"2026-10-13T17:57:51Z","abstract_url":"https://arxiv.org/abs/2610.18845v1","html_url":"https://arxiv.org/html/2610.18845v1","pdf_url":"https://arxiv.org/pdf/2610.18845v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":81117,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Earth observation (EO) models are still built by hand. For each new task, experts design a training recipe and tune it against a benchmark. We show that this loop can be handed to an agent. Any verifiable task can be cast as a harness and a verifier, where th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18844v1","title":"RepProbe: Can Video Language Models Count Repeated Actions? A Diagnostic Benchmark","abstract":"Repetition counting requires identifying and enumerating action cycles over time. While state-of-the-art video language models describe actions fluently, they fail to reliably count how many times an action repeats. To investigate this limitation, we introduce RepProbe, a benchmark of 42K real and synthetic video clips containing exactly k in [1, 20] complete repetitions, with controls for clip position, temporal coverage, and duration. These controls allow us to study the counting failure directly and locate where in the model it arises. Counting accuracy collapses at high counts across the video language models we evaluate, and controlled experiments show this collapse is not explained by frame sampling alone. We compare model outputs with linear probes trained on the final-layer representations used to generate those outputs. We find a consistent representation-to-output dissociation: substantial count information remains linearly decodable even when models fail to report the correct count. Further analysis shows this failure arises primarily at the output stage, where answers concentrate on a small set of preferred numbers rather than the available count information. The dissociation holds on both real and synthetic videos and is not explained by clip duration, position, or scene content. These results indicate that models encode repetition structure but do not reliably report it in their outputs. Project page: https://arenaa.github.io/RepProbe-webpage/","authors":["Mahsa Khoshnoodi","Sarah Adel Bargal"],"published":"2026-10-13T17:57:43Z","updated":"2026-10-13T17:57:43Z","abstract_url":"https://arxiv.org/abs/2610.18844v1","html_url":"https://arxiv.org/html/2610.18844v1","pdf_url":"https://arxiv.org/pdf/2610.18844v1.pdf","matched_keywords":["video","representation"],"source_used":"html","source_text_chars":57719,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation 相关；摘要显示其主要贡献为：Repetition counting requires identifying and enumerating action cycles over time. While state-of-the-art video language models describe actions fluently, they fail to reliably count how many times an action repeats. To investigate this limitation, we introduc...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18829v1","title":"OmniCompass: A Holistic Benchmark for Omni-Modal Video Grounding and Understanding","abstract":"With the rapid development of multimodal large language models (MLLMs), evaluating their video understanding capabilities has become increasingly important. Existing video understanding benchmarks cover only part of the evaluation dimensions, limiting systematic diagnosis of omni-modal video understanding. We introduce OmniCompass, a holistic benchmark for omni-modal video grounding and understanding. OmniCompass defines two evaluation tracks: OmniCompass-VL assesses vision-language models on tasks requiring visual evidence, while OmniCompass-AV assesses omni-modal models on tasks requiring joint audio-visual evidence. Each track includes three complementary tasks: temporal grounding (TG), spatial grounding (SG), and question answering (QA), assessing when a referenced target appears, where it is, and what happens. QA covers five perception and three reasoning categories in OmniCompass-VL, and three perception and two reasoning categories in OmniCompass-AV. OmniCompass-VL contains 820 videos and 2,460 instances across domains and three duration types: short, medium, and long. A narrative- and audio-rich subset forms OmniCompass-AV with 240 videos and 720 instances. Each instance is evaluated under two paired settings: text-only and text+image, specifying the same target through text and visual-language guidance. All instances are manually annotated with multi-round quality verification. Evaluations of 50 MLLMs show that open-source models still lag behind proprietary counterparts, particularly in audio-visual understanding. Precise temporal and spatial grounding remains challenging even for leading models, and their predictions still exhibit inconsistencies across the paired target specifications.","authors":["Xuyang Liu","Shihao Wang","Xinyu Wei","Minghan Li","Zeqing Wang","Zuhao Yang","Zichen Wen","Lei Zhang"],"published":"2026-10-13T17:54:22Z","updated":"2026-10-13T17:54:22Z","abstract_url":"https://arxiv.org/abs/2610.18829v1","html_url":"https://arxiv.org/html/2610.18829v1","pdf_url":"https://arxiv.org/pdf/2610.18829v1.pdf","matched_keywords":["video","instance","multimodal"],"source_used":"html","source_text_chars":107566,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, instance, multimodal 相关；摘要显示其主要贡献为：With the rapid development of multimodal large language models (MLLMs), evaluating their video understanding capabilities has become increasingly important. Existing video understanding benchmarks cover only part of the evaluation dimensions, limiting systema...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18804v1","title":"Registration is a Representation Problem: Solving Whole-Body PET/CT Registration","abstract":"Raw image intensities are a poor surrogate for similarity across images in correspondence problems. Further, while auxiliary segmentation labels can provide semantic identification and improve matching, they can assign only coarse identities to fine-grained anatomy and often cover only a subset of structures, particularly in whole-body settings. We present an approach that instead establishes correspondence using complementary representations of anatomy and demonstrate its utility for longitudinal whole-body PET/CT registration in the Learn2Reg 2026 PSMAReg Challenge. Our 3D foundation model, anatomix, is used to derive fine-grained, per-voxel semantic representations that are consistent across volumes, and we further employ off-the-shelf segmentation models to obtain coarse anatomical identities. Together, these representations drive a GPU-accelerated iterative registration solver (FireANTs) in a hybrid multistage framework: the first stage estimates alignment from dense multi-channel features, after which a second refines the deformation using both anatomix- and segmentation-based losses. Lastly, because registration should not introduce non-biological tumor volume changes across time, we develop lesion-specific component-wise volume preservation schemes. Without any task-specific training, our system won first place in the PSMAReg Challenge leaderboard. Code and interactive visualizations are available at http://www.neeldey.com/reps-for-reg.","authors":["Neel Dey","Adrian V. Dalca"],"published":"2026-10-13T17:45:34Z","updated":"2026-10-13T17:45:34Z","abstract_url":"https://arxiv.org/abs/2610.18804v1","html_url":"https://arxiv.org/html/2610.18804v1","pdf_url":"https://arxiv.org/pdf/2610.18804v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":33315,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Raw image intensities are a poor surrogate for similarity across images in correspondence problems. Further, while auxiliary segmentation labels can provide semantic identification and improve matching, they can assign only coarse identities to fine-grained a...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18789v1","title":"Trust Before Autonomy: Rethinking Agentic Remote Sensing for Crisis Response","abstract":"Agentic remote sensing is evaluated on how many questions it can answer, whereas crisis response depends on whether its answers can be relied on and how much of the decision can safely be handed to the agent. This paper argues that \\emph{autonomy should be earned, not assumed}: An Earth-Observation (EO) agent should be granted autonomy in proportion to demonstrated reliability, epistemic honesty and verifiability. The position is supported by an evidential meta-analysis of twelve agentic RS/EO/GIS benchmark studies from peer-reviewed venues. Only one repeats runs, three contain unanswerable tasks and none measures calibration. Their own tables show that completed workflows are often not correct (task success exceeds tool-call correctness by up to 54pp on identical queries), that the gap to an expert trajectory widens overall with trajectory length (from 7 to 56pp), and that capability does not predict abstention (Spearman r from -0.25 to 0.50, all n.s.). The paper then contributes three EO-specific trust properties, an autonomy ladder for crisis EO tasks, and a readiness protocol that replays archived emergency activations before any live use. In this context, current evidence justifies assistive roles only.","authors":["Georgios Angelidis","Aggelos Psiris","Spyridon Evangelatos","Thomas Lagkas","Panagiotis Sarigiannidis","Iraklis Varlamis","Georgios Th. Papadopoulos"],"published":"2026-10-13T17:39:23Z","updated":"2026-10-13T17:39:23Z","abstract_url":"https://arxiv.org/abs/2610.18789v1","html_url":"https://arxiv.org/html/2610.18789v1","pdf_url":"https://arxiv.org/pdf/2610.18789v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":55562,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Agentic remote sensing is evaluated on how many questions it can answer, whereas crisis response depends on whether its answers can be relied on and how much of the decision can safely be handed to the agent. This paper argues that \\emph{autonomy should be ea...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18779v1","title":"GAD: Geometry Attention Distillation for Consistent Video Generation","abstract":"Video diffusion models generate visually compelling short-term sequences but often struggle to preserve scene geometry and object structure over time. In this paper, we first demonstrate that current video attention cannot identify reliable correspondences across frames, with responses dispersed across multiple regions even after recognizable scene structure has emerged. We argue that reliable cross-frame associations are essential for information exchange as scene structure forms in video generation. Thus, we introduce Geometry Attention Distillation (GAD), which transfers correspondences from a frozen geometry model's attention to video attention. Extracted from clean videos, these correspondences link the same static surface or moving object across frames. Since structure formation begins in deeper layers at higher noise and shallower layers at lower noise, we apply attention distillation at a student layer selected according to the noise timestep. After training, video attention focuses more consistently on corresponding locations. Experiments across all three video backbones demonstrate improved long-range scene consistency and dynamic temporal consistency, with geometric gains across generation lengths. On Wan2.2 5B, GAD improves cross-frame matching accuracy by at least 30% over the Wan baseline on both long-range benchmarks. Notably, GAD achieves these gains without additional inference modules, offering a promising approach to efficient and consistent video-based world simulation. Project page: https://fantasy-amap.github.io/GAD/.","authors":["Junfeng Ni","Ziyu Zhu","Fan Jiang","Yu Liu","Chiyu Wang","Jiawei Zhang","Zhaoxu Sun","Mu Xu","Siyuan Huang","Yixin Chen"],"published":"2026-10-13T17:33:16Z","updated":"2026-10-13T17:33:16Z","abstract_url":"https://arxiv.org/abs/2610.18779v1","html_url":"https://arxiv.org/html/2610.18779v1","pdf_url":"https://arxiv.org/pdf/2610.18779v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":102854,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：Video diffusion models generate visually compelling short-term sequences but often struggle to preserve scene geometry and object structure over time. In this paper, we first demonstrate that current video attention cannot identify reliable correspondences ac...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:09+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18763v1","title":"LayerCanvas: Infographic Generation in AI Learning Assistants via Hybrid Layer-Set Diffusion","abstract":"Online learning platforms are increasingly deploying AI assistants to provide personalized, on-demand tutoring. These can leverage infographics to communicate complex information and improve the learning experience. However, automating effective infographic generation remains a challenging task, requiring a combination of visual richness with precise typography, structured layouts, and continued editability. Existing representation methods satisfy these goals only in part: Scalable Vector Graphics (SVG) representations preserve geometry, hierarchy, and text but provide limited aesthetic flexibility, while raster diffusion models produce richer appearances by flattening content and layout into a single image. Conditioning a diffusion model on a rasterized SVG does not resolve this conflict because the raster preserves approximate placement but discards element ownership, occlusion relationships, and the structure needed to modify and recompose the result. We introduce LayerCanvas, a hybrid approach that retains SVG as the semantic, structural, and typographic program while using diffusion to aestheticize non-text content. Rather than generating one flattened raster, LayerCanvas partitions SVG elements into z-ordered sets of mutually non-overlapping elements and processes them through communicating parallel RGB generation streams. The resulting layers are independently editable and deterministically recomposed, while text is rendered from preserved vector metadata. Our approach combines rich visual synthesis with accurate typography and localized editing. LayerCanvas substantially improves text fidelity over state-of-the-art raster image generators while achieving the highest overall aesthetic quality. We further demonstrate non-destructive content editing, localization, asset reuse, and animation.","authors":["Keshav Gupta","Jeremy Owen","Christopher Lloyd","Shaunak Mishra","Manav Sharma"],"published":"2026-10-13T17:25:04Z","updated":"2026-10-13T17:25:04Z","abstract_url":"https://arxiv.org/abs/2610.18763v1","html_url":"https://arxiv.org/html/2610.18763v1","pdf_url":"https://arxiv.org/pdf/2610.18763v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":89825,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Online learning platforms are increasingly deploying AI assistants to provide personalized, on-demand tutoring. These can leverage infographics to communicate complex information and improve the learning experience. However, automating effective infographic g...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18741v1","title":"Context-aware Bayesian Fusion for Multimodal Object Detection","abstract":"Reliable detection of pedestrians and road users is essential for the safe operation of autonomous vehicles. However, this task becomes increasingly challenging under adverse environmental conditions, such as poor weather and low lighting, where the performance of state-of-the-art pre-trained object detectors and on-board sensors tends to degrade, which limits their effectiveness and reliability. Moreover, retraining models for each operating context imposes significant constraints due to high data requirements, computational resources, and time. Considering this, we propose a novel context-aware multimodal late fusion approach that integrates a lightweight gating network within our probabilistic calibration framework. The gating network extracts environmental context and dynamically modulates the detection outputs of pre-trained object detectors based on the inferred context, without retraining of the detectors. Our methodology is evaluated on a modified KITTI dataset, in which the camera images and lidar pointclouds are augmented for varying fog levels. Experimental results show that our approach yields an approximately 14% relative improvement over non-adaptive late fusion baselines, achieving a consistent average precision of 56% across different fog levels.","authors":["Arunachalam Venkatachalam","Mhafuzul Islam","Marwan Yusuf","David Van Hamme","Ben Stoffelen","James Foresi"],"published":"2026-10-13T17:10:27Z","updated":"2026-10-13T17:10:27Z","abstract_url":"https://arxiv.org/abs/2610.18741v1","html_url":"https://arxiv.org/html/2610.18741v1","pdf_url":"https://arxiv.org/pdf/2610.18741v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":36395,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Reliable detection of pedestrians and road users is essential for the safe operation of autonomous vehicles. However, this task becomes increasingly challenging under adverse environmental conditions, such as poor weather and low lighting, where the performan...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18697v1","title":"UniW(A)M: A Unified Mixture-of-Experts Framework for World and World-Action Models","abstract":"World models (WMs) and world-action models (WAMs) focus on future world prediction and executable action generation, respectively. Although these models learn shared physical dynamics and interaction semantics from embodied trajectories, they are typically trained in isolation, which restricts knowledge reuse between prediction and control. The central challenge is therefore to develop a unified learning framework that shares these dynamics while preserving the distinct modeling capabilities required by each paradigm. We propose UniW(A)M, a mixture-of-experts world-(action) model built upon diffusion Transformers that unifies action-conditioned world modeling and diverse WAM variants. Shared experts capture common dynamics, while atomic capability experts are reused across interfaces so that each interface keeps its own conditional pathway. At deployment, a plug-in adaptive interface router (PAIR) learns from a small subset of target-task chunk scenarios to select a suitable WAM interface for each execution chunk, balancing task success and execution efficiency while keeping the backbone frozen. We evaluate UniW(A)M on LIBERO, RoboTwin 2.0, and three real-world manipulation tasks, where it achieves 88.3% average real-world success versus 76.7% for the strongest baseline. On WorldArena, it leads action-conditioned world modeling on all three tasks. AC-WM co-training contributes to action generation on every action interface and PAIR raises OOD success from 63.3% to 76.7%.","authors":["Jingbo Xu","Jianjie Fang","Zhuohang Li","Zihao Song","Zhaolu Wang","Xvyuan Liu","Xin Zhang","Haisheng Su","Yinzhou Tang","Chen Gao","Wei Wu","Yong Li"],"published":"2026-10-13T16:47:16Z","updated":"2026-10-13T16:47:16Z","abstract_url":"https://arxiv.org/abs/2610.18697v1","html_url":"https://arxiv.org/html/2610.18697v1","pdf_url":"https://arxiv.org/pdf/2610.18697v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":105445,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：World models (WMs) and world-action models (WAMs) focus on future world prediction and executable action generation, respectively. Although these models learn shared physical dynamics and interaction semantics from embodied trajectories, they are typically tr...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18696v1","title":"CryoTracer: A Synthetic-to-Real System for Filament Instance Tracing in Cryo-EM","abstract":"Particle picking in cryo-electron microscopy is commonly formulated as an object-detection problem in which individual particles are represented by bounding boxes, a natural representation for globular particles but a poor match for filaments that can extend across an entire micrograph. Existing methods reconstruct filament trajectories by linking local predictions in a separate post-processing stage, decoupling detection from instance formation and creating potential ambiguities at gaps and crossings. Directly preserving filament identity is particularly useful for polymorphic specimens, where segments originating from the same filament should remain associated. However, learning such instance-level representations is challenging because expert centerline annotations are scarce and costly to obtain. We introduce CryoTracer, a synthetic-to-real framework that addresses this limitation through procedural micrograph generation, transformer-based polyline prediction, and specimen-specific fine-tuning. Procedural pretraining exposes the model to diverse filament geometries, intersections, and imaging conditions before adaptation using a limited number of fully annotated experimental micrographs. CryoTracer represents filaments as ordered centerline polylines and optimizes their geometry using an orientation-invariant discrete Fréchet objective, enabling consistent learning regardless of tracing direction. Evaluation on established and newly expert-annotated datasets shows that CryoTracer improves instance-level filament recovery over existing particle-detection approaches. These results establish end-to-end polyline prediction as a practical alternative to detection-and-linking pipelines for recovering complete filament instances with limited micrograph annotation budgets. Code and data are available at https://github.com/cryotracer/cryotracer","authors":["Radosław Kuczbański","Wojciech Kozłowski","Mateusz Grzesiuk","Konrad Karanowski","Lukas Frey","Andrzej Rzepiela","Maciej Zięba"],"published":"2026-10-13T16:46:43Z","updated":"2026-10-13T16:46:43Z","abstract_url":"https://arxiv.org/abs/2610.18696v1","html_url":"https://arxiv.org/html/2610.18696v1","pdf_url":"https://arxiv.org/pdf/2610.18696v1.pdf","matched_keywords":["representation","instance"],"source_used":"html","source_text_chars":68602,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, instance 相关；摘要显示其主要贡献为：Particle picking in cryo-electron microscopy is commonly formulated as an object-detection problem in which individual particles are represented by bounding boxes, a natural representation for globular particles but a poor match for filaments that can extend...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18694v1","title":"GeoReader: Learning Latent Geometry for Spatial Reasoning in Vision-Language Models","abstract":"Vision-language models (VLMs) struggle with metric and multi-view relationships that remain implicit in RGB observations. Geometry foundation models recover this structure from RGB, but existing methods either fuse the estimated features with visual tokens and learn to use them from question answering alone, or align VLM latents with geometry features. Capturing geometry, however, does not ensure its use: zeroing the aligned latents of a released feature-alignment model leaves its accuracy unchanged. We introduce GeoReader, a framework that learns geometric representations for the VLM that reads them. First, we train lightweight Geometric Readers to produce continuous input tokens, supervising them with geometry descriptions decoded by a frozen VLM, so that the Readers express geometry in a form the target model can already read. We then freeze the Readers to preserve this interface while fine-tuning the VLM on spatial QA, with geometry injection conditioned on the question. Geometry descriptions serve only as training targets: at inference, the VLM answers directly from the continuous geometric tokens without generating a geometry chain of thought. With geometry predicted from RGB images, our approach reaches 94.3 on MindCube-Tiny with Qwen3-VL-4B and, with a multi-source QA mixture, an average of 72.5 across six additional spatial benchmarks with Qwen3.5-9B. These results suggest that a useful geometric representation is one the receiving model can use, not merely one from which geometry can be reconstructed.","authors":["Rong Li","Shijie Li","Jiangyong Huang","Lingdong Kong","Jiaming Zhou","Dongyue Lu","Zeying Gong","Baoxiong Jia","Junwei Liang","Siyuan Huang"],"published":"2026-10-13T16:45:37Z","updated":"2026-10-13T16:45:37Z","abstract_url":"https://arxiv.org/abs/2610.18694v1","html_url":"https://arxiv.org/html/2610.18694v1","pdf_url":"https://arxiv.org/pdf/2610.18694v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":110094,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Vision-language models (VLMs) struggle with metric and multi-view relationships that remain implicit in RGB observations. Geometry foundation models recover this structure from RGB, but existing methods either fuse the estimated features with visual tokens an...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-10-14T05:43:10+00:00","status":"fallback"},"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18688v1","title":"RSIgen: Reciprocal Self-Improvement for Agentic Visual Generation","abstract":"Agentic visual generation produces experience that can improve the native understanding (agent) and generation roles of a unified multimodal backbone, but task success alone does not determine which role should learn. Generator updates can also make the agent's action supervision stale. We introduce RSIgen, a task-centric reciprocal self-improvement framework linking learning allocation, supervision refresh, and recursive curriculum construction. Dynamic Responsibility Routing (DRR) uses matched interventions on evidence, inputs, and supported actions to select learning recipients and construct compatible training targets. After generator learning, RSIgen re-evaluates the relative utility of tested actions with branch inputs held fixed to refresh agent supervision; the retained roles then construct the next curriculum. Across BAGEL, Qwen-Image, and Wan-Image-7B, RSIgen improves AgentGen-Bench Full Overall9 by 3.2--3.3 points over a three-cycle SearchGen adaptation with action costs. Wan controls support allocation gains at matched role-level training exposure, refresh gains at a matched adaptation budget, and benefits from updated curriculum sources while recipients continue learning. In blind evaluation on 200 real-user requests, pooled tie-adjusted preference scores against the same baseline reach 70.0% for task completion and 64.9% for visual quality.","authors":["Yidi Liu","Haozhe Wang","Jie Xiao","Kai Zhu","Xueyang Fu","Zheng-Jun Zha"],"published":"2026-10-13T16:41:24Z","updated":"2026-10-13T16:41:24Z","abstract_url":"https://arxiv.org/abs/2610.18688v1","html_url":"https://arxiv.org/html/2610.18688v1","pdf_url":"https://arxiv.org/pdf/2610.18688v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18686v1","title":"RadarGSOcc: Doppler-Aware 3D Semantic Occupancy Prediction Using 4D Radar Tensor with Geometric-Semantic Feature Extraction","abstract":"3D semantic occupancy prediction is crucial for autonomous driving, but camera-based methods degrade in low-light conditions and LiDAR-based methods are sensitive to adverse weather. 4D radar is more robust, yet its sparsity and the high cost of radar tensor processing limit its use. We propose Radar Geometric-Semantic Occupancy Prediction (RadarGSOcc), an efficient framework that directly processes 4D radar tensors by separately extracting geometric and semantic features, including Doppler information, with a deformable attention-based geometric refinement module as its key component. We also introduce the K-Radar 3DSemOcc benchmark, the first large-scale benchmark for 3D semantic occupancy prediction using 4D radar tensors, built on the K-Radar dataset with refined LiDAR-based annotations. RadarGSOcc predicts 15 classes within a 51.2m range and achieves 38.2% IoU, 7.6% mIoU, and 25.5% weighted mIoU, outperforming RadarOcc by 17% relative (25.5 vs. 21.9) in weighted mIoU while using fewer parameters and lower computation. It substantially improves truck prediction while trading off car accuracy, outperforms camera-based approaches, and narrows the gap with LiDAR-based methods. To assess robustness without per-frame ground truth in adverse weather, we further propose a novel proxy metric, Environment-Based KL Divergence (EBKL), under which 4D radar proves a reliable and efficient modality for 3D semantic occupancy prediction. The dataset and code will be publicly available.","authors":["Christofel Rio Goenawan","Dong-Hee Paek","Seung-Hyun Kong"],"published":"2026-10-13T16:40:59Z","updated":"2026-10-13T16:40:59Z","abstract_url":"https://arxiv.org/abs/2610.18686v1","html_url":"https://arxiv.org/html/2610.18686v1","pdf_url":"https://arxiv.org/pdf/2610.18686v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18670v1","title":"Perception Beyond the Visible: Incompleteness-Aware Scene Understanding for Robot Autonomy","abstract":"Reliable robot autonomy requires reasoning about the world from partial and noisy observations. However, many perception systems model only visible scene regions, rely on fixed semantic categories, and assume reliable sensor measurements. These assumptions break under occlusion, novel object encounters, and sensor degradation. In this paper, I present a research vision for incompleteness-aware scene understanding. I organize this vision around three fundamental challenges: incomplete evidence, incomplete knowledge, and incomplete sensor reliability. I discuss my research contributions toward addressing these challenges through amodal perception, semantic occupancy forecasting, open-world scene understanding, label-efficient learning, and uncertainty-guided multi-modal fusion. Building on these contributions, I outline future research directions toward belief-centric 4D scene representations. These representations aim to jointly model geometry, semantics, motion, and uncertainty. I also discuss active sensing and safe adaptation strategies that allow robots to reduce uncertainty through interaction. The goal is to develop calibrated and actionable scene representations that support reliable autonomy in dynamic, open-world environments.","authors":["Rohit Mohan"],"published":"2026-10-13T16:29:25Z","updated":"2026-10-13T16:29:25Z","abstract_url":"https://arxiv.org/abs/2610.18670v1","html_url":"https://arxiv.org/html/2610.18670v1","pdf_url":"https://arxiv.org/pdf/2610.18670v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18664v1","title":"PlanPath: Exploration-Guided Orchestration for Patient-Level Pathology Reasoning","abstract":"A patient's pathology case spans tens of slides from distinct specimens and anatomical sites, each carrying non-redundant, site-specific evidence. Forming a patient-level conclusion therefore requires locating the slides relevant to a given question and integrating complementary findings across them. However, existing pathology agents analyze one slide at a time and describe morphology rather than measure it, leaving evidence acquisition across a patient's specimens and patient-level quantification underexplored. To address this gap, we propose PlanPath, an agentic framework for patient-level pathology visual question answering (VQA). PlanPath turns the question into an exploration plan that specifies the evidence required, routes to the slides likely to carry it, and drives coarse-to-fine acquisition from tissue architecture down to individual cells. Tissue- and cell-level tools supply the counts, proportions, and extents, which PlanPath aggregates across slides into a traceable answer. To enable evaluation, we build two patient-level VQA datasets for renal and gastric cancer, averaging 15 WSIs per patient, with pathologist-verified question-answer pairs derived from diagnostic reports. Experimental results show that PlanPath outperforms the strongest baseline by 9.4% and 12.1% in overall accuracy on the two datasets and further improves existing slide-level agents when plugged into our framework. The dataset and code are available at: https://github.com/JSGe-AI/PlanPath_1.","authors":["Jiusong Ge","Mingzhao He","Qidong Liu","Chunbao Wang","Chunze Yang","Di Zhang","Jiashuai Liu","Mireia Crispin-Ortuzar","Huazhu Fu","Chen Li","Zeyu Gao"],"published":"2026-10-13T16:25:58Z","updated":"2026-10-13T16:25:58Z","abstract_url":"https://arxiv.org/abs/2610.18664v1","html_url":"https://arxiv.org/html/2610.18664v1","pdf_url":"https://arxiv.org/pdf/2610.18664v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18655v1","title":"Texture Interpolation as Texton Matching","abstract":"Texture interpolation asks what should lie between two textures. Standard methods typically blend pixels or features at corresponding spatial locations, implicitly assuming that co-located elements should be mixed. For unrelated textures, however, this correspondence is arbitrary: a crack at one location has no particular relationship to a fiber at the same location in another image. We study whether this hidden pairing choice is itself a major determinant of interpolation quality. We represent textures as collections of local appearance vectors, or textons, and replace positional pairing with appearance-aware matching while keeping the encoder, representation, and decoder fixed. This isolates the effect of correspondence from changes in model capacity or training. Across texture pairs, appearance-aware matching consistently improves the distributional quality of interpolated midpoints over positional feature blending. Soft matching produces the strongest midpoint statistics, whereas one-to-one assignments yield more balanced transitions and closer agreement with the target endpoint. The same intervention also improves a second pretrained texture interpolator without retraining. These results identify correspondence as a first-class design choice in texture interpolation: meaningful transitions depend not only on how strongly two textures are mixed, but also on which local appearances are mixed with one another.","authors":["Ido Madar","Gal Oren","Shai Avidan"],"published":"2026-10-13T16:19:42Z","updated":"2026-10-13T16:19:42Z","abstract_url":"https://arxiv.org/abs/2610.18655v1","html_url":"https://arxiv.org/html/2610.18655v1","pdf_url":"https://arxiv.org/pdf/2610.18655v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18645v1","title":"ST-GRU PredRNN-V2: A GRU-Based Reformulation of PredRNN-V2 for Video Prediction","abstract":"Video prediction requires models to capture complex spatiotemporal dependencies and to retain relevant information over long sequences. PredRNN and its successor PredRNN-V2 address this challenge with spatiotemporal Long Short-Term Memory (ST-LSTM) units that maintain two separate memory states, at the cost of a relatively complex recurrent building block. In this work, we investigate whether the simpler gating of Gated Recurrent Units (GRUs) can be transferred to spatiotemporal predictive learning. To this end, we develop a spatiotemporal GRU (ST-GRU) unit as a GRU-based alternative to the ST-LSTM. The ST-GRU replaces the ST-LSTM's three gates per memory state with two GRU-style gates (update and reset), and merges the temporal memory state into the hidden state, which reduces the number of parameters by about 5%. We incorporate the ST-GRU into PredRNN-V2 and evaluate the resulting model on the Moving MNIST video prediction benchmark, following the original experimental protocol. Averaged over ten predicted frames, the ST-GRU-based PredRNN-V2 achieves an MSE of 55.1, an SSIM of 0.883, an LPIPS of 0.065 and a PSNR of 19.53dB. It does not surpass the original ST-LSTM-based PredRNN-V2 on MSE, SSIM or PSNR, but it achieves a lower LPIPS and performs on par with the earlier ST-LSTM-based PredRNN, while using a simpler recurrent cell. These results suggest that ST-GRUs are a promising building block for spatiotemporal predictive learning and motivate further work on their design and integration.","authors":["Augusta van Haren","Hanna Hoogen","Luca Pattavina","Quincy Rommen"],"published":"2026-10-13T16:11:56Z","updated":"2026-10-13T16:11:56Z","abstract_url":"https://arxiv.org/abs/2610.18645v1","html_url":"https://arxiv.org/html/2610.18645v1","pdf_url":"https://arxiv.org/pdf/2610.18645v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18615v1","title":"VideoJev: System One Model for Video Understanding and Interaction","abstract":"Visual agents must turn video observations into timely decisions to track progress and choose what to do next. Building on the emerging System One paradigm, we introduce VideoJev, a family of models that cast video understanding and interaction as structured decision tasks. We adapt pretrained multimodal large language models (MLLMs) by replacing autoregressive answer decoding with a shared head that scores temporal intervals and textual options against video evidence. These scores yield event spans or answer choices, unifying temporal grounding and multiple-choice video question answering. This combines the semantic flexibility of MLLMs with efficient decisions that agents can use directly. As an interaction unfolds, new goals and intermediate results prompt further queries about the same visual history. VideoJev therefore reuses visual computation through Cached inference for queries as they arrive and Joint inference for multiple queries in a single forward pass. Across three temporal grounding benchmarks, VideoJev-4B and VideoJev-35B-A3B improve mean mIoU over their backbones by 6.7 and 10.8 points, respectively, with measured inference speedups of $2.8$-$3.1\\times$. On four video QA benchmarks, both achieve performance comparable to their backbones in Thinking mode, with measured inference speedups exceeding $100\\times$. These results offer a unified, reusable decision interface for composing structured visual judgments into complex, open-ended workflows.","authors":["Yuhan Zhu","Xiangyu Zeng","Qingyi Si","Chenxu Yang","Yifei Li","Luozheng Qin","Junhao Zhou","Dingyu Yao","Jun Zhang","Chuanyu Qin","Zhiqiu Zhang","Yuandong Yang","Yuqi Xu","Tianyu Zhang","Hongcheng Guo","Jiaqi Wang","Nan Duan","Limin Wang"],"published":"2026-10-13T16:00:41Z","updated":"2026-10-13T16:00:41Z","abstract_url":"https://arxiv.org/abs/2610.18615v1","html_url":"https://arxiv.org/html/2610.18615v1","pdf_url":"https://arxiv.org/pdf/2610.18615v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18609v1","title":"DPOison-VL: Clean Preference Poisoning in Vision-Language Direct Preference Optimization","abstract":"Direct Preference Optimization (DPO) has become a widely adopted approach for aligning vision-language models (VLMs), yet the security of multimodal preference data remains largely unexplored. Existing preference poisoning attacks either corrupt explicit supervision signals or require visible triggers, making them detectable under human inspection. We introduce DPOison-VL, the first clean preference poisoning attack against VLM-DPO, which manipulates model alignment solely through imperceptible perturbations on a small fraction of training images, while leaving all prompts, responses, and preference annotations semantically intact. We formulate poison construction as a bilevel optimization and derive a gradient alignment surrogate that efficiently steers image perturbations toward the attacker-specified preference. We further introduce a preference displacement score for principled poison selection with provable first-order optimality under a fixed poison budget, and derive a sufficient condition for preference inversion. Extensive experiments across diverse attack tasks, different VLM architectures and scales, and baseline comparisons demonstrate that DPOison-VL achieves up to 98\\% ASR with only 2\\% poisoned data and exhibits cross-model transferability, while largely preserving clean accuracy and general utility. Our findings reveal a critical vulnerability in VLM-DPO, where imperceptible image perturbations in preference training data can silently redirect alignment.","authors":["Chengtao Jian","Kai Yang"],"published":"2026-10-13T15:58:58Z","updated":"2026-10-13T15:58:58Z","abstract_url":"https://arxiv.org/abs/2610.18609v1","html_url":"https://arxiv.org/html/2610.18609v1","pdf_url":"https://arxiv.org/pdf/2610.18609v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18607v1","title":"Recasting DiT for Extreme Image Compression with Hierarchical Visual Priors","abstract":"Pretrained diffusion models provide powerful generative priors for extreme image compression, but their stochastic, iterative generation processes are not designed to decode compressed representations directly. We present PrismCodec, which recasts a pretrained Diffusion Transformer (DiT) as a bitstream-grounded one-step generative decoder. PrismCodec uses the decoded representation in two complementary roles: a projected codec state defines the starting state for generation, while hierarchical visual priors derived from the same decoded latent provide semantic and structural guidance. To bridge the gap between stochastic, iterative generation and deterministic one-step decoding, we develop a progressive adaptation strategy. We first learn codec-conditioned transport from a noisy neighborhood centered on the codec state, distill it into a one-step mapping, and finally anneal the source perturbation to zero during end-to-end optimization. The resulting decoder reconstructs deterministically from the received representation without additional conditioning bits. Across Kodak, CLIC, and DIV2K, PrismCodec consistently improves rate-perception performance over prior generative codecs, achieving BD-rate reductions of 70-75% in LPIPS and 75-81% in DISTS over StableCodec. Code will be released upon acceptance.","authors":["Yunuo Chen","Jingnan Gao","Bing He","Jinjing Zhao","Chuqin Zhou","Xiaoyue Ling","Li Song","Guo Lu","Wenjun Zhang"],"published":"2026-10-13T15:58:40Z","updated":"2026-10-13T15:58:40Z","abstract_url":"https://arxiv.org/abs/2610.18607v1","html_url":"https://arxiv.org/html/2610.18607v1","pdf_url":"https://arxiv.org/pdf/2610.18607v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18604v1","title":"LLM2R: From Large Language Models to 3D Reassemblers","abstract":"3D part assembly aims to reconstruct a complete shape from a set of unassembled parts by predicting a rigid SE(3) transformation for each part. Because the placement of a part is rarely determined by its own geometry, the task demands reasoning over the entire part set, and existing methods, which rely on pairwise relations or iterative generation and verification, scale poorly to objects with many parts. We present LLM2R, which casts part assembly as sequence modeling with a pretrained decoder-only large language model (LLM): a Point-BERT encoder and a Q-Former compress each part into a block of geometric tokens, the blocks of all parts are concatenated, and a causal LLM adapted with Low-Rank Adaptation (LoRA) processes the sequence in one forward pass. Causal attention, however, lets the hidden states of a part observe only the parts that precede it. LLM2R therefore appends a block of learnable summary tokens after the last part: these tokens follow every part, so their states aggregate the whole assembly at a constant token cost, and a part-aware pose head fuses each part's states with them before predicting its rotation and translation. One architecture thus handles semantic and geometric assembly and predicts all poses in a single non-autoregressive pass. LLM2R achieves the highest part accuracy and success rate on all three PartNet categories, the best rotation error, translation error, and part accuracy on PartNeXt, and the lowest translation error and fastest inference on Breaking Bad, where only a fracture-specialized method is more accurate. Its advantage grows with the number of parts: at 100 parts it exceeds GARF by 33.5 points in part accuracy on Breaking Bad and Assembler by 29.1 points on PartNet, and it transfers zero-shot to unseen categories with more than 16 points higher part accuracy than the strongest of three baselines.","authors":["Zhouhan Zhong","Qiuhong Shen","Xingyi Yang","Jinyi Xu","Xinchao Wang"],"published":"2026-10-13T15:57:41Z","updated":"2026-10-13T15:57:41Z","abstract_url":"https://arxiv.org/abs/2610.18604v1","html_url":"https://arxiv.org/html/2610.18604v1","pdf_url":"https://arxiv.org/pdf/2610.18604v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18598v1","title":"Rethinking Projector Training in Multimodal LLMs","abstract":"Multimodal LLMs are typically trained by first aligning a vision encoder with a language model via projector training on large image-caption datasets, followed by joint training of the full multimodal model. Despite its widespread use, the role of the projector training stage remains poorly understood. We find that (i) using only $10$ to $20\\%$ of the data for training the projector already recovers most downstream performance gains, and (ii) projectors trained on different datasets can be linearly interpolated while largely preserving performance. These results suggest that projector training mainly performs a coarse alignment, which many different projectors achieve equally well. Motivated by these findings, we propose PORTAL, a training-free projector initialization that requires neither paired image-caption data nor gradient-based optimization, but only per-modality summary statistics. PORTAL computes an optimal-transport-based map between Gaussian approximations of the vision and language feature distributions on a shared principal subspace, so that the projector training stage can be skipped entirely. Without any paired data, PORTAL matches the standard pipeline trained on 558k image-caption pairs across six LLM backbones, two vision encoders, and 16 benchmarks. It outperforms that pipeline in $3$ of $7$ (vision encoder, LLM) settings and reaches an average $98\\%$ of its score across the other four.","authors":["Fabian Gröger","Naël Ouerghemi","Shuo Wen","Maria Brbić"],"published":"2026-10-13T15:53:53Z","updated":"2026-10-13T15:53:53Z","abstract_url":"https://arxiv.org/abs/2610.18598v1","html_url":"https://arxiv.org/html/2610.18598v1","pdf_url":"https://arxiv.org/pdf/2610.18598v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18571v1","title":"Parameter-Efficient Multimodal Brain Tumor Segmentation With Stage-Wise Shared Adapters","abstract":"Different MRI modalities reveal different parts of a brain tumor. Segmentation models combine information from these modalities to outline tumor regions. Many models use a separate encoder for each modality. However, exchanging features among these encoders at several stages can increase model complexity. We introduce the Block-Wise Shared Adapter (BWSA), which combines compressed features from the modality encoders in a shared path and returns adapted features to each stream. In its fixed-blending form, BWSA adds the adapted features to the original features. Its trainable-gated variant (TG-BWSA) instead learns separate weights for the original and adapted features at each modality and encoder stage. We evaluate both variants on BraTS 2020 and BraTS 2023 with four segmentation backbones. On the official BraTS 2023 online validation set, BWSA increases average region-wise Dice by 1.3--7.6 percentage points relative to the corresponding unmodified backbones. TG-BWSA increases it by 2.8--7.7 points. Both variants add approximately 0.85--3.73% parameters and reduce average HD95 relative to the unmodified backbones.","authors":["Milad Rostamian","Mohammadreza Mohammadi","Ender Konukoglu","Mohsen Soryani"],"published":"2026-10-13T15:39:20Z","updated":"2026-10-13T15:39:20Z","abstract_url":"https://arxiv.org/abs/2610.18571v1","html_url":"https://arxiv.org/html/2610.18571v1","pdf_url":"https://arxiv.org/pdf/2610.18571v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18543v1","title":"Beyond the Encoder: Object-Centric Representations Emerging from Segmentation Foundation Models","abstract":"Foundation models are increasingly used as feature extractors for downstream tasks with limited data, typically through representations obtained from their encoders. However, foundation models trained for structured tasks such as segmentation also form object-specific representations during task execution, whose transferability remains largely unexplored. We investigate Segment Anything Model 2 (SAM2) object pointers, compact object-level representations produced through the segmentation pathway, as transferable representations for downstream tumour prediction. Through experiments on two PET/CT tumour prediction tasks, we find that object pointers learned using segmentation supervision alone already encode tumour-discriminative information, despite never being optimised for the downstream labels. We further introduce task-guided object pointers, where an auxiliary objective jointly shapes the object pointer space for the downstream prediction together with segmentation. Task-guided pointers improve cancer-type classification, outperforming conventional encoder-based transfer and radiomics, while segmentation-only pointers perform best on the more challenging recurrence prediction task. Representation analyses reveal associations between object pointers and interpretable radiomics features, class-dependent organisation of the learned representation space, and explicit spatial grounding around the segmented tumour. Together, these findings suggest that useful transferable representations can emerge through the execution of a foundation model's primary task, providing an alternative to conventional encoder-based transfer.","authors":["Michalis Pistos","Bartłomiej W. Papież"],"published":"2026-10-13T15:22:00Z","updated":"2026-10-13T15:22:00Z","abstract_url":"https://arxiv.org/abs/2610.18543v1","html_url":"https://arxiv.org/html/2610.18543v1","pdf_url":"https://arxiv.org/pdf/2610.18543v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18535v1","title":"Meta-Video: Efficient Standardized Evaluation for Video Understanding","abstract":"Video understanding benchmarks are the primary yardstick for measuring progress in video-language modeling, and a growing body of work relies on them to claim improvements. The reported benchmark scores in these works, however, are almost always produced by frameworks (e.g., lmms eval) used as black boxes: certain evaluation choices like frame sampling, preprocessing, and input formatting are inherited from preset defaults and seldom inspected carefully. We show these unexamined choices are a major source of variance. Even for the same model checkpoint, evaluation configuration alone can shift accuracy by up to 19.5pp. Hence, it is unclear whether reported gains reflect genuine improvements in capability or differences in evaluation setup. Moreover, many benchmark samples offer little evidence of visual capability, since they can be answered without the video, and the full suites are expensive to evaluate. We address these issues in two parts. First, we curate existing suites for discriminability and efficiency, producing Meta-Video, a balanced 1,000-question benchmark over 791 videos spanning diverse tasks and durations, which largely preserves model rankings, at 5 times inference speedup for a full-frame count sweep experiment (4-128 frames). Second, we establish a standardized evaluation protocol by sweeping the configuration space to isolate choices that measurably affect results, distill them into best practices and reporting standards, and release reproducible reference scores across five models and seven benchmarks. We hope that the proposed evaluation framework and the Meta-Video benchmark will support video understanding research by providing a reproducible and efficient foundation to measure progress in a reliable way.","authors":["Soumya Shamarao Jahagirdar","Anna Kukleva","Vishaal Udandarao","Samuel Thomas","Brian Kingsbury","Rogerio Feris","James R. Glass. Ameya Prabhu","Hilde Kuehne"],"published":"2026-10-13T15:18:12Z","updated":"2026-10-13T15:18:12Z","abstract_url":"https://arxiv.org/abs/2610.18535v1","html_url":"https://arxiv.org/html/2610.18535v1","pdf_url":"https://arxiv.org/pdf/2610.18535v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18499v1","title":"EgoOmniWorld: Unifying Egocentric Understanding via Ego-Action-World Interactions","abstract":"Egocentric video understanding spans diverse capabilities, modalities, and evaluation formats, yet these are often studied in isolation despite their tight coupling in real-world interaction. We propose the Ego-Action-World interaction loop as a unifying principle: the wearer perceives the world, forms goals, acts, changes the world, and uses feedback to guide subsequent behavior. Based on this view, we introduce EgoOmniWorld, a benchmark organized around four complementary interaction structures: Node captures ego, action, and world states; Edge captures directed relations among them; Chain captures linked dependencies; and Loop captures feedback-closed interactions. We develop an interaction-first, evidence-grounded data pipeline that extracts structured interactions from egocentric videos, grounds them in visual and auditory evidence, and generates questions according to their interaction structure. Required modalities and single- or multi-turn formats follow naturally from the supporting evidence and dependencies. EgoOmniWorld contains 24,166 QA groups, including 20,284 training and 3,882 test samples. Experiments on representative open- and closed-source multimodal large language models reveal substantial and uneven limitations across interaction structures. Models trained on EgoOmniWorld improve in-domain interaction understanding and generalize to existing egocentric benchmarks. EgoOmniWorld provides a unified foundation for evaluating and advancing egocentric video understanding. Data, code, and models will be released.","authors":["Songruo Chen","Yuqian Fu","Yu Li","Mingkang Dong","Sifan Zhou","Bin Ren","Xu Zheng","Tianwen Qian","Mohamed Elhoseiny","Yanwei Fu"],"published":"2026-10-13T14:53:16Z","updated":"2026-10-13T14:53:16Z","abstract_url":"https://arxiv.org/abs/2610.18499v1","html_url":"https://arxiv.org/html/2610.18499v1","pdf_url":"https://arxiv.org/pdf/2610.18499v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18485v1","title":"Physics-Aware Deepfake Detection via Distance-Speech Consistency","abstract":"Recent progress in generative models has made talking-head deepfakes highly realistic and easy to create, jeopardizing public trust. However, most audio-visual deepfake detectors rely on lip-speech synchronization and are designed for static, frontal videos, limiting their reliability in dynamic, in-the-wild recordings where the speaker moves and lip cues are degraded or missing. As an alternative, we propose a physics-aware detector for dynamic speaking videos that leverages an acoustic constraint: in real recordings, speech energy varies predictably with speaker-to-camera distance, whereas deepfake generation can break this coupling. Our method combines distance estimates from video with distance-dependent acoustic measures from speech to detect deepfakes. Experiments on in-the-wild benchmarks show that the proposed physical cue is effective in dynamic scenarios, and that it complements lip-sync-based detectors, with a simple ensemble achieving consistent gains across datasets. Codes are available at https://byulharang.github.io/PADD/.","authors":["Kyeongrae Kim","Kim Sung-Bin","Oh Hyun-Bin","Tae-Hyun Oh"],"published":"2026-10-13T14:44:28Z","updated":"2026-10-13T14:44:28Z","abstract_url":"https://arxiv.org/abs/2610.18485v1","html_url":"https://arxiv.org/html/2610.18485v1","pdf_url":"https://arxiv.org/pdf/2610.18485v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18472v1","title":"Simplifying and Improving On-Policy Distillation for Few-Step Diffusion","abstract":"Few-step distillation reduces the sampling cost of diffusion and flow models, but existing approaches often require auxiliary score models or specialized architectures. We show that simple on-policy velocity regression already provides a strong foundation for 4-NFE generation. To represent teacher velocity variation within each coarse transition, we introduce Pivot, a training-only residual proxy that separates local corrections from the student's interval-mean prediction. We further repel the student from weaker teacher predictions, providing a lightweight mechanism for avoiding undesirable modes. The resulting framework, Simplified Matching Distillation (SMD), remains entirely regression-based, requires neither online score estimation nor adversarial training, and leaves the deployed generator unchanged. We evaluate SMD on image generation and editing, 3D generation, video synthesis, and joint audio--video generation, scaling to 33 billion parameters. At 4-NFE, SMD outperforms strong few-step baselines and surpasses multi-step teachers on several benchmarks. It also supports cross-model, multi-teacher, and causal-video distillation.","authors":["Jiawei Zhang","Ziyu Wan","Nanye Ma","Long Zhao","Dong Chen","Hongyu Liu","Qifeng Chen","Dongdong Chen"],"published":"2026-10-13T14:35:46Z","updated":"2026-10-13T14:35:46Z","abstract_url":"https://arxiv.org/abs/2610.18472v1","html_url":"https://arxiv.org/html/2610.18472v1","pdf_url":"https://arxiv.org/pdf/2610.18472v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18461v1","title":"MFVSR: A Multi-Style and Fine-Grained Benchmark for Video Subtitle Removal","abstract":"Video subtitle removal (VSR) is an important video restoration task, yet existing evaluation remains limited by low-resolution datasets, fragmented test sets, and generic video-inpainting protocols that fail to adequately capture localized restoration errors, unintended modifications, temporal instability, and incomplete outputs. In this paper, we introduce MFVSR, a large-scale multi-style benchmark for fine-grained and reliability-aware video subtitle removal evaluation. MFVSR distinguishes itself through three key features: (1) Large-scale and diverse data, comprising 3,000 paired videos from Real-HQ, Real-LQ, and AI-Generated sources, with an auxiliary set of 953 in-the-wild real videos for real-world coverage analysis; (2) Controlled subtitle diversity, spanning 16 languages and four factors covering spatial layout, temporal behavior, visual style, and language mode; (3) Fine-grained evaluation, introducing an information-conditioned, spatially decoupled protocol that separates blind from mask-guided removal and measures Restoration Fidelity, Preservation Fidelity, Temporal Fidelity, coverage, and failures. Experiments on six representative methods reveal substantial discrepancies between local restoration, outside-region preservation, temporal consistency, and full-set reliability that are obscured by conventional full-frame metrics. MFVSR therefore provides a more comprehensive and diagnostic foundation for evaluating and advancing video subtitle removal methods.","authors":["Xiyan Huang","Qingdong He","Peng Tang","Bo Yin","Chaoyi Wang","Xiaobin Hu"],"published":"2026-10-13T14:27:22Z","updated":"2026-10-13T14:27:22Z","abstract_url":"https://arxiv.org/abs/2610.18461v1","html_url":"https://arxiv.org/html/2610.18461v1","pdf_url":"https://arxiv.org/pdf/2610.18461v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18458v1","title":"$\\mathrm{S}^3$-PnP: Plug-and-Play Denoising for Scientific Imaging with Self-Supervised Score Priors","abstract":"Modern image restoration methods increasingly rely on large-scale supervised training, yet clean targets are often prohibitively difficult to obtain in scientific imaging modalities such as hyperspectral imaging (HSI) and magnetic resonance imaging (MRI). Plug-and-play ADMM (PnP-ADMM) with pretrained diffusion priors offers a promising alternative, but the learned prior distribution can mismatch both the target scientific image distribution and the distribution of ADMM denoiser inputs induced by dual feedback. To mitigate these mismatches, we propose $\\mathrm{S}^3$-PnP, a self-supervised plug-and-play restoration framework that learns a score prior directly from observation-derived ADMM intermediate states, without clean training targets or externally pretrained weights. Specifically, the learned score corrects the input to the analytical prior update, combining observation-driven corrections with analytical regularization. We further analyze the convergence and reconstruction error of the corrected ADMM algorithm assuming an ideal score and quadratic data fidelity. Experiments on reference-guided HSI restoration, single-image HSI denoising, and MRI denoising demonstrate consistent improvements over competing methods.","authors":["Yukun Cui","Jiangshe Zhang","Shuang Xu","Lilun Deng","Haowen Bai","Tao Feng","Haotong Qin","Konrad Schindler","Zixiang Zhao"],"published":"2026-10-13T14:26:37Z","updated":"2026-10-13T14:26:37Z","abstract_url":"https://arxiv.org/abs/2610.18458v1","html_url":"https://arxiv.org/html/2610.18458v1","pdf_url":"https://arxiv.org/pdf/2610.18458v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18455v1","title":"EmoGenie: Benchmarking and Evaluating Expressed and Evoked Emotion in T2I Generation with MLLMs","abstract":"Rapid advances in artificial intelligence-generated content (AIGC) have significantly promoted using text-to-image (T2I) models to generate images with specific affective intentions. However, the emotional effects conveyed by generated images frequently deviate from target expectations, and it remains unclear whether multimodal large language models (MLLMs) can reliably interpret the emotion of AI-generated visual content. Existing affective benchmarks are predominantly built on natural images, while affective studies of generated images have largely focused on emotions expressed in portraits, lacking a unified benchmark for studying the emotions expressed and evoked by generated images. We therefore introduce EmoGenie, a benchmark of emotion for AI-generated images that evaluates capabilities in T2I generation and MLLM understanding across expressed and evoked emotions. It comprises 6,400 images generated by eight T2I models using 800 emotion-targeted prompts, annotated with question-answer (QA) pairs, termed EmoGenie-QA, and continuous human ratings, termed EmoGenie-Assess. EmoGenie-QA contains 90,000 closed-set questions in single-image and image-pair settings, as well as 1,057 open-ended questions for emotion description. EmoGenie-Assess benchmarks continuous affective and aesthetic prediction using 13,175 mean opinion scores (MOSs) aggregated from human ratings in terms of valence, arousal, dominance, and aesthetic quality. We further develop EmoProbe, which combines emotion question answering with response-aligned, dimension-specific regression heads for continuous score prediction. Experimental results show that EmoProbe achieves superior results on emotion-related QA tasks, while its affective and aesthetic predictions correlate better with human ratings, demonstrating its state-of-the-art capabilities of unified coarse-to-fine affective understanding for AI-generated images.","authors":["Zixuan Xing","Lancheng Gao","Shengyan Li","Huiyu Duan","Zhaolin Cai","Guangtao Zhai","Xiongkuo Min"],"published":"2026-10-13T14:23:07Z","updated":"2026-10-13T14:23:07Z","abstract_url":"https://arxiv.org/abs/2610.18455v1","html_url":"https://arxiv.org/html/2610.18455v1","pdf_url":"https://arxiv.org/pdf/2610.18455v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18447v1","title":"Thinker-WM: A Unified World Model with Shared Multimodal Representations for Embodied Intelligence","abstract":"World models have emerged as a promising paradigm for embodied AI, yet existing systems often remain fragmented in the modalities they model and the functions they support. In particular, visual dynamics, geometric structure, and executable action are commonly coupled through separate interfaces or downstream modules rather than being jointly represented and evolved within a shared dynamics model. In this work, we present Thinker-WM, a unified multimodal world model that jointly models and generates RGB, metric depth, and robot action through a shared intermediate Unified Dynamics Transformer with modality-specific encoders and decoders. The model performs multimodal unification at the representation level: appearance, geometry, and action are transformed into a common dynamic representation and jointly evolved by shared parameters, while their distinct output structures are preserved. The same parameterization supports multiple functions, including joint video-action generation, world prediction, policy inference, action-conditioned generation, video-to-action generation, and inverse dynamics. To examine whether the shared representation captures action-related information, we introduce a lightweight motion probe that shows the frozen visual representation contains recoverable motion information. Thinker-WM is trained on a heterogeneous corpus comprising approximately 20K hours of egocentric video, 10K hours of real-robot data, and 1K hours of simulation data, including approximately 4K hours of real-robot data with aligned depth supervision. Extensive experiments demonstrate strong performance across embodied world-model evaluations. Thinker-WM ranks first on EWMBench, WorldOlympiad and WorldArena, while controlled studies further demonstrate the benefits of action conditioning, geometric interaction, and multi-function training within the shared representation.","authors":["Thinker Team","Peng Gao","Jichao Jiao","Chen Liao","Daqin Luo","Yiming Ma","Baiyu Pan","Hailin Shi","Jiyuan Wang","Xiangming Xu","Xiongwei Zhao"],"published":"2026-10-13T14:18:47Z","updated":"2026-10-13T14:18:47Z","abstract_url":"https://arxiv.org/abs/2610.18447v1","html_url":"https://arxiv.org/html/2610.18447v1","pdf_url":"https://arxiv.org/pdf/2610.18447v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18446v1","title":"CoTL: Compact Token Learning for 3D Scene Representation","abstract":"We present CoTL, a framework that learns a compact set of tokens that preserves scene geometry and appearance from unposed multi-view images. Our encoder compresses the input images into small per-view sets of latent tokens that aggregate information across views to form a view-consistent scene representation. Each additional view expands the representation with only a small, resolution-independent set of tokens, allowing its capacity to grow with the available observations. To force this compact bottleneck to retain sufficient scene information, a query-based Gaussian decoder uses scene-independent queries to attend to the learned tokens and recover an explicit, renderable set of 3D Gaussian primitives. Novel-view rendering supervision trains the compact representation end to end through the reconstructed Gaussian scene. Experiments on \\retenk{} and ACID show that the resulting compact, unstructured token set supports competitive novel-view synthesis and can serve as the latent space of a generative model for 3D Gaussian scene generation. Together, these results show that 3D Gaussian reconstruction is an effective objective for compact scene representation learning and the learned token space provides a basis for broader downstream tasks in 3D vision.","authors":["Han Liang","Sibo Wu","Anpei Chen","Rüdiger Westermann"],"published":"2026-10-13T14:17:30Z","updated":"2026-10-13T14:17:30Z","abstract_url":"https://arxiv.org/abs/2610.18446v1","html_url":"https://arxiv.org/html/2610.18446v1","pdf_url":"https://arxiv.org/pdf/2610.18446v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18417v1","title":"Resource-Efficient 3D Shape and Orientation Estimation of Road Users using Roadside RGB Camera and 3D Radar","abstract":"End-to-end deep learning pipelines for camera-radar 3D object detection are well established in driver assistance systems and autonomous vehicles; however, adapting them to roadside-mounted infrastructure presents significant challenges. On vehicles, sensor heights, pitch angles, and relative geometries remain largely uniform, allowing end-to-end models to generalize effectively. On the contrary, roadside sensor installations vary drastically in height, tilt, and field of view across locations, rendering end-to-end models prone to failure and difficult to adapt without massive location-specific datasets. Hence, instead of designing a complex end-to-end pipeline for direct 3D bounding box estimation, a low-cost, resource-efficient two-stage approach is proposed for real-time 3D shape and orientation estimation. The first stage utilizes any off-the-shelf, state-of-the-art method to extract 2D camera bounding boxes and associated 3D radar points for each road user. The proposed second stage then processes these inputs to construct 3D oriented bounding boxes where radar data determines 3D position, predefined templates define size for each road user, and a tiny neural network predicts a site-specific and optimized yaw angle. The algorithm is successfully validated at a curved road with a junction for pedestrians, bicycles, and cars, where it achieves 25 frames per second on an NVIDIA Jetson ORIN for real-time applications.","authors":["Shiva Agrawal","Savankumar Bhanderi","Gordon Elger"],"published":"2026-10-13T13:58:01Z","updated":"2026-10-13T13:58:01Z","abstract_url":"https://arxiv.org/abs/2610.18417v1","html_url":"https://arxiv.org/html/2610.18417v1","pdf_url":"https://arxiv.org/pdf/2610.18417v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18399v1","title":"Bifocal: Training-Free Mixed Granularity Visual Token Pruning for Multimodal LLMs","abstract":"Visual token pruning for multimodal large language models (MLLMs) appears highly effective, with existing methods retaining over 95% of unpruned performance on common VQA benchmarks using a quarter of the visual tokens or fewer. However, our extensive evaluation of ten methods across three MLLM families and five ability groups reveals a critical gap: strong general performance often comes at the cost of severe degradation on fine-grained tasks such as OCR and visual grounding. We trace these failures to two limitations of the prevailing paradigm of retaining the highest-ranked native patches. A single importance ranking overlooks the complementary evidence required by different tasks, while sparse patch selection disrupts both image content and spatial integrity. To address these limitations, we propose Bifocal, a training-free, two-stage pruning method built on a mixed-granularity framework. It allocates separate budgets to query-focused and image-intrinsic evidence, complemented by a pooled coarse representation of the entire image. Before the LLM, Bifocal matches question words to visual regions through a soft conjunction balanced against norm-debiased image saliency, while selecting image-intrinsic evidence to maximize representational coverage. Inside the LLM, it further prunes tokens using density-adjusted text-to-image attention. With roughly a quarter of the original visual tokens, Bifocal is the only evaluated method to retain over 90% of unpruned performance in every ability group across all three models, and ranks first on average in all nine model-budget settings. The code is available at: https://github.com/EIT-NLP/Bifocal","authors":["Peiran Yin","Hao Wu","Zihao Yang","Fengyu Zhou","Yijuan Liang","Haozhe Hu","Xudong Wang","Wei Zhang","Xiaoyu Shen"],"published":"2026-10-13T13:46:32Z","updated":"2026-10-13T13:46:32Z","abstract_url":"https://arxiv.org/abs/2610.18399v1","html_url":"https://arxiv.org/html/2610.18399v1","pdf_url":"https://arxiv.org/pdf/2610.18399v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18388v1","title":"ReDiS: Reasoning-Diagnosis Self-Evolution for Multimodal Reasoning in Remote Sensing","abstract":"Multimodal large language models (MLLMs) have shown strong potential for remote sensing understanding, yet reliable reasoning remains challenging when tasks require fine-grained visual grounding and multi-step inference. Existing approaches typically rely on either costly pre-constructed reasoning trajectories or self-generated signals such as response consistency, which can reinforce shared errors and provide unreliable supervision. We introduce \\textbf{Reasoning--Diagnosis Self-Evolution (ReDiS)}, a framework that separates reasoning exploration from candidate evaluation while allowing the two processes to evolve jointly. ReDiS instantiates two role-specific experts from a shared multimodal backbone: a \\textbf{Reasoner} that explores diverse visual evidence--answer candidates and a \\textbf{Diagnoser} that jointly evaluates the complete candidate set and provides credibility-aware feedback. As the Reasoner evolves, it exposes new candidate distributions and failure modes; the Diagnoser adapts to these changes and, in turn, reshapes the learning signal for subsequent exploration. To handle groups in which all sampled answers are incorrect and group-relative advantages vanish, we further introduce \\textbf{Failure-Triggered Recovery (FTR)}, which provides minimal outcome-level correction without prescribing intermediate reasoning trajectories. Experiments on LHRS-Bench, MME-RS, and CHOICE show consistent improvements over Qwen3.5 backbones at 0.8B, 2B, and 4B scales. ReDiS improves category-averaged accuracy by 6.47 percentage points at 0.8B, while ReDiS-4B achieves the highest average performance among the compared remote sensing MLLMs.","authors":["Yi Liu","Wentao Jiang","Shuo Ni","Zhiming Luo","Di Wang","Zengmao Wang","Jing Zhang","Bo Du"],"published":"2026-10-13T13:38:02Z","updated":"2026-10-13T13:38:02Z","abstract_url":"https://arxiv.org/abs/2610.18388v1","html_url":"https://arxiv.org/html/2610.18388v1","pdf_url":"https://arxiv.org/pdf/2610.18388v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18374v1","title":"SchemaPose: RGB-Based Category-Level Pose Estimation with Parametric Category Schema","abstract":"RGB-based category-level 9D pose estimation remains highly challenging because a monocular system must generalize across unseen object instances while jointly inferring 3D translation, 3D rotation, and 3D size. Unlike instance-level pose estimation, the category-level setting requires the network to learn both what is shared across objects within a category and how individual instances vary in structure. This challenge is amplified in the RGB-only setting, where pose cues, category-level commonality, and instance-specific variation are entangled in appearance without direct geometric constraints, making it difficult for existing frameworks to learn a representation that is truly aligned with the category-level estimation objective. To address this problem, we propose SchemaPose, a schema-guided framework for RGB-based category-level pose estimation. SchemaPose equips the estimation pipeline with an explicit parametric schema for modeling category-level regularities together with structured instance variation, and uses the inferred schema variables to guide pose-related prediction in an end-to-end query-based framework. The same formulation also supports template instantiation, synthetic annotation, and pose learning within a unified framework. Experiments on synthetic and real data show that SchemaPose achieves state-of-the-art performance among RGB-based methods for category-level 9D pose estimation.","authors":["Shuang Wu","Jiude Wei","Cewu Lu","Jianhua Sun"],"published":"2026-10-13T13:29:04Z","updated":"2026-10-13T13:29:04Z","abstract_url":"https://arxiv.org/abs/2610.18374v1","html_url":"https://arxiv.org/html/2610.18374v1","pdf_url":"https://arxiv.org/pdf/2610.18374v1.pdf","matched_keywords":["3d","representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18369v1","title":"Hallucination-aware Faithful Reasoning in Remote Sensing","abstract":"Multimodal large language models (MLLMs) have demonstrated promising capabilities for remote sensing reasoning, yet they frequently generate visually unsupported reasoning that contradicts the visual evidence. Existing post-training methods optimize primarily for final-answer correctness, providing limited supervision for identifying and correcting hallucinations that arise during the reasoning process. To address this limitation, we propose \\textbf{FaithRS}, a hallucination-aware self-reflection framework for faithful reasoning in remote sensing. We first construct \\textbf{SFHD-43K}, a dataset of 43K structured, fine-grained hallucination annotations, and train a detector to identify hallucination types, underlying causes, and supporting visual evidence. FaithRS then incorporates this diagnostic feedback into a Safe Detector-Guided Corrective Rollout framework, where a safety-aware gate selectively determines whether and how to revise the response. Training is driven by a composite reward that jointly optimizes answer accuracy, reasoning faithfulness, hallucination reduction, format compliance, and revision safety. Experiments with Qwen3.5 backbones (0.8B, 4B, and 9B) show consistent improvements across four remote sensing benchmarks, with gains of up to 11.64 points.","authors":["Yi Liu","Jing Zhang","Xiang Feng","Xiaoyu Tian","Haonan Guo","Di Wang","Zengmao Wang","Bo Du"],"published":"2026-10-13T13:28:00Z","updated":"2026-10-13T13:28:00Z","abstract_url":"https://arxiv.org/abs/2610.18369v1","html_url":"https://arxiv.org/html/2610.18369v1","pdf_url":"https://arxiv.org/pdf/2610.18369v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18363v1","title":"Visual Sevoing from Lines","abstract":"In this work, we present a fundamentally new approach to visual servoing using lines. It is based on a theoretical and geometrical study of the main line representations which allowed us to define a new representation, the so-called binormalized Plucker coordinates. They are particularly well suited to visual servoing. Indeed, they allow the definition of a proper image line alignment concept. The control law which realizes such an alignment has moreover several properties: partial decoupling between rotation and translation, analytical inversion of the motion equations and global asymptotic stability conditions. This control law was validated both in simulation and experimentally in the specific case of an orthogonal trihedron.","authors":["Nicolas Andreff","Bernard Espiau","Radu Horaud"],"published":"2026-10-13T13:25:30Z","updated":"2026-10-13T13:25:30Z","abstract_url":"https://arxiv.org/abs/2610.18363v1","html_url":"https://arxiv.org/html/2610.18363v1","pdf_url":"https://arxiv.org/pdf/2610.18363v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18356v1","title":"Urbex: Agentic Spatial Grounding for City-Scale 3D Scenes","abstract":"City-scale 3D grounding is commonly formulated as candidate ranking, which requires precomputed instance proposals and becomes inefficient in large outdoor scenes. We propose Urbex, an agentic vision-language framework that instead casts grounding as active spatial search. Urbex represents a city-scale 3D scene as an interactive multi-view environment, allowing a VLM agent to query landmarks, zoom into local regions, render oblique views, and commit a grounded bounding box. We optimize this tool-use policy with reinforcement learning on CityRefer, using smooth localization rewards and lightweight shaping rewards for efficient exploration. Experiments show that Urbex achieves the best Hit@1 and IoU on CityRefer, supports candidate-free grounding without ground-truth boxes, and is substantially faster than the strongest city-scale ranking baseline. Zero-shot results on STPLS3D-Refer further indicate improved cross-scene robustness.","authors":["Yu Wang","Rui Dai","Wei Chen","Yi Wang","Bo Dang","Kaikui Liu","Xiangxiang Chu","Yansheng Li"],"published":"2026-10-13T13:23:24Z","updated":"2026-10-13T13:23:24Z","abstract_url":"https://arxiv.org/abs/2610.18356v1","html_url":"https://arxiv.org/html/2610.18356v1","pdf_url":"https://arxiv.org/pdf/2610.18356v1.pdf","matched_keywords":["3d","agent","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18342v1","title":"CityCode: Building Agent-Operable 3D Cities from Sparse Aerial Observations","abstract":"Urban spatial intelligence calls for 3D cities that agents can measure, interpret, and modify across successive tasks. Maintaining such cities as persistent, code-based states requires lightweight acquisition and support for consistent state updates without repeated dense reconstruction. We therefore formulate a new setting for grounded urban world construction: generating large-scale, instance-level parameterized 3D cities from one low-altitude aerial RGB image per region and known camera parameters, while recovering metrically scaled buildings and explicit road geometry and connectivity. We introduce CityCode, an agent-operable representation that unifies metric geometry, urban topology, visual semantics, and 3D assets through persistent entity identities, with dependency-aware versioned execution for validated updates and historical restoration. We further develop Air2Code to construct this representation by combining visual structure extraction with adapted metric depth estimation. To address occlusion and incomplete coverage, recovered structure and observed appearance guide generative completion and subsequent structure-aware 3D generation for buildings and backgrounds. Experiments on CitySample-Aerial and UrbanScene3D demonstrate substantially more accurate metric structure recovery and superior visual fidelity to the target cities compared with the evaluated baselines. Across 50 task chains of 50 steps each, CityCode supports continued querying, editing, planning, and historical restoration over evolving city states. Together, CityCode and Air2Code turn sparse aerial observations into persistent, agent-operable urban worlds for long-horizon urban spatial intelligence.","authors":["Jiahui Sun","Ran Bi","Yifei Liu","Xiaolong Zhou","Yishuo Xu","Yuanqi Li","Congcong Zhu","Lei Yang","Yanwen Guo","Zhihang Zhong","Hongjie Zhang"],"published":"2026-10-13T13:14:17Z","updated":"2026-10-13T13:14:17Z","abstract_url":"https://arxiv.org/abs/2610.18342v1","html_url":"https://arxiv.org/html/2610.18342v1","pdf_url":"https://arxiv.org/pdf/2610.18342v1.pdf","matched_keywords":["3d","agent","representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18325v1","title":"ShoeFit: A New Dataset and Dual-image-stream DiT Framework for Virtual Footwear Try-On","abstract":"Virtual footwear try-on (VFTON), a critical yet underexplored area in virtual try-on (VTON), aims to synthesize faithful try-on results given diverse footwear and model images while maintaining 3D consistency and texture authenticity. Unlike conventional garment-focused VTON methods, VFTON presents unique challenges due to (1) Data Scarcity, which arises from the difficulty of perfectly matching product shoes with models wearing the identical ones, (2) Viewpoint Misalignment, where the target foot pose and source shoe views are always misaligned, leading to incomplete texture information and detail distortion, and (3) Background-induced Color Distortion, where complex material of footwear interacts with environmental lighting, causing unintended color contamination. To address these challenges, we introduce MVShoes, a multi-view shoe try-on dataset consisting of 7305 well-annotated image triplets, covering diverse footwear categories and challenging try-on scenarios. Furthermore, we propose a dual-stream DiT architecture, ShoeFit, designed to mitigate viewpoint misalignment through Multi-View Conditioning with 3D Rotary Position Embedding, and alleviate background-induced distortion using the LayeredRefAttention which leverages background features to modulate footwear latents. The proposed framework effectively decouples shoe appearance from environmental interferences while preserving high-quality texture detail through decoupled denoising and conditioning branches. Extensive quantitative and qualitative experiments demonstrate that our method substantially improves rendering fidelity and robustness under challenging real-world product shoes, establishing a new benchmark in high-fidelity footwear try-on synthesis.","authors":["Yuhan Li","Zhiyu Jin","Yifan Tong","Wenxiang Shang","Benlei Cui","Xuanhong Chen","Hangcheng Zhu","Bingbing Ni"],"published":"2026-10-13T13:03:29Z","updated":"2026-10-13T13:03:29Z","abstract_url":"https://arxiv.org/abs/2610.18325v1","html_url":"https://arxiv.org/html/2610.18325v1","pdf_url":"https://arxiv.org/pdf/2610.18325v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18323v1","title":"Omni-RS: Unifying Multi-Task Understanding and Generation in Remote Sensing","abstract":"Practical remote sensing applications often require both understanding and generation capabilities for the same geographic scene. However, most existing methods address either understanding or generation in isolation, while existing unified remote sensing models' generative ability is limited to text-to-image. To bridge this gap, we propose Omni-RS, a unified framework supporting four remote sensing understanding tasks and five generation tasks. Specifically, we introduce the \"Scene-Guided Two-Stage Training\" strategy, which first adapts a multimodal large language model to remote sensing understanding and then uses its hidden states to guide a diffusion transformer for image generation. To enable joint learning across diverse generation tasks, we construct UniGen, a unified multi-task generation dataset, by organizing heterogeneous remote sensing data into a unified format. Furthermore, we introduce \"Detailed Visual Conditioning\", which uses visual conditions encoded by a VAE to guide the generation process, thereby supporting additional generation tasks that require reference images. Extensive experiments demonstrate that Omni-RS performs exceptionally well in understanding tasks and has achieved outstanding results in a variety of generative tasks.","authors":["Pan Yin. Shuai Yang","Yuanhao Liu","Datao Tang","Jialin Li","Hao Wang","Pei Liu","Kaiyu Li","Cong Zhao","Xiangyong Cao"],"published":"2026-10-13T13:02:27Z","updated":"2026-10-13T13:02:27Z","abstract_url":"https://arxiv.org/abs/2610.18323v1","html_url":"https://arxiv.org/html/2610.18323v1","pdf_url":"https://arxiv.org/pdf/2610.18323v1.pdf","matched_keywords":["multimodal","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18305v1","title":"AffectWorld: Benchmarking Emotion-Driven Future World Prediction","abstract":"The world encompasses both physical environments and human actors. Predicting its evolution requires understanding both physical laws and how emotions shape human actions. However, existing world model benchmarks primarily assess physical plausibility and perceptual quality, leaving emotion-driven world evolution largely untested.We introduce AffectWorld, a benchmark that evaluates the chain Emotion-Action-World State through three tasks: World-State Consistency, Emotion-Action Consistency, and Causal Consistency. It comprises 1,498 everyday video samples annotated with plausible emotions, action tendencies, and atomic world-state constraints. A counterfactual subset of 233 samples tests whether changing an agent's emotion under fixed scene and event conditions yields corresponding changes in actions and consequences. We define eight metrics across the three tasks and an additional counterfactual metric, combining automatic visual assessment with human-calibrated VLM/LLM judgments. Evaluations of five SoTA world models (e.g., Cosmos3) required world-state change scores of 0.100-0.280 and counterfactual emotion sensitivity scores of 0.027-0.070 on a [0, 1] scale. These results reveal substantial gaps in generating the consequences of emotion-driven actions and adapting future predictions to emotional interventions. AffectWorld provides a testbed for advancing world models that capture how emotions shape future physical and social states.","authors":["Changhao Song","Yacong Chen","Hui Gao","Yazhou Zhang","Peng Zhang"],"published":"2026-10-13T12:50:40Z","updated":"2026-10-13T12:50:40Z","abstract_url":"https://arxiv.org/abs/2610.18305v1","html_url":"https://arxiv.org/html/2610.18305v1","pdf_url":"https://arxiv.org/pdf/2610.18305v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18289v1","title":"LongForcing: Scaling Temporal Manifold Matching for Long-Horizon World Rollout","abstract":"Autoregressive video diffusion models have emerged as a foundation for long-horizon world rollout. However, when extended far beyond their training windows, these models suffer from progressive drift: visual quality deteriorates, motion becomes inconsistent, and object identity gradually collapses as generated frames are recursively reused as context. We study a supervision-horizon gap: short-horizon distillation leaves later rollout states without direct supervision. We show that matching short-window marginals need not determine long-horizon behavior, while longer on-policy trajectories expose delayed failures to training. This motivates temporal manifold matching at scale for long-horizon world models. Building on this insight, we introduce LongForcing, a distillation approach that scales teacher supervision to long student self-rollouts. LongForcing preserves the short-horizon teacher-forcing and causal ODE-distillation stages, while replacing the realscore teacher in the final distribution-matching stage with an extended-horizon bidirectional teacher. The long-horizon teacher supervises extended student self-rollouts using the standard distribution-matching formulation, without modifying the student architecture or increasing inference cost. We evaluate LongForcing on text-to-video generation and interactive action-conditioned world models, achieving a VBench Quality score of 85.52 and improving WorldRoamBench 60s action score by 23.9 points in first-person ablations. Qualitative stress tests further sample interactive rollouts up to 24 hours, far beyond the training horizon. These results suggest that scaling supervision along the temporal axis is a practical step toward long-horizon world models. The project website and code are at https://github.com/Fantasy-AMAP/LongForcing.","authors":["Ziyu Zhu","Zhaoxu Sun","Fan Jiang","Mengchao Wang","Junfeng Ni","Ting-Bing Xu","Zhicheng Liu","Mu Xu"],"published":"2026-10-13T12:39:00Z","updated":"2026-10-13T12:39:00Z","abstract_url":"https://arxiv.org/abs/2610.18289v1","html_url":"https://arxiv.org/html/2610.18289v1","pdf_url":"https://arxiv.org/pdf/2610.18289v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18243v1","title":"LiFUSE: Frequency-Spatial Unified Self-Supervised Pretraining for Liver Disease Analysis on Non-contrast CT","abstract":"Given the growing global burden of liver tumors and diffuse liver diseases, non-contrast computed tomography (NCCT) is increasingly used for opportunistic screening because of its low cost and favorable safety profile. However, downstream tasks such as tumor detection and fine-grained disease diagnosis remain challenging due to NCCT's inherently low tissue contrast, lack of hemodynamic enhancement, and complex anatomical background. These limitations make subtle, heterogeneous, and multifocal hepatic lesions difficult to identify. Although large-scale self-supervised pretraining can learn robust representations from unlabeled NCCT scans, conventional voxel-wise reconstruction does not fully exploit the complementary information available in NCCT. Under weak NCCT contrast, low-level intensity patterns become less informative for pathology recognition, limiting the capture of lesion-specific discriminative features. In this paper, we propose the Liver Frequency-Spatial Unified Self-Supervised Pretraining (LiFUSE). The frequency branch applies random band-stop masking and spectrum reconstruction to encourage the model to capture subtle differences between lesions and surrounding tissues, while the spatial branch performs hybrid-granularity masked volumetric reconstruction to accommodate lesions of diverse sizes and morphologies. Finally, a cross-domain consistency scheme couples the spatial and frequency branches, yielding more discriminative representations for hepatic structures and lesions. Extensive experiments on three clinically relevant tasks across internal cohorts and a public target-domain transfer setting show that LiFUSE consistently outperforms strong baselines. These results suggest that unified frequency-spatial learning can improve liver disease analysis on NCCT, highlighting its potential for large-scale screening.","authors":["Hao Zhang","Yi Huang","Wei Liu","Yuan Gao","Zeju Li","Xu Han","Yu Shi","Ling Zhang","Ke Yan"],"published":"2026-10-13T12:08:56Z","updated":"2026-10-13T12:08:56Z","abstract_url":"https://arxiv.org/abs/2610.18243v1","html_url":"https://arxiv.org/html/2610.18243v1","pdf_url":"https://arxiv.org/pdf/2610.18243v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18238v1","title":"Heading Hierarchy Reconstruction for Complex and Long Documents with Level-Wise Multimodal Memory","abstract":"Vision-language models (VLMs) have been widely adopted for document parsing and optical character recognition (OCR), as they can accurately extract page-level elements. However, downstream applications such as retrieval-augmented generation (RAG) also require coherent document-level structure. Although these models indicate heading levels using different numbers of preceding ``\\#'' symbols, page-by-page prediction often lacks document-level consistency. In practice, input-resolution and context-length constraints make it infeasible for a VLM to jointly process all page images in documents containing tens or hundreds of pages. To address this limitation, we propose a VLM-based framework that incrementally reconstructs heading hierarchies with a \\emph{level-wise multimodal memory}. The memory retains a compact subset of all previously processed pages, selected by anchors. Our framework supports flexible anchor selection, and in this work we select the most recent node at each level, allowing the VLM to observe the visual, textual, and layout patterns of headings at every level. For comprehensive evaluation, we also introduce the Complex and Long Document Heading Hierarchy Reconstruction Benchmark (CLDoc-HHRBench), comprising 250 documents and 11,212 pages with expert-verified annotations. Experiments on CLDoc-HHRBench and three existing benchmarks demonstrate the effectiveness of our method.","authors":["Qian Chen","Xianyin Zhang","Lifan Guo","Chi Zhang"],"published":"2026-10-13T12:06:28Z","updated":"2026-10-13T12:06:28Z","abstract_url":"https://arxiv.org/abs/2610.18238v1","html_url":"https://arxiv.org/html/2610.18238v1","pdf_url":"https://arxiv.org/pdf/2610.18238v1.pdf","matched_keywords":["retrieval","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18227v1","title":"A Controlled Evaluation of Curvature Inspired Scalar Feature Scaling for Domain Generalization","abstract":"Domain-specific curvature is an appealing idea for domain generalization (DG), but curvature learning can denote substantially different computations. This paper evaluates one deliberately narrow implementation: the code calls it HyperDG, but it rescales Euclidean encoder features during training by learned positive scalars and uses an ordinary linear classifier on unscaled Euclidean features at inference. It does not implement a Lorentz or Poincaré representation, geodesic prediction, or a Sharpness-Aware Minimization inner loop. We audit the executed objective and evaluate six conditions on PACS, VLCS, Office Home, and TerraIncognita. The completed design contains 384 runs: six conditions, four held-out targets, and four run seeds per dataset. Checkpoints are selected using only the three source-validation environments. Inference first averages paired seed differences within each held-out target; targets, rather than 16 seed-by-target observations, are the per-dataset clusters. The full implementation's equal-dataset macro point estimate is 1.61 percentage points below native DomainBed ERM (95% clustered CI [-3.17, -0.04]). All four dataset point estimates favor ERM, but an exact four-dataset sign-flip test gives p = .125 and Holm-adjusted p = .250; we therefore claim no adjusted evidence of a difference. The cleaner domain-specificity contrast, separate learned source scales without their variance penalty versus one shared learned source scale, is -0.13 pp (95% CI [-0.53, 0.27]). Its 90% CI lies within a revision-stage $\\pm 1$ pp smallest effect of practical interest (TOST p = .003), supporting equivalence only for the source-selected suite macro, not every dataset, target, or final-step endpoint. The study thus supplies a bounded negative result for this scalar training package; it does not test or refute genuine hyperbolic representation learning.","authors":["Sunny Gupta","Amit Sethi"],"published":"2026-10-13T11:56:18Z","updated":"2026-10-13T11:56:18Z","abstract_url":"https://arxiv.org/abs/2610.18227v1","html_url":"https://arxiv.org/html/2610.18227v1","pdf_url":"https://arxiv.org/pdf/2610.18227v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18209v1","title":"Closing the Estimation Gap: Training-Free Transductive Inference for Cross-Domain Few-Shot Action Recognition","abstract":"Cross-domain few-shot action recognition (CD-FSAR) aims to recognise unseen action classes in a target domain from a handful of labelled videos. Despite advances in representation learning, CD-FSAR inference still relies on prototypes estimated from extremely limited support examples. To assess this bottleneck, we perform an oracle analysis with the representation fixed. Constructing oracle prototypes and decision boundaries from ground-truth query labels improves 5-way 1-shot accuracy by 7--20 percentage points across five target datasets. This reveals a substantial estimation gap: the representation contains useful discriminative information, but prototypes and boundaries estimated from scarce supports fail to capture each episode's true class structure. Motivated by this, we propose TRACE, a training-free transductive inference framework that improves episode-level estimation without modifying the backbone. TRACE comprises two complementary stages. Confidence-Thresholded Transductive Prototype Refinement (CTPR) refines support-based prototypes using confidently predicted queries. The refined prototypes initialise a lightweight per-episode classifier, which Transductive Classifier Refinement (TCR) further adapts by encouraging confident, class-balanced predictions over all queries. Together, the two stages improve prototype and boundary estimation, enabling better use of information in the unlabelled queries. Across five target datasets (HMDB51, UCF101, SSv2, Diving48, and RareAct) in both 1-shot and 5-shot settings, TRACE consistently improves a strong CD-FSAR baseline, including gains of more than six percentage points on HMDB51 1-shot, while recovering much of the oracle-estimated gap. These results suggest that improving test-time estimation is a powerful, broadly applicable complement to representation learning for CD-FSAR under extreme support scarcity.","authors":["Changyi Li","Zeyu Yang","Yu Xiao"],"published":"2026-10-13T11:42:31Z","updated":"2026-10-13T11:42:31Z","abstract_url":"https://arxiv.org/abs/2610.18209v1","html_url":"https://arxiv.org/html/2610.18209v1","pdf_url":"https://arxiv.org/pdf/2610.18209v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18189v1","title":"VARI: Robust Text-to-Video Generation via Group-Structured Intent Alignment","abstract":"Modern text-to-video (T2V) models generate visually compelling videos, yet meaning-preserving changes in prompt wording can substantially alter semantic realization and overall quality. Existing prompt rewriting modifies the inference input, whereas conventional post-training constructs supervision from one prompt formulation at a time; neither explicitly optimizes reliability across equivalent forms. We introduce VARI (Verified Alignment over Representations of Intent), a group-structured framework that treats automatically verified formulations of the same visual intent as a shared supervision unit. VARI builds matched form-seed rollout pools, cross-scores each video against all forms, and applies a wording-independent structured intent audit to identify valid realizations and hard semantic failures. Group-Consistent Distillation (GCD) aligns every verified form with interchangeable valid realizations, while Form-Contrastive Flow-DPO (FC-DPO) learns group-level preferences from audited positive-negative pairs, prioritizing same-seed, different-form contrasts. On HunyuanVideo-1.5, VARI attains the highest T2V-CompBench, VBench, and StoryEval scores among the evaluated methods. On prompt-form extensions of T2V-CompBench and VBench, it improves weakest-form alignment over the strongest prompt-level baselines by 2.45 and 3.55 points and reduces cross-form drop by 30.5% and 32.2%, respectively, while preserving visual quality. Human evaluation, natural-caption controls, prompt-enhancement experiments, diversity analyses, and transfer to LTX-2.3 further support the robustness and transferability of these gains, while VARI requires no additional inference-time module.","authors":["Mingxuan Zhu","Hohei Chan","Shiyuan Liu","Yuanxing Zhang","Lu Chen"],"published":"2026-10-13T11:28:50Z","updated":"2026-10-13T11:28:50Z","abstract_url":"https://arxiv.org/abs/2610.18189v1","html_url":"https://arxiv.org/html/2610.18189v1","pdf_url":"https://arxiv.org/pdf/2610.18189v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18161v1","title":"Benchmarking Multimodal Large Language Models for Zero-Shot Human-Object Interaction","abstract":"Multimodal Large Language Models (MLLMs) have demonstrated strong zero-shot reasoning across diverse domains, but their potential for Human-Object Interaction (HOI) remains unexplored. Unlike traditional HOI approaches that rely on extensive labeled datasets and fixed interaction taxonomies, MLLMs offer flexible reasoning, making them well-suited for dynamic, real-world scenarios. In this work, we present the first systematic study of MLLMs for HOI recognition and detection within a pipeline that combines an external object detector for entity localization with zero-shot multimodal reasoning for interaction understanding. We introduce a benchmark framework for principled zero-shot evaluation, consisting of (i) a unified taxonomy of zero-shot prompting strategies, and (ii) a methodology that transforms token-level logits into interaction scores, enabling fair comparison with specialized HOI models under standard metrics. To support prompt-based evaluation, we additionally construct new question-answer annotations for standard HOI datasets, transforming them into a format suitable for MLLMs. Building on this, we propose two visual prompting strategies, namely Objects as Context and Black Other Objects, that guide MLLMs to target objects while preserving scene context. Experiments on HICO, HICO-DET, and V-COCO demonstrate state-of-the-art zero-shot performance, achieving 53.50 mAP on HICO and 23.69 mAP on HICO-DET. Overall, our work provides a principled benchmarking framework for MLLMs in HOI, opening the door to new models and datasets and enabling flexible open-world interaction understanding.","authors":["Oriol Rabasseda","Zenjie Li","Kamal Nasrollahi","Sergio Escalera"],"published":"2026-10-13T11:05:05Z","updated":"2026-10-13T11:05:05Z","abstract_url":"https://arxiv.org/abs/2610.18161v1","html_url":"https://arxiv.org/html/2610.18161v1","pdf_url":"https://arxiv.org/pdf/2610.18161v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18142v1","title":"FlowCred: Hierarchical Credit Assignment and Functional Coordination for Joint Text-to-Video Post-Training","abstract":"Prompt optimization and generator post-training are two complementary ways to improve text-to-video (T2V) generation, and recent systems increasingly train both modules jointly. However, optimizing a prompt policy and a video generator from the same terminal reward creates two ambiguities: prompt quality is confounded with stochastic generation, and the two modules may realize overlapping local improvements. We introduce FlowCred, a two-level framework for joint T2V post-training. First, hierarchical credit assignment uses matched prompt-seed rollout grids to separate prompt-level credit from prompt-conditioned generator residuals under shared randomness. Second, functional coordination probes alternative current-policy prompts at states from actual generation trajectories, providing generator-aware evidence for prompt optimization while selectively attenuating generator updates already supported by conditioning changes. Across multiple T2V benchmarks, FlowCred consistently improves matched joint-training baselines. On LTX-2.5, FlowCred improves a strictly matched joint-training control from 61.47 to 64.46 on T2V-CompBench and from 55.58 to 58.08 on StoryEval, without increasing decoded-video or reward-model-call budgets. Factorial and realized-update analyses show complementary contributions from prompt shaping and generator routing, while human evaluation and transfer across backbones and updater families provide further supporting evidence.","authors":["Mingxuan Zhu","Yanwei Huang","Shiyuan Liu","Xinzhi Zhang","Shujie Li","Yuanxing Zhang","Lu Chen"],"published":"2026-10-13T10:48:01Z","updated":"2026-10-13T10:48:01Z","abstract_url":"https://arxiv.org/abs/2610.18142v1","html_url":"https://arxiv.org/html/2610.18142v1","pdf_url":"https://arxiv.org/pdf/2610.18142v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18125v1","title":"H-DDCM: Hadamard Codebooks for Fast Generative Image and Video Compression","abstract":"Training-free diffusion-based compression methods repurpose the generative priors of a diffusion or a flow model to compress data without retraining them as task-specific codecs. Recent codebook-based approaches such as Turbo-DDCM achieve strong perceptual quality at ultra-low bitrates, but their reliance on dense Gaussian codebooks remains costly in both memory and computation, and scales poorly with the large latent dimensions of modern image and video generators. Their combinatorial bitstream encoding further becomes computationally heavy at this scale. We introduce H-DDCM, a scalable generative compression framework that replaces Gaussian codebooks with implicit randomized Hadamard dictionaries. The fast Walsh-Hadamard transform allows for implicitly synthesizing full-dimensional dictionaries with $O(d \\log d)$ compute for projection and reconstruction and $O(d)$ memory, without materializing the full-dimensional dictionary. We further introduce an efficient table-free lexicographic coding scheme that makes combinatorial encoding practical at larger dimensions. Beyond images, we adapt the framework to an autoregressive video flow model and develop a streaming compression scheme that periodically re-encodes recently reconstructed frames into a fresh KV-cache prefix, preserving temporal context across segments at no additional transmitted bits. This enables long-form, close to real-time generative video compression on a single GPU. Across image and video benchmarks, H-DDCM achieves competitive rate-distortion-perception performance while substantially reducing the memory and computational overhead of codebook-based training-free generative compression.","authors":["Or Ronai","Vladimir Kulikov","Tomer Michaeli"],"published":"2026-10-13T10:36:58Z","updated":"2026-10-13T10:36:58Z","abstract_url":"https://arxiv.org/abs/2610.18125v1","html_url":"https://arxiv.org/html/2610.18125v1","pdf_url":"https://arxiv.org/pdf/2610.18125v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18110v1","title":"SYNPRED: A Synergistic Approach to Multimodal Learning for Clinical Prediction","abstract":"Multimodal medical data captures complementary aspects of disease. It provides a comprehensive basis for diagnosis and the identification of biological associations linked to progression or treatment response. Established contrastive learning approaches exploit shared information across modalities, but fall short in exploiting complementary, modality-specific signals relevant for a task. Here, we propose a synergistic multimodal variational autoencoder (VAE) framework that separates task-relevant unimodal and multimodal information from instance-specific variation task-irrelevant, allowing complementary signals across modalities to be leveraged for prediction. The method yields benefits even if modalities are missing at test time. We evaluate the method on a treatment response prediction task using medical imaging and RNA data. Empirical comparison with alignment-based and multimodal VAE state-of-the-art approaches demonstrates improved multimodal prediction performance, and consistent benefits for prediction from a single modality after multimodal training. The full code can be found here: https://github.com/cirmuw/SYNPRED.","authors":["Ivana Janíčková","Yen Y. Tan","Thomas H. Helbich","Philipp Seeböck","Julieta Di Marco","Zsuzsanna Bago-Horvath","Ulrike Heber","Thomas Spiegel","Georg Langs"],"published":"2026-10-13T10:24:09Z","updated":"2026-10-13T10:24:09Z","abstract_url":"https://arxiv.org/abs/2610.18110v1","html_url":"https://arxiv.org/html/2610.18110v1","pdf_url":"https://arxiv.org/pdf/2610.18110v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18097v1","title":"APT: Feedback-Driven Agentic Post-Training for Text-to-Image Generation","abstract":"Post-training is crucial for improving text-to-image models, yet existing pipelines typically rely on manually curated training data and fixed training distributions. We introduce APT (Agentic Post-Training), a fully automated framework that adaptively post-trains a base model according to its evolving capability profile. APT coordinates three agents to construct evaluation sets from user requirements, diagnose model-specific strengths and failure modes, and generate reinforcement learning data with an adaptive prompt distribution that emphasizes underperforming capabilities. By repeatedly evaluating, diagnosing, and updating the generator, APT lets the current model's behavior shape its next training tasks, forming a feedback loop inspired by recursive self-improvement. For general-purpose settings without user-specified evaluation scenarios, we further develop an evaluation harness that enables broad and diverse evaluation set generation. Experiments across multiple base models, benchmarks, and generation architectures demonstrate that APT is model-agnostic, benchmark-agnostic, architecture-agnostic, and fully automated.","authors":["Sirui Zhang","Fangyun Wei","Dong Chen","Jinjing Zhao","Yitong Wang","Yunuo Chen","Baining Guo","Zheng-Jun Zha"],"published":"2026-10-13T10:14:23Z","updated":"2026-10-13T10:14:23Z","abstract_url":"https://arxiv.org/abs/2610.18097v1","html_url":"https://arxiv.org/html/2610.18097v1","pdf_url":"https://arxiv.org/pdf/2610.18097v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18072v1","title":"LensErase: A Foundation Model for Erase Anything","abstract":"We introduce LensErase, a general-purpose mask-based Erase Anything foundation model designed to cover a broad spectrum of real-world erase scenarios. LensErase supports diverse objects, visual text, watermarks, associated visual effects, multiple-object removal, and a wide range of object scales, aspect ratios, and image resolutions. First, to enable such broad coverage, we construct LensErase-100M, a large-scale dataset containing 101.07 million paired source-mask-target examples spanning diverse erase scenarios. Second, we pretrain LensErase from the text-to-image model Lens, adapting its strong generative prior to mask-based erasing. To efficiently incorporate the source image and erase mask, we propose Mask-Aware RoPE, a 3D rotary positional encoding that directly injects mask information into the source-image tokens without introducing a separate mask token sequence. Finally, we refine the model through supervised fine-tuning and reinforcement learning with contract-guided, region-aware rewards, and apply TraceFusion at inference to preserve high-fidelity content outside the effective edit region. Across six public benchmarks and the proposed LensErase-Bench, LensErase achieves substantial improvements under both reference-based objective metrics and reference-free VLM evaluation. We hope LensErase can serve as a foundational model for erase-related applications and systems.","authors":["Yunuo Chen","Xiuyu Wu","Qinhong Yang","Jinjing Zhao","Yanchen Dong","Sirui Zhang","Dong Chen","Fangyun Wei","Lei Shi","Ji Li","Dongdong Chen","Guo Lu","Yan Lu","Baining Guo"],"published":"2026-10-13T09:56:02Z","updated":"2026-10-13T09:56:02Z","abstract_url":"https://arxiv.org/abs/2610.18072v1","html_url":"https://arxiv.org/html/2610.18072v1","pdf_url":"https://arxiv.org/pdf/2610.18072v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18038v1","title":"Data-Free Continual Learning for World Action Model with Rectified Generative Replay","abstract":"World action models (WAMs) built on pretrained video generation models adapt quickly to new robotic tasks, but they forget previously learned tasks under sequential fine-tuning. Experience replay (ER) mitigates such forgetting by rehearsing data of previous tasks, yet this data is often unavailable in robotics, where a policy is deployed as weights only and its training data is not shared along with it. In this work, we ask whether a WAM can achieve data-free continual learning by regenerating its own past. Our key observation is that a WAM can indeed autoregressively regenerate complete rollouts of previously learned tasks and replay them to mitigate forgetting. However, replaying such raw rollouts still lags far behind replaying real data, which we attribute to two issues. First, the WAM is unable to recognize task completion and keeps generating purposeless motion after the task is done. Second, under open-loop generation, the generated actions gradually drift away from the generated observations. To address both issues, we present rectified generative replay (R$^2$-WAM), which truncates generated rollouts at task completion with an agentic evaluator and filters out rollouts whose actions are physically inconsistent with the observations. On the four LIBERO suites and five real-world tasks, R$^2$-WAM reduces forgetting by over 90% relative to sequential fine-tuning and nearly matches ER without accessing any data from previous tasks. Our analysis further reveals that forgetting in WAMs concentrates in inverse dynamics modeling: a forgotten WAM still produces visually plausible observations of previous tasks while its generated actions fail.","authors":["Kaipeng Fang","Hangxu Liu","Chaojian Shi","Yunsong Zhou","Hongzi Zhu","Minyi Guo","Jingkuan Song","Lianli Gao"],"published":"2026-10-13T09:27:32Z","updated":"2026-10-13T09:27:32Z","abstract_url":"https://arxiv.org/abs/2610.18038v1","html_url":"https://arxiv.org/html/2610.18038v1","pdf_url":"https://arxiv.org/pdf/2610.18038v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18034v1","title":"COMPASS: Contextual Moment Prior Alignment for Generalizable AIGI Detection","abstract":"Generalizable AI-generated image (AIGI) and deepfake detection remain challenging due to the asymmetry phenomenon, where adaptation to limited training distributions can degrade the transferable representations of Vision Foundation Models (VFMs). Recent subspace adaptation methods mitigate this issue by freezing high-magnitude principal components while adapting the residual subspace. However, such magnitude-based decomposition is data-agnostic and does not explicitly account for target-relevant semantics, potentially leading to semantic misalignment. We propose COMPASS (COntextual Moment Prior Alignment for Subspace Separation), a data-aware subspace adaptation framework that uses a small unlabeled Semantic Proxy Set to estimate target activation statistics. COMPASS incorporates activation covariance into the decomposition of pre-trained weights, preserving target-relevant representations as a stable semantic reference while the residual adapter learns forgery-related variations. The proxy calibration requires no gradient-based optimization. Extensive experiments demonstrate strong generalization across cross-dataset, cross-method, joint cross-dataset-method, and open-world cross-generator evaluations, achieving state-of-the-art performance on both Deepfake and AIGI detection benchmarks.","authors":["Zhan Yang","Tiancheng Shen","Weijie Lyu","Shuo Chen","Bernard Ghanem","Yibo Yang","Ming-Hsuan Yang"],"published":"2026-10-13T09:23:12Z","updated":"2026-10-13T09:23:12Z","abstract_url":"https://arxiv.org/abs/2610.18034v1","html_url":"https://arxiv.org/html/2610.18034v1","pdf_url":"https://arxiv.org/pdf/2610.18034v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18030v1","title":"FlowSim: Rendering-Free Closed-Loop Simulation for Evaluating End-to-End Driving Systems","abstract":"Closed-loop evaluation of end-to-end (E2E) driving systems typically relies on generating sensor observations and re-processing them through the perception encoder, introducing substantial computational cost and a sim2real gap between simulated and real sensor observations. In this paper, we ask a more fundamental question: is image-space simulation necessary for closed-loop evaluation of E2E driving systems? We propose FlowSim, a rendering-free simulation paradigm that predicts the internal latent representation directly from a previous latent and target-frame symbolic scene conditions. The predicted latent is then processed by the original frozen downstream modules, eliminating image rendering and perception re-encoding. Explicit cross-frame agent association improves latent transition prediction and rollout stability, while variable-horizon simulation enables long-horizon prediction from a common real anchor without accumulating intermediate rollout errors. Experiments on nuScenes and NavSim demonstrate that FlowSim preserves downstream behavior competitively with, and often exceeds image-space simulation in source-to-reference agreement across variable simulation horizons and both dense and sparse latent representations. By predicting the latent directly, both instantiations of FlowSim simulate each step in 0.04--0.06s, substantially faster than the image-space simulation methods they are compared against. These results establish FlowSim as an efficient and practical alternative to conventional image-space simulation methods.","authors":["Hanfeng Wu","Alvaro Marcos-Ramiro","Michael Schmidt","Christoph Stiller"],"published":"2026-10-13T09:21:40Z","updated":"2026-10-13T09:21:40Z","abstract_url":"https://arxiv.org/abs/2610.18030v1","html_url":"https://arxiv.org/html/2610.18030v1","pdf_url":"https://arxiv.org/pdf/2610.18030v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"},{"id":"2610.18018v1","title":"Dynamic Interpolation for Training-Time Prediction Reshaping in Low-Light Image Enhancement","abstract":"Low-light image enhancement (LLIE) is an important image/video processing problem for reliable visual systems under poor illumination, yet it remains challenging due to the strong coupling among insufficient illumination, noise amplification, and structural degradation. Existing methods typically rely on sophisticated network architectures or engineered objective functions. While effective, the former increases model complexity and deployment burden, whereas the latter relies on empirically tuned loss weights. We revisit supervised LLIE from a training-dynamics perspective and observe that brightness-related errors tend to converge early, while residual noise and structural artifacts often remain insufficiently optimized in later stages. To address this issue, we propose a Dynamic Interpolation Training-only Module (DITM), which introduces no additional learnable parameters and adaptively reshapes the model prediction for supervised feed-forward LLIE training. Specifically, DITM employs brightness-aware interpolation, in which the model prediction is combined with a mean brightness-aligned image constructed by rescaling the model prediction according to the mean brightness of the ground-truth image. By reducing the relative dominance of global brightness discrepancy, DITM makes residual local errors more influential during backpropagation after global luminance has largely stabilized, thereby facilitating artifact suppression and fine-detail restoration in later training stages. DITM is used only during training and is fully removed at inference, introducing no additional inference cost. Extensive experiments on multiple benchmark datasets and CNN-, Transformer-, and Mamba-based LLIE backbones show that DITM consistently improves fidelity and perceptual quality while preserving the inference-time architecture and introducing no additional inference-time computation.","authors":["Peirui Zhu","Shijie Hao","Jingxi Liao","Richang Hong","Meng Wang"],"published":"2026-10-13T09:14:49Z","updated":"2026-10-13T09:14:49Z","abstract_url":"https://arxiv.org/abs/2610.18018v1","html_url":"https://arxiv.org/html/2610.18018v1","pdf_url":"https://arxiv.org/pdf/2610.18018v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-10-14T05:43:07+00:00","last_seen_at":"2026-10-14T05:43:07+00:00"}],"tracked_paper_count":69,"storage_mode":"latest_overwrite"}};
